/* 平成16年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h16.committeeSessions.push(...[{"id":"h16-20040309-3","meetingId":"h16-c-budget","date":"2004年3月9日","dateIso":"2004-03-09","committee":"予算特別委員会","time":"午前１０時０４分～午後６時３２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を187件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"おはようあります。本日もよろしくお願いをいたします。私は１５０ページ、総務管理費のうちの町会関係についてお伺いしたいと思います。そこで、最初にお伺いしたいのは、先ほど伺いました区からはどのような形で何件ぐらい町会に仕事を頼んでいるのか、また、区の理事者の方、部署でもどなたがそれを把握し、指導しているのか、お聞かせください。","respondent":"志村地域活動課長","answer":"私どものほうの地域活動の重要な担い手だと考えています町会の方々、町会、自治会ですけれども、定例的には毎月５日と２０日、これを文書配付日と定めておりまして、各地域センターからそれぞれの町会長のところに私ども行政の文書等々ありますので、これの配送といいますか。","voiceIndex":4,"id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"ＰＴＡなんかは教育委員会もかかわり合っていると思うんですけれども、総体的に今おっしゃったのは、地域センターというフィルターを通して町会の方に仕事の依頼をするということなんですが、それ以外にちょっと申し上げましたように、ＰＴＡ、学校などは地域センターとはまたかかわりのない部分があるんですが、そこの部分とあわせた数、ちょっとおわかりにならないというご答弁だったんですが。","respondent":"志村地域活動課長","answer":"すみません。今調べていますので、ちょっとお時間をいただけますでしょうか、申しわけありません。","voiceIndex":8,"id":"exchange-002"},{"speaker":"大沢委員","kind":"質問・要望","question":"できれば、数はちょっと教えていただきたいということです。今、手元に資料がないということなので、入り次第お願いいたします。それと、先ほど町会、自治会というようなお話が出ましたけれども、自治会の目安といいますか、自治会とはというものについてちょっとお伺いをしたいと思います。よろしくお願いします。","respondent":"志村地域活動課長","answer":"ただ、私ども行政の施策を進める上においては、そこのいわゆる地域を代表される、コミュニティを代表される団体だということで、それぞれ扱いは同じです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"今、都営ということで、区営は自治会というのは持ち合わせていないんでしょうか。区営はあるのかないのか、ちょっとすみません、勉強不足で申しわけないんですが、お願いいたします。","respondent":"志村地域活動課長","answer":"現在、区営住宅の自治会というのはございません。〔「あるよ」と呼ぶ者あり〕町会に入っている自治会はございません。すみません。","voiceIndex":13,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"町会に入っている、それは区営の場合は町会の中に内包されているということで認識してよろしゅうありますでしょうか。","respondent":"志村地域活動課長","answer":"それぞれありますので、全部そうだというわけではございませんで、それぞれの町会の中に入っている自治会もありますし、そうでないのもあるということなんですけど、今のところは単独で自治会を構成しているというところはないということです。","voiceIndex":15,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"区営のほうは単独でというのはないということでしょうか。区営のほうは単独でないということを今おっしゃっているんでしょうか。","respondent":"志村地域活動課長","answer":"すみません。区営住宅で、単独で私どもの区政協力委員となっている自治会はないです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"区政協力委員となっている自治会がないということは、区政協力委員イコール町会長だというふうな私、認識があるんですが、その自治会長なりが出てきてはいないんでしょうか。すみません。ちょっと手でこね過ぎまして、わからなくなったんですけれども。先に進まないので、自治会は何戸以上を自治会というふうに定義をされるんでしょうか、お願いいたします。","respondent":"志村地域活動課長","answer":"何人だから自治会として認めないとかという、そういう規定はございません。あくまでも任意の団体だです。","voiceIndex":19,"id":"exchange-007","title":"町会・自治会支援"},{"speaker":"大沢委員","kind":"質問","question":"ちょっとあるところから伺ったんですけど、１００戸ぐらいが目安ということを伺ったんですが、それの真偽はどうなんでしょうか。","respondent":"志村地域活動課長","answer":"いろいろ形態があります。例えば大規模な住宅もありますし、小さいのもあります。ですので、目安といいますか、その辺は非常に難しゅうありますので、それはそれぞれの団体がお決めになるというふうに考えてあります。","voiceIndex":21,"id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"今の集合住宅のことなんですが、先ほど申し上げましたように、町会に参加をしているという部分では、集合住宅の方が非常に参加をされている方が、集合住宅のほうから例えば集合住宅という単位で町会に参加をしていない部分が非常に多いような感じを私は持つんですけれども、区営、都営、そういう公的な集合住宅以外に私の企業が建てた住宅があるんですが、そういうものに対しては。","respondent":"志村地域活動課長","answer":"せんだってございました西五反田の集合住宅ですけれども、こうした説明会のときには、建設というか、入居の折には、地元の町会に入っていただくようにというお知らせはしています。","voiceIndex":23,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"協力的なところは町会活動がスムーズにいっているんですけれども、非協力的なところは非常にまるっきり知らないよ、知らないよというとちょっと語弊があるかもしれないんですが、非常に関心が薄いということなので、そこのところの関心をもうちょっと盛り上げていただくために、先ほどお知らせをしているということなんですが、何か行政の側で一定の枠組みみたいなものを設けることはできないんでしょうか。","respondent":"志村地域活動課長","answer":"いろいろ大変難しい問題があります。それで、私ども地域のコミュニティ活動ということで、今年、平成１６年度もふれあいサポート活動等々を進めていきたいと思ってあります。","voiceIndex":25,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問・要望","question":"非常に難しいことはわかりました。これは質問ではないので、要望ということで、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"三上委員","kind":"確認","question":"ちょっと確認します。先ほどの答弁の中で、区営住宅では自治会、区政協力委員になっている人はいないということでよろしいんでしょうか。","respondent":"志村地域活動課長","answer":"先ほどご答弁しましたとおり、区営住宅の自治会として、区政協力委員となっている団体自治会はないです。","voiceIndex":31,"id":"exchange-012"},{"speaker":"三上委員","kind":"質問","question":"ということは、あるということでしょう。だから、そういう中途半端なことを言われると困るわけですよね。ですから、区営住宅だって、そういうような形であると。住んでいる人たちが働きかけがないという。だから、それについては、品川区から働きかけをしてもらわない限り、なかなか広がっていかないんじゃないかな、こういうふうに思うんですけど、いかがでしょうか。","respondent":"志村地域活動課長","answer":"先ほど申し上げましたように、私どもは例えば建設の説明会等々からそういった働きかけは行ってありますけれども、これはあくまでもそうした意味では、そちらの団体等がそうした意思を持っていただけるまで私どものほうで働きかけを。","voiceIndex":35,"id":"exchange-013"},{"speaker":"三上委員","kind":"質問・要望","question":"ありがたいなと思いながらね。建設型だったら、まだ直接働きかけというのがあるかもわかりませんけど、そういう部分についての、やはりきめ細かな働きかけというものをこれから一生懸命ちょっと取り組んでいただきたいと、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"１５９ページのインターネット美術館、それから１６３ページの区政資料、１６５ページのインターネット経費について、手短にご質問いたします。区政資料ですが、事務事業評価ではＢランクになっております。この１６３ページを開きますと、区政資料等の中で４項目ありますが、例えば、「グラフしながわ」発行については、ランクはいかほどになりますでしょうか。","respondent":"山田広報広聴課長","answer":"そういった意味では、「グラフしながわ」についても、同じようなレベルを落とさずに、区民の皆様に愛されておりますので、レベルを落とさずに発行していきたいというふうに考えです。","voiceIndex":39,"id":"exchange-015"},{"speaker":"若林委員","kind":"質問","question":"これは数字を見ますと、１回８４５万円というふうにありますが、このグラフの内容を教えていただけますでしょうか。","respondent":"山田広報広聴課長","answer":"今般、先ほどもコミュニティのお話がございましたけれども、現在発行しております２５号については、コミュニティ新時代ということで、さまざまな地域の中で活躍をなさっている方々を取り上げてあります。","voiceIndex":41,"id":"exchange-016"},{"speaker":"若林委員","kind":"意見","question":"この年に１回、年に１冊という意味だと思います。何部発行されるのかここには出ておりませんが、８４５万円。その下の欄の「しながわガイド」と、私たち、区民の皆さんもよくご利用されるようなもの、ポスターとか、これでも８４０万円、それぞれ５００万円を超える、６００万円を超える、この経費のかけ方、こういうお金の使い方がいいのかどうかという問いかけを今しております。","respondent":"山田広報広聴課長","answer":"「グラフしながわ」につきましては、先ほどご説明させていただいたとおりです。「しながわガイド」につきましては、区民の便利帳ということで、これは転入の方には品川区の諸届けのあり方、制度について説明をしている役割を果たしています。","voiceIndex":43,"id":"exchange-017"},{"speaker":"若林委員","kind":"質問・要望","question":"わかりました。年に１冊、何部発行されるのかわかりませんが、８４５万円、ここら辺のお金の使い方、正しくして、もし直すところがあれば、要望をしておきます。続きまして１６５ページのインターネット経費、ホームページを品川区でつくっておられますが、例えば視覚障害を持った方等、こういう方に対してどのような工夫をされているのか、また、国や都からどういう指導をされているのか、お伺いいたします。","respondent":"山田広報広聴課長","answer":"レベル的には、インターネットで網羅している中身を「知っテル区ん」の中にも盛り込んむように努力をしながら進めているです。","voiceIndex":47,"id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"わかりました。総務省のほうでも、情報バリアフリーのためにホームページのつくり方、こういう基準、基準という言い方はないと思いますが、指導しているような部分がありますので、またしっかりとご検討いただきたい。最近３月に入りまして、厚生労働省のホームページで、音声読み上げ、文字拡大サービスがありますが、あれについての評価はいかがでしょうか。","respondent":"山田広報広聴課長","answer":"音声につきまして、私どものほうも大変興味を持って事業者のほうには聞いておりますけれども、まだ現在いわゆる受け手の部分の環境という点で、どこまで進んでいるかということもありますので、動きを私どもは注目していきたいというふうに考えてあります。","voiceIndex":49,"id":"exchange-019"},{"speaker":"若林委員","kind":"質問","question":"動きを見ながら、よければ導入していくという考え方でいいですか。一応聞いておきます。","respondent":"山田広報広聴課長","answer":"もちろんそうしたさまざまな技術の発展に伴って利便性が高まるですので、これは積極的に取り上げられるときには取り上げてまいりたいというふうに考えてあります。","voiceIndex":51,"id":"exchange-020"},{"speaker":"若林委員","kind":"質問・要望","question":"わかりました。１年間の運営経費で１５９万９,０００円ということですね。それで、これから多分４月から見られるようになると思いますが、その内容とか構成でありますとか、また、見ていただきたいターゲットはどういうふうになりますでしょうか、お教え願いたいと思います。","respondent":"諸岡区民生活事業部副参事","answer":"そのほかには、常設展ということで、区に所蔵しております歴史館の所蔵品でありますとか、そういったものも常設展として掲示をしてご覧いただけるようにというふうに考えてあります。","voiceIndex":55,"id":"exchange-021"},{"speaker":"若林委員","kind":"質問・要望","question":"１５９万９,０００円、ちょっとこだわりますが。やはり本物を見ていただきたい。これも一つ非常に大事な視点で、もう一つ、やはりインターネット美術館をつくるのであれば、こういう都市型観光という、またそういう発想をされるのであれば、ぜひここら辺とリンクをしながら、インターネット上で美術と、またぜひ来ていただきたいという観光という意味で、そういう考え方はできませんでしょうか。","respondent":"諸岡区民生活事業部副参事","answer":"したがいまして、インターネット美術館の中には、「区内の美術館案内」というようなものを載せするとか、そのほか、美術館、近隣の美術館とリンクをさせてもらうとか、そのようなことも考えておりまして。","voiceIndex":57,"id":"exchange-022"},{"speaker":"若林委員","kind":"質問・要望","question":"昼のほうが多いんだ。すみません。逆でした。要するに、そういうことですよね。もっともっと品川に来ていただきたい。ぜひここら辺、各課、一つにまとまるのか、また、一致団結していくという言い方もありますので、ここら辺、そういう意味では、１５９万９,０００円の中でもっともっと広げて、内容を充実していっていただきたいな、このように要望したいと思いますが、お考えを伺います。","respondent":"山田広報広聴課長","answer":"これについては、インターネットをあちらもリニューアルするということもありますので、お互いにリンクを張りながらＰＲを強く進めてまいりたいというふうに考えてあります。","voiceIndex":59,"id":"exchange-023"},{"speaker":"菊地委員","kind":"質問・要望","question":"ホームページによりますと、２月２３日に締め切りということで、この改修工事、工事監理をする、包括委託をする企業、これを募っていたようですけれども、この目的とこれまでの体制とどういうふうに違っていくのかということをまずお聞きをしたいのが１点と、それから、品川区に登録をされている企業数、この企業数と、それからそのうち４５名以上の企業数を教えていただきたい。","respondent":"宍戸施設担当課長","answer":"プロポーザル以降の予定なんですけれども、まだ業者としては決定してございません。それから、何社から応募があったかということなんですけれども、１３社から応募がございまして、そのうち区内業者は２社でございました。","voiceIndex":62,"id":"exchange-024"},{"speaker":"菊地委員","kind":"質問・要望","question":"はい、わかりました。この目的なんですけれども、民間の力を借りるというような話がありましたけれども、今までも、これまでそれぞれ２０社に設計ですとか、仕事としてずっと回っていったんだと思いますけれども、包括業務委託をすることで、民間の力をかりていくというのは、今までとどこが違うのかちょっとよくわからないんですけども、その辺、もう少し詳しく教えていただきたいなというふうに思います。","respondent":"宍戸施設担当課長","answer":"今回、さまざまな先ほどお話ししたような理由で、今まで自前で職員が行ってきた部分に委託を進めてまいりましょうということで、これまで何百件も中小の事業者、設計事務所に委託をしていたものを取り上げて、大手１社に任せるというものでは決してございません。","voiceIndex":65,"id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"そうですか。確かに誤解をしておりました。その３０件余りは、これまでどおり他の実際にプロポーザルで包括業務委託をされた会社以外にこれは回っていくんだというふうにとらえてよろしいんでしょうかね。それで、実際に１２億１,５００万円、少なくともこれについては１社に回っていくことになりますよね。","respondent":"宍戸施設担当課長","answer":"もう一つちょっと誤解があるのではないかなと思うんですが、工事費についてです。今回委託をするのは、あくまでも設計の部分でございまして、工事はこれまで同様、区内の業者を中心にほぼ１件ごとに発注をしていくというものです。","voiceIndex":67,"id":"exchange-026"},{"speaker":"菊地委員","kind":"質問","question":"実際に職員の体制、品川区の技術職員の体制で言いますと、これからチェック体制そのものを一括で出していって、スケジュールを見ますと、工事というのは大体夏休み期間中、６月から９月ぐらいの間に集中をしてきますけれども、旧営繕課がありました時代、今廃止をされてそれぞれ技術職員はいろんな部署に入っているようですけれども、経理でこれだけの工事を発注していって、工事が集中した場合に。","respondent":"宍戸施設担当課長","answer":"が、３％か５％というふうな割合であろうというふうに思われます。それから、６月から９月に工事は集中するわけです。","voiceIndex":69,"id":"exchange-027"},{"speaker":"菊地委員","kind":"質問・要望","question":"実際にこれだけの工事が経理課に集中をしていくわけですから、ここでの職員体制、技術関係の職員体制というのは、ぜひとも強化をしたチェック体制をとっていただきたいのと、それとこれまで中小企業、小規模の設計屋が多いのかと思いますけれども、ここに回してきた仕事、これまでの体制と同時に少しでも幅が。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-028"},{"speaker":"本間委員","kind":"質問","question":"よろしくお願いします。私の場合には、まず１５５ページの職員研修費にわたる件、それから１５９ページ、水と緑の市町村との交流事業について、１６１ページに関して、生活安全推進事業について、それから１７３ページ、区民保養所経費について質問したいと思います。生活安全推進事業につきましては、一番最後のほうに質問したいというふうに思っています。最初に、職員研修費についてです。","respondent":"桑村人事課長","answer":"派遣研修ですけども、これはいわゆる他の市町村の研修ですとか、国内の都市派遣研修ですとか、いわゆる区の外の研修機関というようなところに派遣しているものです。大体５コースぐらい予定しているものです。","voiceIndex":73,"id":"exchange-029"},{"speaker":"本間委員","kind":"質問・要望","question":"やはり品川区は教育改革プラン２１を皮切りに、全体の質的向上を高めるためのさまざまな努力をされている分野もありますし、また、このように庁舎内で、やはり実力を高めていくというふうな素晴らしい研修があるようですが、教育の品川として一層、品川区はそれなりの評価はありますけども、常に他人に学ぶ。","respondent":"長田区民課長","answer":"例を申し上げますと、田植え体験とマス釣り、それからホタル観賞と渓流釣り、それからふるさと体験ホームステイ、こういった事業も実施をしてきました。そのほかに、虫とりと川遊び、工芸と山伏峠、かなりの事業を、これは例ですけれども、実施をしています。","voiceIndex":75,"id":"exchange-030"},{"speaker":"本間委員","kind":"質問・要望","question":"いろいろ学校の跡地なものですから、雨の日には体育館でいろいろそば打ちをやったり、室内のいろんな遊びができるですけれども、ちょっとこれは調べていただきたいというふうに思いますが、宅急便だとか、道具の出し入れのできるような方法は、この時期だからないことはないと思いますが、この部分で難が一つあります。次、１７３ページの区民保養所の部分にいきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-031"},{"speaker":"本間委員","kind":"質問・要望","question":"交流事業の部分につきましては、いろんな苦情もあるけれども、これからも宣伝に努めていただきたいということで、一応打ち切ります。そして、１７３ページの区民保養所経費、暖景苑のことについて、どのようなお考えでしょうかということでお尋ねします。","respondent":"長田区民課長","answer":"区民保養所についてのお尋ねです。区民保養所につきましては、昨日もお答えをしたとおり、暖景苑だけじゃなくて、すべての保養所を見直していくというようなことで、これから見直し作業に入ってあります。","voiceIndex":79,"id":"exchange-032"},{"speaker":"本間委員","kind":"質問・要望","question":"小さなことかもしれませんけども、お金を出して利用するわけですので、その辺の後味の非常に悪いものを残さないような対応を何とか期待したいなというふうに思っています。１６１ページ、生活安全推進事業に移らせていただきます。そのような観点からお尋ねします。生活安全サポート隊、我が町パトロール隊、この推進とありますが、この件について簡単に説明をしていただきたいと思います。","respondent":"杉浦生活安全担当課長","answer":"そういうことで品川区がつくった、そういう制度です。そこで、いち早く品川区がこういう治安の問題について部門をつくったということは、非常に意義あることというふうに考えております。","voiceIndex":81,"id":"exchange-033"},{"speaker":"本間委員","kind":"質問","question":"そのようなことで、私たちの街は自分たちで守るというようなことで地域の皆さんも一生懸命やろうと今していますが、やはり防火のための安全システム、この近隣セキュリティシステム導入調査ですが、この老夫婦だとかひとり暮らしの部分では、たしかガス漏れ警報機を民生委員の方がおつけになったりするようなことがありますが、その他、そういうふうな痴呆になったとか。","respondent":"杉浦生活安全担当課長","answer":"今後、ＮＰＯと、そういった意見を出し合いながら火災にも使えるんじゃないかと、どういう使い方がいいのかということを考えながら開発に生かしていきたいというふうに考えております。","voiceIndex":83,"id":"exchange-034"},{"speaker":"本間委員","kind":"質問・要望","question":"いずれにしましても地域の皆さんと防犯、防火の部分での接点を持っていただきたいというふうに思います。そのようなこともございましたものですから、防犯と防火、それぞれ地域で一体となった連携をとった部分が、日常の中から行われていないと未然にそのような危険を防ぐことができないだろうという観点からお尋ねいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-035"},{"speaker":"本多委員","kind":"質問・要望","question":"１６５ページの契約関係事務費について、３３９万３,０００円、この内容について教えていただきたいと思います。","respondent":"西島経理課長","answer":"さらに来年度につきましては、２年に１回の業者の登録の更新がありますので、その入札参加申込書の作成、業者登録システム、セットアップ代等がこれに含まれてあります。","voiceIndex":87,"id":"exchange-036"},{"speaker":"本多委員","kind":"質問・要望","question":"それぞれ契約に必要な事務費ということなんですが、契約の案件、件数ですね、件数に対して当然それぞれに契約するということなんですが、例えば契約変更とか、そういったものが生じる場合も含めた予備費など、そういったものがこの中に含まれているのかどうなのか、再契約とか、そういった契約変更とか、そういった部分について教えていただきたいと思います。","respondent":"西島経理課長","answer":"先ほどお話ししましたのは、経理課で所管している契約に係わる事務費でございまして、仮に契約変更等が発生した場合は、それぞれの所管の工事であれば工事費の中、それから設計であれば設計委託費の中に含まれているです。","voiceIndex":89,"id":"exchange-037"},{"speaker":"本多委員","kind":"質問・要望","question":"ここ２年間ぐらい続けまして、夏休み前に作業が集中したと思うんですが、契約が非常にその時期に重なるということがあったと思うんですが、夏休みというと非常に日程が比較的長いものですから、どうしてもこういった時期に集中するとは思うんですが、当然夏休みというのは日にちが最初から決まっておりますので、こうした包括業務委託によりまして。","respondent":"宍戸施設担当課長","answer":"今回包括業務委託ということで来年度から開始したいと考えていますが、これも大きな目的の一つです。","voiceIndex":91,"id":"exchange-038"},{"speaker":"本多委員","kind":"質問・要望","question":"契約というところで関連しまして、大崎地区の小中一貫校の設計変更について教えていただきたいと思うんですが、こちらも設計プロポーザルを採用しました。教育内容には支障がないということなんですけれども、この変更したということで、契約上は発注者側からの変更というところなんですけれども、その辺についての考え方、また契約金額に対する追加金額、その辺についてご説明をお願いしたいと思います。","respondent":"宍戸施設担当課長","answer":"小中一貫校の実施設計ですが、当初平成１５年７月２４日に契約しています。一応工期、その後、一度工期変更いたしまして、今ご指摘がありました設計業務の内容変更ということで、１月２０日に変更しています。","voiceIndex":93,"id":"exchange-039"},{"speaker":"本多委員","kind":"意見","question":"はい、追加金額、わかりました。非常にこうした変更に対するいろんなご意見があると思うんですけれども、半年前に計画概要が公に示されて、それ以前は当然その施設の検討委員会などによりまして、協議会を経て積み上げてこられました。そうしたやはり関係者にも説明がなかったというふうに聞いておりますが、その辺について、改めてお願いしたいと思います。","respondent":"宍戸施設担当課長","answer":"今回小中一貫校の工事説明会というふうなことで、東京都紛争予防条例に基づく説明会を１２月５日にいたしました。","voiceIndex":95,"id":"exchange-040"},{"speaker":"本多委員","kind":"質問・要望","question":"それはそれなんですが、やはり、こうした品川区のしっかりした、何年もかけて計画をされてきました施設検討委員会の方たちも、非常に何年もかけてやってきたものを、積み上げてきたものを、全く説明がなく、あれっというような状況があるんですが、その辺に対しまして、当然公には半年前から示されていたわけですから、その辺のちょっと考え方を教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-041"},{"speaker":"本多委員","kind":"提案","question":"当然今後の一貫校計画を進めるに当たりまして、あらゆる点で総合的に配慮をした上で提案をされることを望みますが、当然もちろん近隣に配慮もし、また、関係者にも配慮をした上でしっかりしたものを提案されまして、変更というものが最大限ないようにお願いしたいと思うんですが、そういった意味では、当然設計に委託をするということではプロポーザルで提案型ということなんですけれども、この先。","respondent":"古川教育次長","answer":"今回の大崎地区におきます小中一貫、これの基本設計の段階、先ほど庶務課長が申し上げました。昨年の３月に一定の検討をし、基本設計をし、そして実施設計を踏まえ、これから着工と、こういう段階で一定の変更です。","voiceIndex":103,"id":"exchange-042"},{"speaker":"藤原委員","kind":"質問","question":"私は１６１ページの生活安全サポート隊活動費と我が町パトロールの推進の２点についてお伺いします。この２点に共通するのは、やはり所轄警察とのパイプということだと思うんですが、去年の９月か １０月に生活安全担当課といいますか、課が新しく新設されましたが、その辺からお伺いします。その抱負などは軌道に乗ってきたでしょうか。","respondent":"杉浦生活安全担当課長","answer":"１,２００万人から３２万人というお話ですけれども、これは全く安全を確保するという私の仕事には変わりありませんので、使命感を持って引き続き取り組んでいきたいというふうに考えております。","voiceIndex":106,"id":"exchange-043"},{"speaker":"藤原委員","kind":"質問","question":"この課をつくっていただいて、つくってきていただいたことのいろいろ仕事がある中で、所轄警察とのパイプをつくるという仕事が、仕事の中の重要な一つだと思うんですけれども、今までは所轄警察に連絡、電話等をするときは、警視庁の管理官という立場で連絡をしていたと思うんですけれども、今は品川区生活安全課課長としてかけると思うんですけれども、そのときの所轄の署の対応の仕方というのは。","respondent":"杉浦生活安全担当課長","answer":"人と話をするときには、やはり階級とか立場とかというよりも、人間としてお話をしたほうが気持ちが通じるのかなという気がいたします。したがって、何もその辺のところも変わることはございません。","voiceIndex":108,"id":"exchange-044"},{"speaker":"藤原委員","kind":"意見","question":"５カ月過ぎて、都民、区民への安全を守るのは命がけでやる抱負は変わらないということなんですけれども、いずれ課長も警視庁に戻られてしまうと思うんですけれども、何かここに配属されているうちにこれだけは残しておきたいというものが何かありましたらお知らせください。","respondent":"杉浦生活安全担当課長","answer":"ここのところはせっかく世の中がこのように関係機関が一体となって安全を確保していこうということで立ち上がってまいりましたので、何とかこれに道をつけて、そして定着させていきたいというふうに考えております。","voiceIndex":110,"id":"exchange-045"},{"speaker":"藤原委員","kind":"質問","question":"ここで生活安全サポート隊についてお伺いしますが、まず３名から１０名に変更になったということですが、この人数が増えることによって得られる効果と、１０人の配属はどのようになっているのかお知らせください。","respondent":"杉浦生活安全担当課長","answer":"非常に品川区、それほど広くないとはいうものの、３人で到底足りるものではありません。","voiceIndex":112,"id":"exchange-046"},{"speaker":"藤原委員","kind":"質問","question":"次は、我が町パトロールの推進についてお伺いしますが、この方たち、どのような方が参加していただけるのか、それと大体でいいんですけど、年齢層がわかれば教えていただけますか。","respondent":"杉浦生活安全担当課長","answer":"年齢の話ですね。年齢につきましては、一応８０歳、９０歳というのはどうもよろしくありませんので、そういうことで原則として６５歳ぐらいでお願いできたらいいなというふうに意向は伝えてあります。","voiceIndex":114,"id":"exchange-047"},{"speaker":"藤原委員","kind":"質問","question":"今なぜ年齢を伺ったかといいますと、６５歳以上の方でもお若い方はいっぱいいらっしゃると思うんですけれども、考え方なんですけれども、いわゆる犯人等をつかまえるとか、そういうことよりも、まず自覚を持っていただく、防犯の自覚を持っていただくという意味合いが強いんだと思うんですけれども、自覚とそれと防犯パトロールと地域とのコミュニティ、連携だと思うんですが。","respondent":"杉浦生活安全担当課長","answer":"自覚と連携、ちょっと難しいあれなんですけども、やはり、この我が町パトロールの目指すところは、パトロールしている姿を内外に見せると、先ほども申し上げましたけれども、そういうことで得られる効果というものを大きく期待しているわけでありまして、ぜひそういった意味で。","voiceIndex":116,"id":"exchange-048"},{"speaker":"武内委員","kind":"質問・要望","question":"質疑に入ります前に、委員長にご許可をお願いしたいと思いますが、質疑の途中で資料を指し示しながら質疑をさせていただきたいと思います。私は総務費の１６１ページのふれあい掲示板管理費についてお伺いをいたしたいと思います。このふれあい掲示板管理費ですが、どういった役割を担っているのか、また、その使用目的についてご説明を願いたいと思います。","respondent":"志村地域活動課長","answer":"ふれあい掲示板です。これにつきましては、街のいわゆるコミュニティの活動の促進を図りたいということで、これまで続けておりました掲示板を平成４年からコミュニティのより密接したものにしたいということで、地域の情報伝言板と見直したところです。","voiceIndex":123,"id":"exchange-049"},{"speaker":"武内委員","kind":"質問","question":"品川生活と健康を守る会という団体のチラシですけども、これが上の段に張ってありましたもので、一応こういう形でちょっと写真を撮ってあるんですけども、これに対して、先ほどのご答弁だと、行政のお知らせ等ということなんですが、このチラシは行政のそういったご許可とか了解はとられていらっしゃいますでしょうか。","respondent":"志村地域活動課長","answer":"掲出をご希望される方につきましては、地域センターで私ども日付印の入りましたスタンプを掲出期限内までということで表示をしています。ですので、その承認の印のないものは私どものほうでそういう意味で承認したものではないという理解です。","voiceIndex":127,"id":"exchange-050"},{"speaker":"武内委員","kind":"確認","question":"ちょっと小さくて恐縮なんですけど、これを見る限りは、そうした承認の印が書いていないわけです。いわゆる先ほどありました区の行政のお知らせですね、許可がないということなんですけども、これを受けまして、先日私どもの同僚議員が区のほうにこういった報告というか、お知らせをしたんですけども、その後これについて、何か区のほうで確認されたことはありますでしょうか。","respondent":"志村地域活動課長","answer":"大変申しわけありません。ちょっとその件とは別件かと思いますけど、実は区民の声ということで、ちょっと古いポスターが張ってあるじゃないかという苦情をいただいたものですから、私どものほうでは月２回所長会等を行ってあります。","voiceIndex":129,"id":"exchange-051"},{"speaker":"武内委員","kind":"確認","question":"ご答弁ありがとうあります。これについては、具体的に私どもの同僚議員がご報告申し上げたと思うんですけど、それに対して、ここに電話番号も書いてありますが、何か具体的に確認をされたとか、そういったことがあるかどうか、お願いいたします。","respondent":"志村地域活動課長","answer":"すみません。その件につきましては、たしかお電話をいただきまして、担当している地域センターの所長に現場を確認させました。それで、確かに私どもで先ほど申しました承認されているものが張ってありませんでしたので、直ちに撤去させたものです。","voiceIndex":131,"id":"exchange-052"},{"speaker":"武内委員","kind":"確認","question":"これについて、私のほうでちょっとあえてご報告はしていませんけれども、そういった部分で、この品川生活と健康を守る会ですけども、この会の概要等を区は確認されていらっしゃいますでしょうか。","respondent":"志村地域活動課長","answer":"その件の内容については、承知してございません。","voiceIndex":133,"id":"exchange-053"},{"speaker":"武内委員","kind":"確認","question":"確認されていないということですけども、実は私の地域の方で、このチラシを見て、豊町三丁目会館に実際に行かれまして、というのは、やはりいろいろご質疑にあるとおり、都営住宅はなかなか入れません。そうしましたら、いわゆるこういった会費の納入袋というのがありまして、これは多分強制ではないんですけれども、勧められたそうです。私どももほんとうに。私が質疑者なので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-054"},{"speaker":"武内委員","kind":"質問・要望","question":"そういう質問がありました。実際に私のところにもそういうチラシが張ってあって、これはそこに行くと、都営住宅が有利になるのかというご質問があって、それはないということでもちろん伝えておりますが、そういった誤解を生じることもありますので、区のほうとしてしっかりそうしたことを徹底管理していただきたいというふうに思いますが、この件について、どのように思いますでしょうか。","respondent":"太川区民生活事業部長","answer":"ただいま担当課長のほうから説明いたしましたけれども、ふれあい掲示板はあくまでも区からのお知らせの部分と、それからあと、行政の部分でも、あいている場合はコミュニティの関連の部分ということでお使いいただくというものです。","voiceIndex":137,"id":"exchange-055"},{"speaker":"武内委員","kind":"質問・要望","question":"ぜひ徹底していただきたいとともに、連絡先もありますので、ぜひちょっと事実確認をしていただいて、やっぱり区民の方、こういう形で張ってありますと、確かにこういったところで手続すれば、またそういった相談会に行けば、都営住宅に入れるんじゃないかと勘違いされて行かれる方が多うありますので、ぜひその辺をしっかり行政としてよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-056"},{"speaker":"鈴木（真）委員","kind":"質問","question":"契約管理費の契約関係事務費のほうでいきます。先ほど来、お二人質疑がございました中で、ご答弁の中に小規模設計事業者のグループ化も視野に入れていくというお話がお答えいただいております。要するに、これは品川区の中小企業者にとって仕事が回ってくるという、仕事の受注が入るということで、そういうお答えでいいんでしょうか。その点を。","respondent":"西島経理課長","answer":"第２弾が予定していますので、その際には区内の中小規模の設計業者が十分参加できるよう配慮してまいります。","voiceIndex":141,"id":"exchange-057"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほど参加基準達成が区内４社しかないという状況のお話が出た。この公募型設計プロポーザル要領の中に、その一つに金額もありますけど、過去５年以内に５件以上の公共施設改修工事の設計、または管理業務委託があるということが条件になっている。大もとにそこがあるんですが、こういうところも見直しを考えていただけるのかなということでお聞きしたいと思います。","respondent":"西島経理課長","answer":"いずれにいたしましても、次回の発注の際には、その辺も十分施設担当課長のほうと協議いたしまして、区内の中小企業の方にも仕事が回るように配慮してまいりたいと考えています。","voiceIndex":143,"id":"exchange-058"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"生活安全部分ですね、生活安全推進事業、この中で、先ほど来これも質疑に出ておりますので、確認をさせていただきたいんですが、区内を広報の車両で回るというお話があったと思うんです。これはどのような形でやられるのか、予算の中で特別に車の購入というのは出ていなかったような気もするんですが、その辺、ちょっと教えてください。","respondent":"杉浦生活安全担当課長","answer":"この車につきましては、平成１５年度の予算の補正のほうで１台つけていただいております。それから、新年度につきましては３台、巡回用自動車ということで軽自動車、同じ形ですが、つけていただいております。","voiceIndex":145,"id":"exchange-059"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。ですから、その辺のところはやはり少し考えておいていただきたい。これはご答弁は結構です。この点に関しては要望にしますが、その中で、こういう安全業務というのが、本来からしたら区の仕事ではない、東京都の仕事である。ですから、大もとの考えからいけば、５２％を外れた部分で来てもいいんじゃないのかなと、そういう思いがあるんですが、その辺はどうでしょうか。","respondent":"市岡企画財政課長","answer":"ただ、これは先ほど来、担当課長が申し上げているとおり、地域として安全・安心な街づくりを基礎的自治体の仕事として行うという意味で財調算入を区側からも要望いたしましたので、その辺のけじめはしっかりつけていきたいというふうに考えてあります。","voiceIndex":147,"id":"exchange-060"},{"speaker":"鈴木（真）委員","kind":"質問","question":"もう一点、今度ＣＡＴＶのほうです。これは予算書のほうに南東京ケーブル出資金２億５,０００万円と出ているんですが、ご答弁も最初の説明のときにありましたが、追加出資というお話があったので、この辺について考え方を教えていただければと思います。","respondent":"山田広報広聴課長","answer":"ただいまのご指摘の南東京ケーブルテレビの出資金ですけれども、現在品川区は７％の出資金という形で運営をしているところですけれども、実を言いますと、ケーブルテレビは全国的に見ましても大変広域化というものが進んです。","voiceIndex":149,"id":"exchange-061","title":"町会・自治会支援"},{"speaker":"鈴木（真）委員","kind":"質問","question":"はい、わかりました。株を所得というのは、増資の部分ではなく、ほかの部分から買ってくる、ほかのところから株を買うという考え方ですか。当然先に契約していますけども、そういう家にもダイレクト、ビラまきをやっておりましたので、加入の案件、やっているとは思うんですけど、ですから、困難地域の解消という点と、それから既存のマンション、どうしても加入率が悪いと思うんです。","respondent":"山田広報広聴課長","answer":"今後大きな課題になっていくので、区としても改めていろんな形で何ができるかを検討していきたいというふうには考えてあります。","voiceIndex":151,"id":"exchange-062"},{"speaker":"鈴木（真）委員","kind":"質問","question":"前にお聞きしたかどうか、これも正式な中身はわからないんですが、歩道橋を伝わって回線を送るということもできるとか、前にご答弁があったのは電波を使ってとれるということもあったと思います。こういうときに、品川区のほうとして、新しく住民になる方に区の情報を伝えるため、建築の段階、そこの辺で指導はとれないのかもしれないんですけど、説明はなさっているんですか。","respondent":"山田広報広聴課長、片田建築課長","answer":"その後もケーブルテレビの中の技術革新ということで、ぜひ研究をしてくれということで、私ども申し入れをしておりまして、今、平成１６年度をめどに、何とかなりそうだということを伺っております。最近では、高層建築物がかなり多くなってきたということで、複合受信の障害というようなこともありますので、今後新しくやはり、ただマンションだけではなくて、個別住宅等々についても、やはり受信障害等を考えますと。","voiceIndex":153,"id":"exchange-063"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ごめんなさい、最後に要望だけにします。紛争の関係ではなくて、その建物自体、周りに対してじゃなくて、その新築建物に対しての住民に対する区の情報の提供という意味で、何か今後検討ができないかということ、要望で、時間がないからお答えは悪いと思うので。その辺のことで、あくまでも区の情報を伝えるという意味で有効に使っていっていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":156,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１５７ページの庁舎等整備工事費と、あとちょっとページがないんですが、指定管理者制度について、お伺いをします。一番近いのが第一庁舎の３階なんですけれども、先日電動車いすでは中が狭くて回れなくて使えないというのがわかったんです。結局、第二庁舎の３、５、７階まで行かないとトイレが使えないという状況では、私はほんとうにはっきり言って遅れているなと思うので、ぜひ改善を求めます。","respondent":"西島経理課長","answer":"単にエレベーターをつけるだけではなくて、上の傍聴席の部分にも手を入れなきゃいけないということで、かなり大規模な修繕が必要だですので、一般質問でご答弁しましたように、大規模修繕の際の検討課題にするということにします。","voiceIndex":158,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"トイレに行きたいと思ってから延々と二つの建物を越えて、階を下がらないとトイレに入れないというのでは、私は来ないでほしいと言われているのに等しいと思うんです。私、この辺ですごく教訓を受けたのは、やはりいろいろな障害を持った方たちの声をよく聞くのと、実際に立ち会ってもらってつくることが大事だと思うので、ぜひその辺を教訓にしていただきたいと思います。","respondent":"西島経理課長","answer":"したがいまして、バリアフリーに向けてできるところから庁舎は改修していますので、大規模改修の際には十分検討してまいりたいというふうに考えてあります。それから第二庁舎のトイレですけども、あそこをつくる際には、職員にも電動車いすを使用している職員がおります。","voiceIndex":162,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"大分前なんですが、トイレに１５０万円ぐらいかかるというのを、間違っていたらすみません、伺ったので、私はできないことはないなと思うのと、先日来てくださった電動車いすの方は、前に目黒にいらっしゃって、しょっちゅう国会も行き、都議会も行き、区議会も行っている。このままではいけないという意識をより多く持っていただきたいと思うので、これは要望で終わらせていただきます。次に移ります。","respondent":"日下部障害者福祉課長","answer":"そういった点からいたしますと、少なくともそれぞれの事業者に係わるいろんな情報が、情報といいますか、そういった複数の事業者のほうから事業の収支関係はもとより、事業者自体の全体の事業計画から収支の状況も含めて報告をさせるということになりますと、個々の。","voiceIndex":164,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回は、心身障害者福祉会館については品川総合福祉センター１法人です。ぷりすくーる西五反田は子育て品川ですか、１社ですよね。そういった面では、別に資料が多くなるわけでもないし、より中身が深まるし、理事者の説明だけでは足りなくて、私たちは実際に中身を質問して、この内容のまた答弁を求めたわけですけれども、それよりももっと深くこの中に書かれているわけですよね。","respondent":"日下部障害者福祉課長","answer":"それからもう一つは、確かにさっき申し上げましたように、今回は今までの経過がありますので、それぞれ１社ずつということになりますけれども、ある意味では、今回の取り組みが指定管理者制度の導入の一つのひな型といいますか、モデルになります。","voiceIndex":166,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これはご返事はいいです。じゃあ中身に入りますけれども、新しい制度が始まって、厚生委員会では２件既に条例の審査をしたわけですけれども、なかなか中身がわかりにくいので教えていただきたいと思います。現行の管理委託制度と、新しい指定管理者制度の違いを教えていただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"それを端的に言いますと、民間事業者、株式会社までに委託の範囲を広げることができるというのが大きな違いです。それで、こういうことにより、区民サービスの向上とともに行政コストの縮減を図るというものをねらいとしているものです。","voiceIndex":168,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"意見","question":"民間の株式会社も参入をしていくというところで、また利用料なんかも設定されるというところでは、適切な運営ができるかどうか、このチェックが大変重要になっていくと思うんですけれども、行政はどのようなチェック機能を持っているのか、その辺をお話しください。","respondent":"榎本行財政改革担当課長","answer":"区の条例の中でその管理の仕方、利用者の対象、それから使用料等をすべて決めておりまして、その条例に基づく形での委託という形になりますので、大枠のチェックは条例、またはそれとあと具体的な指定管理者については。","voiceIndex":170,"id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問","question":"条例に定めるということですけれども、ちょっと条例の中身について幾つかお伺いしますが、先日ヤフーＢＢで４５０万人の顧客の情報が流出してしまったという事件があったんですけれども、個人情報の保護のところが大変重要と思います。情報公開と監査のところがどうなっているのか教えてください。","respondent":"榎本行財政改革担当課長","answer":"監査のほうの関係ですけれども、従来の管理運営委託でも同じでしたけれども、区が関与しているものについては監査がきちんとかけられるということで、監査のほうでの必要性、または区長、長のほうの必要性に応じて監査ができるということになっております。","voiceIndex":172,"id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問","question":"個人情報のところなんですけれども、先日の条例の中にも条項はあったんですけれども、一つにはこの制度上の義務づけがないという解釈があるんですけれども、その辺、どうなのかなと１点お伺いしたいのと、あと情報公開と監査のところ、委員会で私ご質問したら、これはできるということなんですけれども、実際に条項の中にないんですよね、監査の項目と情報公開の部分がないので。","respondent":"山田広報広聴課長、榎本行財政改革担当課長","answer":"ただいまのご指摘ですけれども、情報公開に関しましては、区が取得したいわゆる情報という形になりますので、それぞれの区の窓口の所管のところに申請をしていただければ。監査のほうにつきましては、地方自治法の中で指定管理者そのものに対して監査ができるという規定で改正されておりますので、従来と同じように公共的団体にかかわらず、民間事業者まで監査ができる。","voiceIndex":174,"id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問","question":"指定管理者制度のちょっと本を読んでかじったところなんですが、出納関係については監査ができるけれども、管理業務は対象外だという項目があってちょっと気になったんですが、お金の出し入れのところはわかるけれど、管理業務は対象外と、この辺、わかりますでしょうか。","respondent":"榎本行財政改革担当課長","answer":"区が委託する業務については、すべて監査ができるということで、例えば委託先の固有の事業については監査の対象になりませんけれども、区が関与して委託した分についてはすべて監査の対象となります。","voiceIndex":177,"id":"exchange-073"},{"speaker":"飯沼委員","kind":"確認","question":"ご説明はわかったんですけれども、監査の条項がないのは、これは確認できますよね。私はぜひ入ったほうがいいと思うんですが、その点はいかがでしょうか。","respondent":"榎本行財政改革担当課長","answer":"監査については、地方自治法の改正条文の中で、「指定管理者が行う公の施設の管理業務にかかわる出納管理の事務について監査を行うことができる」という形で、法律に規定しておりますので、条例のほうでは特に規定をしておりません。","voiceIndex":179,"id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっと時間がなくなってしまったので。品川区の中で、現在管理運営委託になっていて、この指定管理者制度が適用される施設についてご説明いただきたいんですが。","respondent":"榎本行財政改革担当課長","answer":"現在管理運営委託が行われている施設は今後３年以内に指定管理者の制度に移るという経過措置が設けられておりまして、その辺の施設については、具体的に全部の施設、全部で個別に言うと２０施設ぐらいのところが管理運営委託ということで。","voiceIndex":181,"id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問","question":"すみません。この制度から外れるかもしれないんですけれども、保育園の給食の代行とか、あとこれから始まる図書館の窓口はどういう扱いになるか、ちょっとだけお聞きします。","respondent":"榎本行財政改革担当課長","answer":"管理運営委託というのは、その建物、公の施設の全体の管理運営を委託するものであって、実際に窓口とか受付とか、調理の代行の部分ですとか、一部についてはこの管理運営委託とか、指定管理者というところの概念には入ってきておりません。","voiceIndex":183,"id":"exchange-076"},{"speaker":"川西委員","kind":"質問","question":"１番目は１６９ページ、次世代育成支援行動計画策定経費について、二つ目は小学校避難所、それから防災活動広場、防災備蓄品に関連したことが一つ、そして三つ目は保養所関連です。初めに、次世代育成支援事業計画策定についての事業内容を教えてください。","respondent":"榎本行財政改革担当課長","answer":"平成１５年、１６年の中で具体的な計画を各自治体ごとに定めるということで、その計画策定経費をここに計上しています。","voiceIndex":186,"id":"exchange-077"},{"speaker":"川西委員","kind":"意見","question":"メンバーとか、どういうことで進められるのか、平成１５年度はどんなことをやられたのか。私、せんだって、どこの課長でしたか忘れましたが、こういうことを手がけているのかと聞きましたら、全然やっていませんよと言われちゃったんですけど。","respondent":"榎本行財政改革担当課長","answer":"失礼いたしました。手がけております。それで、まず平成１５年度は庁内検討会ということで、これはかなり幅広い分野の実際には事業を想定しております。","voiceIndex":188,"id":"exchange-078"},{"speaker":"川西委員","kind":"質問・要望","question":"それで、庁内の組織、どういう課長なのか、係長なのか、部長なのか、プロジェクトというんですか、こういうの。そういうものはどうなっているのか。平成１６年度どういうふうに組織化して検討しようとするのか。それから、閲覧制度のように区民の皆さんにこういう計画を策定しましたよというのをどこかで広報されるのだと思いますけれども、平成１６年度分の過程だけお知らせいただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"実際上その原案をかけるとともに、そういう計画案につきましては、広く区民に公表して意見も求めていきたいというふうに現時点では考えております。","voiceIndex":190,"id":"exchange-079"},{"speaker":"川西委員","kind":"質問","question":"これはこの辺で大いに期待をするところです。広報についてもよろしくお願いいたします。それから、防災関係のことで、せんだって、うちの地元の町会で総会がありました。ですから、備蓄品の配布の範囲を知りたいと思います。それから、防災活動広場の定義ですね、防災活動広場というのはどういう内容のものか、定義を教えてください。公園管理、土木のほうに何で管理が任せられないのか、あわせて伺います。","respondent":"久保田防災課長","answer":"第１点目の浅間台小学校の避難所ですけれども、現在浅間台小学校には被害想定の数からいいますと、４２１人が避難するという想定になってあります。","voiceIndex":194,"id":"exchange-080"},{"speaker":"川西委員","kind":"質問・要望","question":"時間がないので要望だけにとどめます。今あいている土地がいっぱい売りに出ておりますので、ぜひ国庫補助金や負担金が今出ないからつくらないというようなことでは寂しいと思いますので要望しておきます。ですから、やはり費用対効果の面なのか、１,０００円、７０歳以上に負担しているのが困るのか、安過ぎるのか、それから人気がないのか、問題はどの辺かということを伺いたい。","respondent":"長田区民課長","answer":"保養所の見直しの件ですけれども、先ほどもご答弁申し上げましたけれども、４０年代、５０年代と違いまして、区民のニーズが大分変わってきた。","voiceIndex":196,"id":"exchange-081"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ご苦労さまです。私のほうからは１５１ページの電子計算機組織運営に関連して、それから、１５９ページのふれあいサポート推進事業、災害要援護者の名簿づくりに関連をして、それから１７９ページ、住基ネットに関連して質問をします。ですから、その両方をどういうふうに確立していくかということをお聞かせください。お願いいたします。","respondent":"志村地域活動課長","answer":"ただ、これにつきましては、ほんとうに町会の方のご理解をいただかないと、これはできないところです。そこで、今モデル地区といたしまして、そこにご希望の名簿に登載を希望される方について意見を募ったところです。","voiceIndex":200,"id":"exchange-082"},{"speaker":"伊藤委員","kind":"質問","question":"それはそれで結構乗り越えてくださって、ここまでしていただいたのはありがたいんですが、そういうほんとうにプライバシーの高い名簿が今度できてくるわけですから、今度はそれを災害でどう生かすかという大目的を確保すると同時に、あわせてそれがいろんなさまざまな目的を持つ団体に活用されるような仕組みづくりもあわせて必要である。","respondent":"久保田防災課長","answer":"これの情報管理については、厳しく徹底してやってほしいということを一つ書いてやっているという状況です。したがって、そういうところで今後も保護に関しては徹底した形で今後も充実していきたいというふうに考えております。","voiceIndex":202,"id":"exchange-083"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、そういうふうなセキュリティポリシーという言葉を勉強しましたけど、そういう情報を取り扱う職員の意識、行動の徹底、それから研修、あわせて職員の皆さんに対する監査ですね、それはどうなさっているかということ。それから、今いないと思うんですが、まさかパソコンを使えない職員はいないと思うんですが、いないということの確認をいただければと思います。","respondent":"田中情報システム課長","answer":"お尋ねのまず１点目のセキュリティに関する職員の意識や研修についてですが、平成１６年度予算の中で一応職員２,５００人を対象にしたｅラーニングを予定しております。","voiceIndex":204,"id":"exchange-084"},{"speaker":"伊藤委員","kind":"質問・要望","question":"いないとは思いますけど、職員が皆さん１人１台パソコンを持っているわけですから、ずっと追い続けたことがありますけども、これもすべての職員が少なくともパソコンの基本的なことができないとおかしい話ですので、進めていっていただきたいのと、それからシステムを立ち上げた、それから基準もつくった、ですけど、これから２,５００名のｅラーニングを始めていくわけですが。","respondent":"田中情報システム課長","answer":"一切廃棄しておりませんので、その部分についてはいろいろ問題があったりした場合は、すぐ解析できるような形になっております。いわば一定の抑止力にもなるし、そういう公開等があれば対応していくような準備を整えているところです。","voiceIndex":206,"id":"exchange-085"},{"speaker":"伊藤委員","kind":"確認","question":"そのことを考えていきますと、非常に今より以上にさまざまなことが出てくるでしょうし、仮に情報が流出された場合には、品川区という大きな地方自治体のデータが出ていく、大変恐ろしい事態になっていくわけですから、昨日も確認させていただきましたが、これから電子区役所構想の中で、セキュリティ対策とあわせて。","respondent":"田中情報システム課長","answer":"その点で、リスクをきちっと管理していくということで、利便性の向上とリスクをきちっと管理していくというところで電子区役所の実現に向けて努力していきたいというふうに考えております。","voiceIndex":208,"id":"exchange-086"},{"speaker":"大西委員","kind":"質問","question":"最初に先ほど企画財政課長のほうで政策形成研修というんですか、これに力を入れたいということがございましたが、これは具体的な中身はどういうことになるんでしょうか。","respondent":"桑村人事課長","answer":"その意味で、そういうことを通じまして、いわゆる区の中の職員が自らの仕事についてどのような形で改善していくか、あるいは取り組んでいけばいいのかという方向を自らが見出すというような職員をつくることを目的としてごさいます。","voiceIndex":211,"id":"exchange-087"},{"speaker":"大西委員","kind":"質問","question":"わかりました。これの場合、対象となる職員層、大体どの辺の層を対象とするのかを教えてください。","respondent":"桑村人事課長","answer":"基本的には特に限っているわけではございませんけども、私どもとすれば、できればいわゆる若手の層から、いわゆる係長でもまだ昇任されたばかりといった層をねらいにしているものです。","voiceIndex":213,"id":"exchange-088"},{"speaker":"大西委員","kind":"質問","question":"具体的に１年間で人数的には何名ぐらいの方がこの研修を受けられるんでしょうか。","respondent":"桑村人事課長","answer":"そういったものについては１クラス例えば４０名とすれば、１０ぐらいありますので４００名ぐらいが受けられる形だろうと思います。","voiceIndex":215,"id":"exchange-089"},{"speaker":"大西委員","kind":"質問・要望","question":"ぜひそのような機会がありますれば、その件も、私は全部大規模改修しなくても、登壇して質問するところを１８０度変えられるような形で、これは一つの私のアイデアで、別に私は設計なんでもありませんし、前に居たわけでもありませんので、ぜひその辺のところも一つご勘案いただければ、もっと何か私もよい質問ができるのかなというふうに思っていますので、ひとつそのようなこともお願いできれば。","respondent":"志村地域活動課長","answer":"それと、平成９年から始まりました夕食につきましても、現在中学校のいわゆる給食設備を利用してつくってありますけど、現在のところ１４校です。ですので、計画的にこれから進めてまいります。","voiceIndex":217,"id":"exchange-090"},{"speaker":"大西委員","kind":"質問","question":"今のだとちょっと答弁漏れになるんですけど、どうしてこの事業評価でＡになるのかをちょっと教えてもらいたい。","respondent":"榎本行財政改革担当課長","answer":"それで、このＡというのは「拡大する事業」という形でくくっておりますけれども、その細かい説明の欄を見ますと、「将来への必要度が高い場合」「今後重点的に実施すべき場合」「特色ある政策を展開する場合」ということで。","voiceIndex":219,"id":"exchange-091"},{"speaker":"大西委員","kind":"質問・要望","question":"先般、この配食サービスをしているボランティアの人とか、あと民生委員とかで、試食会というのがあったんですね。その際にいろんな要望が出ておったんですけど、そこで役所からも人が来ておったんですけど、そこでこの事業が始まって４年ぐらいたつという話だったんですけど、その間、ここ４年間ほどアンケートをとっていないんですね。その点に関してはどうなんでしょうか。","respondent":"志村地域活動課長","answer":"いずれにいたしましても、これから高齢者あるいはひとり暮らしの方の配食のサービスがいろいろ現在出てきてあります。ですので、こうしたことを踏まえながらサービスのあり方については検討してまいりたいと思ってあります。","voiceIndex":221,"id":"exchange-092"},{"speaker":"大西委員","kind":"質問・要望","question":"私が申し上げているのは、受益者の考え方をくみ取る仕組みができていないんじゃないでしょうかと。こういうことがあったんですね。待つ身はやっぱりそんなものだと思うんですね。私はそれじゃあ、そういう遅れるときには、山中小学校では９件の配食しかないので、そういうときには電話を差し上げたらどうですかと、それで安心してもらえるし、配る側もあせらなくていいんですね。これは要望にしておきます。","respondent":"志村地域活動課長","answer":"実はこちらもかなりの歴史がありますけども、これにつきましても、連合会を通じて、ほかの地区にもＰＲ等々を行いまして、委員今ご提案がありました件につきましては伝えてまいりたいと、かように考えてあります。","voiceIndex":223,"id":"exchange-093"},{"speaker":"大西委員","kind":"質問・要望","question":"そしてあと、生活安全サポート隊、そして我が町パトロールの推進ですが、これのボランティアの募集方法についてなんですけど、私はちょっと取り違えているかどうかわからないんですけど、ボランティアを、区長も前に、昨年の私の一般質問のときにおっしゃったんですけど、地域で自分たちのところは自分たちで守っていこうというお話があったんですけども、その際に、私が思うには。","respondent":"杉浦生活安全担当課長","answer":"先ほど申し上げましたけれども、警察や防犯協会で把握している防犯活動に熱心な方、こういう方に対して、その労苦に報いたいというのが、確実なところで、まず第一歩としてやらせていただくにはいいのかなというふうに思った次第であります。","voiceIndex":225,"id":"exchange-094"},{"speaker":"大西委員","kind":"質問","question":"なるほど、手堅いところからスタートするのは私も賛成です。ただ、潜在的に意欲を持ってボランティア活動に取り組もうという方々も私は品川区に多くおられるのではないかなと、そういう方々に場の提供をしていただければと思います。ぜひ新しく区民の安全を守っていこうということでスタートされていますので、今後の活躍を期待して、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":227,"id":"exchange-095"},{"speaker":"藤田委員","kind":"質問・要望","question":"私から３点、端的にご質問いたします。１５７ページの庁舎の屋上庭園につきまして、２番目が１７３ページの防災活動広場管理費につきまして、３点目が１７３ページの区民保養所についてお伺いしたいと思います。だから、私ちょっと代弁して、小さな、ささいな問題ですけれども、ちょっとお考えをお聞かせいただきたい。これは何か理由があるんでしょうか。それから、保養所につきましては深入りしません。","respondent":"西島経理課長、久保田防災課長、長田区民課長","answer":"そうしますと、ドアをあけると、あそこに置いてあるものがみんな飛んでしまうようなこともありまして、なかなか管理が難しいこともあろうかと思いますが。防災活動広場に関しては、この設置目的は先ほど若干触れたところですけれども、防災活動広場の施設の内容としては。ただ、仮に廃止をするにして、そのままで、廃止のしっ放しでいいのか、また、これはそれにかわる何かを考えなければいけないのか。","voiceIndex":229,"id":"exchange-096"},{"speaker":"藤田委員","kind":"質問・要望","question":"わかりました。ですから、もう少しきれいに、庭園とマッチしたものを、例えば緑でずっとペンキを塗るとか、何か工夫ができないものか。ですから、これは即答できないと思いますが、この２カ所だけがついていないのか、防災活動広場、皆さん発災時には一時集合場所で来るわけですから、それは全然皆さんが集まってきたときに時計を持ってくるかどうかもわからないという部分で、混乱していますよね。","respondent":"西島経理課長","answer":"屋上のネットフェンスの件ですけど、一時私どもも検討したことがありますけれども、主に職員が昼休みに運動に使うということで、あそこは修繕するには相当な経費がかかるということもあります。したがいまして、当面今のままで利用していきたいなというふうに考えております。","voiceIndex":233,"id":"exchange-097"},{"speaker":"藤田委員","kind":"提案","question":"私もやめようと思ったんですが、今ちょっと違った答弁がありました。フェンスを撤去しろと言っているんじゃないんです。十分あれはまだ使えるんではないかと私は思うんですけど、素人ですけれども、ただ、今庭園とマッチしないような、さびていますので、これを修繕してはどうかという提案をしているんですけれども、これだけちょっとお願いします。","respondent":"西島経理課長","answer":"運動ですけど、今度運動はしながわ中央公園という場所もできますし、そういう意味ではそちらでやっていただくということで、あそこの部分については、将来的には撤去するということで考えていくつもりです。","voiceIndex":238,"id":"exchange-098"},{"speaker":"原委員","kind":"質問","question":"私のほうからは３点にわたりましてお伺いをします。それから区政モニター、タウンミーティング、今回１月２９日にやられたですが、これもまた同じく目的と、それから区側の出席者、そして年何回ぐらいを予定しているのかについてお伺いをします。それから、区政アドバイザー、これもまた目的をお伺いします。そしてまた、この区政アドバイザーに区側はどの方々を出席させようとしているのか。","respondent":"志村地域活動課長、山田広報広聴課長、榎本行財政改革担当課長","answer":"皆様ご案内のことにつきましては、新年度の予算といいますか、区の方針等について春にご説明をする会を１回持ってあります。平成１５年度につきましては、７回実施をしておりまして、それについて区政のテーマによって所管の課長が出てまいりますので。区政アドバイザーですけれども、まず、事業の目的としましては、今説明がありましたきらめきトークタウンとか、モニターのほかに。","voiceIndex":241,"id":"exchange-099"},{"speaker":"原委員","kind":"質問・要望","question":"それぞれ区政協力委員会あるいはモニター、タウンミーティング等々、目的を持って皆さんから意見を聴取し、そしてまた要望を聞きということでやられて、そしてこの区政アドバイザーも今回７名のメンバーを決めたわけですけれども、その三つをあわせて、モニターを入れると四つなんですが、それぞれのところで意見を聴取して、いろんな場面で区政に対する意見を述べてもらうわけですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":245,"id":"exchange-100"},{"speaker":"原委員","kind":"質問・要望","question":"それをどう調整するのかというのも大切な部分だろうと思うし、特に今回の区政アドバイザーの場合は、その審議会形式をとるということだと、じゃあそのアドバイスをどなたがメインになって聞かれるんですか。これはそれぞれじゃなくて、どなたかまとめてお答えいただけるとありがたいんですが。","respondent":"中尾根企画部長","answer":"これまでここに来るまでの準備としましては、内部的には事業部制というのをとりまして、重要な会議については、たとえどこが受けたとしても、事業部経営会議という、このトップの会議の中でいろいろ調整をして、政策として打ち出していくという機能を持っておりますので。","voiceIndex":250,"id":"exchange-101"},{"speaker":"原委員","kind":"質問","question":"そういう審議会だというような……。それともう一つは、私たち議員という立場もあるわけで、先ほどそこに話し合いをし、調整をしていくという話が出てきましたけど、やっぱり私たち議員も、議会と、それから行政との両輪という形で位置しているわけですから、どう調整されようとしているのか、そこを教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":252,"id":"exchange-102"},{"speaker":"原委員","kind":"質問","question":"アドバイザーのほうですけれども、区長がそれを聞かれるという、補完的に企画部長が出られるわけですから、そうすると、区長の諮問機関という形ですか。そうすると、ちょっとここの ２４０万円の使い方が違ってくるんじゃないですか。その辺のところをちゃんとはっきりしていただかないと、もし区長の諮問機関であるならば……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":257,"id":"exchange-103"},{"speaker":"西本委員","kind":"質問","question":"質問のほうは、まず１５３ページの国際友好都市交流事業、それと１６７ページの行政評価システム、ちょっと項目が見つからないんですが、外部評価について、それと１６９ページの事業部支援プロジェクトの中のボランティア活動の連携の仕組みづくり、時間のある限りちょっとお願いしたいと思います。１５３ページの国際友好都市交流事業についてお聞きします。","respondent":"宮地総務課長","answer":"ホームステイあるいは留学、あるいは区内に在住の外国人の方との交流ということでは、生け花やお国自慢料理教室とか、日本語教室とか、そういった事業を展開しておりますが、区とのかかわり合いということですと、所管しているのは総務課ですから。","voiceIndex":262,"id":"exchange-104"},{"speaker":"西本委員","kind":"質問","question":"ここら辺の工夫、実際委託をしておりますので、具体的な事業内容については、当然ながら友好協会のほうが指導されるんでしょうけれども、こういう状態で果たして事業評価もＢというランクをつけているわけですから、ここら辺の工夫というのは、どのようにお考えになっているのか、ちょっとお聞きしたいというふうに思います。","respondent":"宮地総務課長","answer":"そのＰＲの方法につきましては、やはり、主体的に動くのは国際友好協会ですから、どういうふうにしたらいいのかというアドバイス的なことはこちらでも積極的に言っていきたいと思いますし、また区のいろいろな所管ともＰＲのルートをつくりまして、ぜひ地域センターだとか。","voiceIndex":264,"id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"そういうノウハウも少し教えていただきながら、広くＰＲ活動を担っていけるようにお願いしたいというふうに思っています。わりあい若い層の人たちがあまりいないものですから、なかなか若い人たちの意見が反映しにくいんではないかなというふうに私は感じましたので、そこら辺のアドバイスもぜひしていただきたいなというふうに考えますが、いかがでしょうか。","respondent":"宮地総務課長","answer":"やはり補助金を出している以上、いろいろな形でのアドバイスはさせていただきたいと思います。","voiceIndex":266,"id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"次に１６７ページのほうの行政評価システムについて質問いたします。ちょっと項目が長いので、外部評価委員会ということで、外部評価に対して、今区としていろいろと進んでいるかとは思うんですが、今後どういうふうに外部評価をしようとしているのか、その辺の進捗状況と、今後の方向性といいますか、そちらのほうを教えていただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"それで、外部評価委員会につきましては、２年前の平成１４年２月に設置されまして、政策評価についての仕組みづくりを主に検討してまいりました。仕組みづくりと、それに基づく評価ということで課題が与えられまして、それについての検討を行ってきたところです。","voiceIndex":268,"id":"exchange-107"},{"speaker":"西本委員","kind":"質問","question":"先ほどからいろんな委員のほうからもありましたけれども、区民の意見を反映する方法、苦情であったり、いろんな形で行政のほうに意見があったり、区政モニターなんかもあるというところで、多分これもそういう形でいろいろな意見を区民の皆さんの意見を聞くという一つの方法として使われるのかなという部分もあるんですが、そこら辺のほかの区民の皆様の声の反映の仕方と。","respondent":"榎本行財政改革担当課長","answer":"それで、さらにこういう答申につきましては公表しまして、さらにその公表結果については各区民の方からもご意見をいただいて、さらに今後の外部評価委員会の中にも生かしていくというような仕組みをつくったところです。","voiceIndex":270,"id":"exchange-108"},{"speaker":"西本委員","kind":"意見","question":"そうしますと、これからの評価対象というところを見ていきますと、非常に多岐にわたっていると思うんですね。そのそれぞれの項目がそれなりに専門的な知識、それから広い知識がないと評価できにくいという部分があろうかと思うんですけれども、そこら辺を今後どういうふうにしていくのか。","respondent":"榎本行財政改革担当課長","answer":"この政策評価、外部評価の評価対象ですけれども、第三次長期基本計画の主に２４の分野ということで挙げておりますけれども、実際上外部評価委員会の中で検討するときには、それぞれ全体像をまずお示しして、全体像の中で特に区民の方。","voiceIndex":272,"id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"むしろ選ぶ側のほうの力量が問われてしまう。ということは、選ぶ側のほうによって、この外部評価がうまくいくのかいかないのか、それが政策に具体的に反映できるのかできないのかというところで大きな違いが出てきてしまいますので、その辺の人選等も含めてのお考えをちょっとお聞きしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"それで、人選につきましては、やはり応募した段階でさまざまな方が応募されますので、年代ですとか、地域ですとか、それまでのいろんな経験ですとか、そういうものでなるべく知識豊富な方に参加していただきたいということで人選をしておりまして。","voiceIndex":274,"id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、私としては要望もありますけれども、その公募で選ばれた方、いろんな形での人選の方法があるかとは思うんですが、ただ、外部評価で出てきた評価が、ほんとうに妥当性があるのかどうかということに対しての、それの評価ですね、評価の評価といいますか、そこはしっかりと持っていただかないと、ある程度そこの評価によって、ほんとうに品川区の政策が違う方向に行ってしまう可能性もありますので。","respondent":"榎本行財政改革担当課長","answer":"それで、最初いろいろ仕組みの方策というのはあるんですけれども、どういう方法を選んで評価していきたいのか、それも各委員からの意見をもとにそれぞれ進めてまいりました。","voiceIndex":276,"id":"exchange-111"},{"speaker":"中塚委員","kind":"質問","question":"私からは１６５ページのタウンミーティングについて、あと１６９ページの防災センター展示について、あと時間があれば、１７５ページの区民集会所リフレッシュ経費について３点伺いたいと思います。そこで伺いますけれども、開催に至った背景、またこのタウンミーティング参加の呼びかけですか、区民への周知の方法について伺いたいと思います。","respondent":"山田広報広聴課長","answer":"そうしたわけで、広報につきましては、当初１２月に開催する予定でございましたので、周知については広報紙で実施をいたしました。これが１１月１日です。","voiceIndex":279,"id":"exchange-112"},{"speaker":"中塚委員","kind":"意見","question":"私も第１回のきらめきトークタウンを傍聴させていただきまして、その中で区長があいさつの中で、「区民の意見を政策に加点するため」とおっしゃっておりました。","respondent":"山田広報広聴課長","answer":"いわゆる議会と行政との行政運営が円滑にいくためには、やはり両輪になりながら進めていくのが第一義的なことだと、それを冒頭申し上げた上で、ただ、幅広く区民の皆様のご意見をいただきながら、そうしたものの補完の役割として。","voiceIndex":281,"id":"exchange-113"},{"speaker":"中塚委員","kind":"提案","question":"若干、より充実していただきたいと思うところで提案があるんですけれども、初めての事業なので、区民にもなかなか周知の点ではご苦労があるかとは思いますけれども、ぜひポスターなんかを使って町会の区内のさまざまな掲示板に張られたらどうかなと思うのと、あと、開催の時間なんですけれども、平日の午後だと、どうしても働いている人は参加しにくいというのが現状としてあると思いますので。","respondent":"山田広報広聴課長","answer":"そうした意味でも、テーマの設け方、それから開催日のあり方、それから開催の場所については、平成１６年度は４回実施をいたしますので、その中で十分検討していきたいというふうに考えてあります。","voiceIndex":283,"id":"exchange-114"},{"speaker":"中塚委員","kind":"質問・要望","question":"では次に、１６９ページの防災センターの展示についてなんですけれども、私たちとしては、防災センターの３階ロビー、一緒に第三庁舎のことも含めてですけれども、区民開放をこの間求めてきたんですけれども、そのときの説明で、職員と区民との利用目的が違うとか、有事の際のオープンスペースとして確保していきたい、そういった答弁があったと思いますけれども。","respondent":"久保田防災課長","answer":"そのほか、ほかの事業部のほうで活用したものとしては、環境課の環境啓発パネル展示とか、それから選挙啓発ポスター、エイズの予防啓発展示、人権啓発ポスター展、歯の啓発ポスター、そのほか防災課のほうになりますけれども、防災フェアを実施しましたので、これは１月１６日。","voiceIndex":285,"id":"exchange-115"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただいまの説明ですと、写真展やポスターのパネルの展示といった壁かけ式の展示物が多かったと思うんですけれども、これらの展示はやはり災害や地震のときに、即座にスペースとして確保したいという意向で壁掛け式にしているという理解でいいのかという点が１点伺いたいと思います。","respondent":"久保田防災課長","answer":"この活用についてですが、あくまでも３階ロビー、庁舎ですので、一般の区民が自由に使う集会所のようなものではないというふうに考えておりますので、従来どおり事業部の啓発展示、防災課を主体にした啓発、それからちょっとつけ加えますと。","voiceIndex":287,"id":"exchange-116"},{"speaker":"中塚委員","kind":"意見","question":"目的外利用も多く取り入れてきて、できるだけ有効的に活用していこう、こういう視点が行政改革の中でも議論されてきたと思うんですけれども、目的外使用としても多くのオープンスペースやさまざまな施設があるとは思いますけれども、主にこれまでどんな施設や場所をこういった使い方をしてきたのか、ちょっと説明していただければと思います。","respondent":"西島経理課長","answer":"したがいまして、先ほどいろいろご質問が出ていましたのは、公共用財産ですので、区民が利用するようにつくられた施設です。使用目的がもともと違いますので、この庁舎については、庁舎機能として使っていきたいというふうに考えてあります。","voiceIndex":289,"id":"exchange-117"},{"speaker":"中塚委員","kind":"質問・要望","question":"庁舎は庁舎の機能を兼ね備えているという説明ですけれども、これまでも品川区の庁舎がある中で、隣の第三庁舎は区民開放されていた事例もありますし、ぜひ有効活用していただきたいという点で検討していただければと思います。","respondent":"西島経理課長","answer":"区が主催する行事で使ったことはありますが、そういうことはございませんで、先ほどもご答弁しましたように、この建物については、庁舎として使っていきたいというふうに考えてあります。","voiceIndex":291,"id":"exchange-118"},{"speaker":"中塚委員","kind":"質問・要望","question":"次に１７５ページの区民集会所のリフレッシュ工事ですけれども、報告にもありましたように、やっと大井第三地域センターと荏原第五地域センターのエレベーターの設置が予算化に乗りまして、大変地域の方も喜んでおります。改めて設置の理由と工事の日程や完成予定日などももし明らかになっていれば、ご説明していただきたいと思います。","respondent":"志村地域活動課長","answer":"私ども、そうしたことで技術的に解決ができるところから順次つけてまいりました。今年平成１５年度につきましては、９月補正にもお願いをして、荏原第三地域センターにエレベーターをつけたところです。ですので、平成１６年度、今お尋ねの２件について予定しています。","voiceIndex":293,"id":"exchange-119"},{"speaker":"中塚委員","kind":"質問・要望","question":"地域の方も大変喜んでいると思います。なぜかといいますと、例えばきちんと利用して、片づけて終わっている団体もあるんですけれども、終了時間になると時間になったから、ちょっと終わりですよとあったりとか、何かもう少し実態に合わせて、原則は原則として守りながらも、多少柔軟に動くところも必要なのかなと思うので、お聞かせいただきたいと思います。","respondent":"志村地域活動課長","answer":"多少の、例えば５分とか、ちょっと延長しました、あるいは使う前にお越しになっても、私どもはそれでだめだというようなことを言っているわけではございませんので、その辺はもし実態がございましたら、どうぞ使うときに事前にご連絡をください。","voiceIndex":295,"id":"exchange-120"},{"speaker":"中塚委員","kind":"質問・要望","question":"割と利用団体からいろいろ苦言といいますか、ちょこちょこありまして、特に土日ですね。初めの１回目はよくわかるんですけれども、その利用団体はきちんと掃除もして、机のレイアウトももとに戻してきれいに使っているのに、毎回１５分前になると電話が来るというのはちょっとなかなかどうかという話も伺いました。その１点だけ説明していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":297,"id":"exchange-121"},{"speaker":"中塚委員","kind":"質問・要望","question":"僕、思うんですけれども、新築のマンションですと、できた当時から計画的に大規模改修のものを持ちまして、修繕費などを積み立てて鉄部の塗装やさまざまな修繕を計画的に行っているんですけれども、こうした区民集会所、ぜひこういう計画をきちんと持っていただいてやっていただくようにしていただきたいと思いますけれども、今後の大規模改修の計画について、少し説明していただきたいと思います。","respondent":"志村地域活動課長","answer":"大体３０年の施設が一番古いということで、ここで一度そういう意味では手を入れたというようなことです。ですので、あと今年につきましても、細かなところにつきましても、できる範囲で対応をとっていきたいというふうには考えてあります。","voiceIndex":302,"id":"exchange-122"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に要望なんですけれども、地域センターも文化センターも含めて修繕のほうは進んでいるとは思いますけれども、シルバーセンターを見てみますと、ちょっとそろそろ外壁塗装が必要がかなと思われる施設、あと内壁の改修も必要かなと思われる施設もありますので、ぜひそちらのほうも進めていただきたいと思います。これは要望で結構ですので、終了したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-123"},{"speaker":"山村委員","kind":"質問","question":"私からは１６３ページ、イメージアップ経費および１５１ページ、基幹事務管理システム整備費および１８２ページ、選挙費、時間がありましたら１５９ページ、青少年問題協議会運営費の質問をします。１６３ページのイメージアップ経費のほうから質問します。じゃあ、まずはイメージアップ経費はどのようなことをされているのかということをよろしくお願いします。","respondent":"山田広報広聴課長","answer":"今般お示しをしておりますイメージアップ経費については、全体が２３９万円ですけれども、それの内訳については職員報「ふれあい」を出しておりますが、そちらのほうの発行費、また区民憲章や品川百景の普及経費というような形で計上しています。","voiceIndex":306,"id":"exchange-124"},{"speaker":"山村委員","kind":"質問","question":"事務事業評価のところで、ちょっと苦情のことでイメージアップのほうに書いてあったものですから、そのように誤解していたんですが、じゃあ、苦情の件で質問します。","respondent":"山田広報広聴課長","answer":"苦情の処理につきましてということで、私ども苦情がなくなるようにさまざまな研修や民間派遣研修等実施はしております。","voiceIndex":308,"id":"exchange-125"},{"speaker":"山村委員","kind":"質問","question":"お仕事も大変でしょうから、いろいろと時間がないというか、人数が足りない部分もあるのかどうかわかりませんが、これからも一生懸命やっていただければと考えています。テレビだと基本的なところは暗証番号だと全部抜けると、筒抜けになるということで、基本的には生体照合というか、指紋だとか、そういうもの以外は防ぐ道がないようなことをテレビではおっしゃっていましたが、どのようにお考えでしょうか。","respondent":"田中情報システム課長","answer":"ということで、いろいろ電波を採取されたとしても、解読はできない形の一応対応をとることにしています。電波の届く範囲等についても、必要最小限の電波の調整をして届くような形での調整をする予定にしています。","voiceIndex":310,"id":"exchange-126"},{"speaker":"山村委員","kind":"質問","question":"そうすると、結局その自分の番号をとられる可能性が出てくることもあるわけですから、番号だけで個人を認識するので、出先機関で電波ということになると、ある１人の個人に特定してその番号を盗もうと思えば、そういう無線のでできてしまうということになると思うんですが、それについてどのように考察されているか。","respondent":"田中情報システム課長","answer":"それ以外の一般的な情報の流通の部分については暗号化してありますので、番号でも、非常に複雑な形の暗号に解読されていない単純な番号でも区民の番号でも、複雑に暗号化して解読されないような形で通信をするようにしています。","voiceIndex":312,"id":"exchange-127"},{"speaker":"山村委員","kind":"質問","question":"同じ事務管理システムのことなんですが、コピー機などを使用ができなくなった、故障したものですとか、例えばパソコンなどの故障したものを廃棄する場合に、特にコピー機とかが盲点だと思うんですが、ハードディスク内に全部今までコピーしたものの暗号が残っていますので、取り出そうと思えば取り出せるわけですが、そういうことはある程度想定して廃棄なされているのかどうかをお聞きしたいなと思います。","respondent":"田中情報システム課長","answer":"コピー機については、ハードディスクを持っている形のコピー機は今うちでは使っていないというふうに、ネットワーク対応のものも若干ありますが、そこのところはちょっと確認できませんので、ちょっとお時間をいただきたいと思います。","voiceIndex":314,"id":"exchange-128"},{"speaker":"山村委員","kind":"質問","question":"今まで使っていたコピー機だとすべてそれが残っていると思っていいらしいようで、最近、結局それを残さないという名目をセールスポイントにして売り出しているコピー機があるくらいですから、そこら辺のことは今までなかった事例だと思うので、気をつけていろいろと考えていただければと思うんですが、どうでしょうか。","respondent":"田中情報システム課長","answer":"ご指摘の点についてはわかりました。メモリ等が残って、それを再生できるような形というのはいろんなソフトがありますので、そういう点を配慮したような形で廃棄の仕様等についてはきちっとしていきたいというふうに思います。","voiceIndex":316,"id":"exchange-129"},{"speaker":"山村委員","kind":"質問","question":"どうもありがとうございました。これからも努力していただければと思います。次に１８２ページ、選挙費の関係で質問します。それと、補欠選挙というものをもしやられることがある場合は、どのようなときに、どのような判断で行われるのかというのをちょっと教えていただければと思います。","respondent":"野田口選挙管理委員会事務局長","answer":"それから補欠選挙ですけども、補欠選挙は先ほど言いましたように、繰り上げ当選しても、いわゆる欠員を補充しても、なおかつ定数の一定割合、例えば区議会議員の場合ですと６分の１を超えた場合については補欠選挙する、こういう仕組みです。","voiceIndex":318,"id":"exchange-130"},{"speaker":"山村委員","kind":"質問","question":"そうすると、次点は１人のみと考えてよろしいんでしょうか。","respondent":"野田口選挙管理委員会事務局長","answer":"先ほどちょっと説明の中で、例えば繰り上げ当選の場合につきましては、区議と長では違いまして、区議の場合にはそういった制度がありますけども、長の場合については同じ得票数であった場合については、抽選で決めるというような規定がありますので、そういった場合については。","voiceIndex":320,"id":"exchange-131"},{"speaker":"山村委員","kind":"意見","question":"そうすると、３カ月を過ぎた場合に補欠選挙をやられるときの先ほどの説明では、６分の１以上繰り上げ当選全部してということですけど、３カ月を過ぎていたら繰り上げ当選しないでも補欠選挙と考えていいわけですね。","respondent":"野田口選挙管理委員会事務局長","answer":"期日後３カ月を過ぎて、定数の６分の１を超えるような状況があれば補欠選挙ということになります。ただし、欠員が６分の１を超えたときですね。それで、ただし、任期満了の６カ月前の時点で欠けたような状況の場合については選挙は行われません。","voiceIndex":324,"id":"exchange-132"},{"speaker":"松澤委員","kind":"質問・要望","question":"私の質問に先立ちまして、先ほど我が党の原委員が区政アドバイザーについて区長の見解を求めましたけれども、区長はお答えする時間がありませんでしたので、もしございましたら、お聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":327,"id":"exchange-133"},{"speaker":"松澤委員","kind":"質問","question":"改めて質問をしたいと思います。２款の総務費、１項総務管理費、１目一般管理費、１５３ページ、１５４ページになります。それともう一つ、男女共同参画センター運営費５７９万６,０００円、この予算の内容についても聞きたいと思います。","respondent":"阿部人権啓発課長","answer":"２点のご質問です。１点目の男女共同参画行動計画推進会議の件ですけれども、これは平成１３年度から第三次の行動計画品川プランをつくってあります。それを区民の方と協働していくということで、行動計画推進会議というのを設置しています。","voiceIndex":330,"id":"exchange-134"},{"speaker":"松澤委員","kind":"意見","question":"男女共同参画社会を目指す第三次行動計画品川プラン、よく男女共同参画社会とかいわれます。その中で、今いろいろと問題になっているのは、男女共同参画というものとジェンダーフリーという言葉がありますよね。そのジェンダーフリーという言葉について、この共同参画、今の課長をはじめ、理事者、どのようなとらえ方をしているのかについてお教え願います。","respondent":"阿部人権啓発課長","answer":"私ども、男女共同参画社会を進めていくために、第三次行動計画をつくっているわけですけれども、その中で目指しているのは、男性も女性も性別にとらわれることなく、能力と個性を発揮でき、なおかつ社会的責任を分担できる社会。","voiceIndex":332,"id":"exchange-135"},{"speaker":"松澤委員","kind":"質問","question":"ジェンダーフリーという言葉は使わない。一切使わないと言いながら、一番のもとである第９期品川区行動計画推進会議報告書、この中に盛られている、今課長が言った言葉と実際に文章になってできている、この今の予算の中でつくっている行動計画ですから、明らかに反していると思うんですね。改めてご答弁を聞きます。","respondent":"阿部人権啓発課長","answer":"その辺はご理解願いたいと思います。","voiceIndex":334,"id":"exchange-136"},{"speaker":"松澤委員","kind":"質問","question":"ちょっと読んでみましょうか。これがもとになっているんです、ジェンダーフリー、ジェンダーフリー、すべてジェンダーフリーですから。これがもとになって、これをもとにして、年ごとに行動計画をつくりましょうと委員に呼びかけて、問題提起して、諮問して提言してくださいと言ったら、これが憲法みたいなものですから、ジェンダーフリーという言葉が出てくるのは当たり前なんですよ。私たちは使いません。","respondent":"本間総務部長","answer":"機械的、画一的な男女差の解消を求めているものではないと、こういう見解が示されまして、区といたしましても、こういう見解に基づいて、誤解のないように、生まないように十分留意しながら対応しているところと、そういう意味で課長が答弁しておりますので、ひとつご理解のほど。","voiceIndex":336,"id":"exchange-137"},{"speaker":"松澤委員","kind":"質問","question":"今のお話を伺いました。実は、人権尊重都市品川宣言１０周年記念、１２月１２日ですけど、「みんな違って、みんないい」、大変話題になりました。これは私も新聞で見まして、何かおもしろそうだなというんで聞きに行きました。これについて、計画者としてはたくさんの人が集まりましたものですから、どのような評価をされているのか、その評価をお聞きしたいと思います。","respondent":"阿部人権啓発課長","answer":"今回いろいろございましたけれども、結果としては皆様には男女共同参画社会を認識してもらうよい機会になったのではないかなというふうに思ってあります。","voiceIndex":338,"id":"exchange-138"},{"speaker":"松澤委員","kind":"質問","question":"質疑のときに、「それじゃあ、教室が成り立たないんじゃないんですか」と質問した方が、「今私たちはここに聞きに来ているけど、みんな静かにあなたたちの話を聞いているから成り立っているんじゃないですか」。１人の方は問題発言はありませんでしたけれども、こういう方をパネラーに招いて、これで共同参画、人権啓発でいいんだ、課長はそれを聞かれていたんでしょうか、一つ聞きたいと思います。","respondent":"阿部人権啓発課長","answer":"今回のシンポジウムは「みんな違って、みんないい」という視点でパネラーを選びました。その中で、委員ご指摘の絵本作家の方については、子どもの視点というお話で選んだわけですけれども、たしかその中でも、質問なさった方に対して、「あなたの意見が大部分の考え方でしょう。","voiceIndex":340,"id":"exchange-139"},{"speaker":"松澤委員","kind":"質問","question":"「みんな違って、みんないい」、それぞれの考え方はあるということですけど、やはり私たちは言いっ放しの話を聞きに行っているわけじゃないんですよね。大多数の話、でも私はこう思うんだ、これについてこう思うんですけど、どうですか。ああなるほど、あの人は少数意見かもしれないけど、正しいな。その辺、改めてもう一度お聞きしたいと思います。","respondent":"阿部人権啓発課長","answer":"今後、委員ご指摘の点も含めまして、パネラーの選出について検討してまいりたいと思っています。","voiceIndex":342,"id":"exchange-140"},{"speaker":"松澤委員","kind":"意見","question":"時間になりましたので。成人式にもアンケートが出たんですよね。ジェンダー、男らしさ、女らしさといった性差をあらわします。これはやっぱり成人式おめでとうと子どもたちに呼びかけているんですけど、中身を見るとやっぱり誘導しているんですよね、新成人に対して。こういうことがされていいのかな。私はその答えも聞きたいんですけど、時間がありませんので結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":344,"id":"exchange-141"},{"speaker":"嶋委員","kind":"質問・要望","question":"私からは３点についてお伺いします。昨年の１２月にやはり八潮の中でも未遂の事件が幾つかありまして、暗いところがありまして、すぐ区のほうに地域の方が要望いたしまして、すぐそのところに街灯が設置をされたということで、地域の方もすぐ対応してくれた、すぐ区が反応してくれたということで大変喜ばれています。","respondent":"杉浦生活安全担当課長","answer":"この方々にジャンパーというお話でしたけれども、そのようなたぐいのもの、そういったものを対応していきたいというふうには考えてあります。","voiceIndex":346,"id":"exchange-142"},{"speaker":"嶋委員","kind":"質問","question":"じゃあすぐそういうジャンパーとか保険に対応していただけるということで、よろしいんでしょうか。もう一度。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":348,"id":"exchange-143"},{"speaker":"嶋委員","kind":"質問・要望","question":"二つ目の人権啓発意識調査ですが、ちょっとこれは初めてなのか、何回目なのか、また、どのような規模でやられるのか、ちょっと内容をお聞かせいただきたいと思います。","respondent":"阿部人権啓発課長","answer":"これは概ね５年ごとにやってございまして、平成５年、平成１１年、今回平成１６年、３回目です。規模としては、区民の方、１８歳から８０歳未満までの方で、２,０００名の方の調査をしております。","voiceIndex":352,"id":"exchange-144"},{"speaker":"嶋委員","kind":"質問","question":"３回目ということで、今回１８歳から８０歳までということですが、この人たちをどのような形で選んでいかれるのか、また、この調査をして、その結果、どのようにこれを活用されるのか、ちょっとお聞きをしたいと思います。","respondent":"阿部人権啓発課長","answer":"それで、結果をどのように生かしていくかですけれども、前回の調査の中では、例えば人権尊重都市宣言の普及がもう一つだということでございましたので、その辺は例えば区有施設に宣言板を設置しながら宣言の普及を図る、あるいはさまざまな集いの中で宣言の普及を図る。","voiceIndex":354,"id":"exchange-145"},{"speaker":"嶋委員","kind":"質問","question":"無作為ということですので、でも、年齢が制限があるので、無作為もどのように無作為でやられるのか、ちょっとお聞きをしたいところです。それからあと、どのようにこれを進めていかれるのか、いつぐらいまでに作成をされるのか、ちょっとお聞きをいたします。","respondent":"阿部人権啓発課長","answer":"それとどのように選ぶかということですけれども、住民基本台帳より抽出して選んです。時期としては、前回は６月の１カ月で区民の方に配布して回収したですけれども、今回につきましても大体６月ぐらいには送れるような形で調査項目を選んでいきたいというふうに思ってあります。","voiceIndex":356,"id":"exchange-146"},{"speaker":"嶋委員","kind":"質問・要望","question":"はい、わかりました。ぜひよろしくお願いいたします。今回３回目ですので、過去の１回、２回のいろんな課題もあったかと思いますが、３回目ということで、なおすばらしいものをつくっていただきたいと考えていますので、よろしくお願いいたします。３点目にまいります。１５７ページの庁舎管理。そういうお声がありましたら、お聞かせをいただきたいと思います。","respondent":"西島経理課長","answer":"お話は喫煙コーナーのお話をされているんだろうと思いますけれども、区のほうでも分煙ということで方針を出しまして実施をしています。","voiceIndex":358,"id":"exchange-147"},{"speaker":"嶋委員","kind":"質問・要望","question":"なお一層区民が役所に来て、皆様がほんとうに安心して利用できる庁舎にしていただきたいと思います。その中で一つ、私たち議員が使わせていただいている１階の駐車場について、ちょっとお尋ねをいたします。これから障害をお持ちになった議員も誕生されることもあるかと思いますので、そのときに兼ねるということもありますので、そこに対してちょっとお考えを聞かせいただきたいと思います。","respondent":"西島経理課長","answer":"あそこは出たところがすぐ車の通路ということになりますので、ちょっと工夫が必要かと思いますけれども、どうしたら段差が解消できるのかということについて研究してまいりたいというふうに考えてあります。","voiceIndex":360,"id":"exchange-148"},{"speaker":"嶋委員","kind":"質問・要望","question":"大変狭いところで設計上大変難しいかと思いますが、ぜひ工夫をして実現していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":362,"id":"exchange-149"},{"speaker":"三村委員","kind":"質問","question":"私のほうからは、１６９ページ、次世代育成支援行動計画策定についてと、１６５ページ、予算関係事務費について、１５３ページ、非核平和都市品川宣言事業についてお伺いをいたします。最初に１６９ページの次世代育成支援行動計画策定経費についてお伺いをいたします。","respondent":"榎本行財政改革担当課長","answer":"それで、この次世代行動育成計画の中で、住民参加と情報公開というのが求められておりまして、その中でそういう地域協議会を設けて原案についてというか、計画を策定するに当たって十分意見を聞くようにという形で方針を立てております。","voiceIndex":364,"id":"exchange-150"},{"speaker":"三村委員","kind":"質問・要望","question":"ぜひそうした取り組みを進めていただきたいと思います。今年１月、日本政府は子どもの権利条約の締結国として、子どもの権利条例の実施状況について、国連から２回ほど勧告を受けております。ぜひ計画の中に子どもの権利をどういうふうに位置づけるのか、また、計画策定段階で中高生や若者の参加の場をどういうふうにつくっていくのか、この２点についてお考えをお聞きいたします。","respondent":"榎本行財政改革担当課長","answer":"中高生、若者の意見をどういうふうに反映させればいいかということにつきましては、今庁内の検討会も設置しておりますので、その中で十分そういう意見が反映できるような形を検討していきたいというふうに考えております。","voiceIndex":366,"id":"exchange-151"},{"speaker":"三村委員","kind":"質問・要望","question":"ぜひなるべく直接的な形での参加をご検討いただければと思います。参加というところでもそうなんですけれども、評価、人数調査といったところで、今ある施策が次世代育成支援策としてほんとうに当事者に求められているのか、若者や子育て当事者に評価をしてもらうといった視点も必要かと思いますけれども、そういった点についてのお考えをお聞かせ願います。","respondent":"榎本行財政改革担当課長","answer":"実際にその行動計画の具体的な部分につきましては、そこのそういう審議会の中でもいろいろ意見を聞いていくという形で思っておりますけれども、さらにそういう中高生の意見等が反映できるものも、例えば今行っている電子アンケートですとか。","voiceIndex":368,"id":"exchange-152"},{"speaker":"三村委員","kind":"提案","question":"前回決算特別委員会のほうで私質問させていただいたんですけれども、子育て支援といったところでは、男性の子育て参加の不足ということがかなり大きく言われておりまして、男性職員の育児休業の義務化といったものを提案したんですけれども、それに対しての品川区の取り組み状況、その後、そのときは検討していくということだったんですけれども、その後の状況報告をお願いしたいと思います。","respondent":"桑村人事課長","answer":"その意味で、義務化というのはなかなか難しい状況ですけれども、何かとりやすい状況、あるいは目標数値みたいな設定ができれば十分検討に値すると思いますので、その辺のところを十分検討してまいりたいと思います。","voiceIndex":372,"id":"exchange-153"},{"speaker":"三村委員","kind":"質問・要望","question":"この報告書の中では、特定事業主行動計画は企業が策定する一般企業主の行動計画の模範となるべきものとしておりますので、ぜひよろしくお願いいたします。引き続きまして、予算関係事務費についてお伺いいたします。生活者ネットワークでは、以前より予算書、決算書を見やすくしてほしいと要望しておりましたけれども、どういった工夫がされているのか、お伺いをしたいと思います。","respondent":"市岡企画財政課長","answer":"予算書、決算書をわかりやすく、見やすくということですが、もう少し具体的なところもお聞かせ願えればと思いますが、私ども、まずこの予算書に関しましては、基本となっておりますのは、地方自治法とそれから地方自治法の施行令、政令、それから省令に定める一定の様式。","voiceIndex":374,"id":"exchange-154"},{"speaker":"三村委員","kind":"質問","question":"委託等の内容が説明でそのままわかるようにしていただけるととてもわかるんですけれども、ぜひそういった視点でよろしくお願いします。","respondent":"市岡企画財政課長","answer":"ただ、ちょっとご答弁させていただければ、予算書はなるべく簡潔明瞭にするということを中心に努力をいたしますが、これだけですべて今おっしゃられたような事業の内容を紙で説明し切ることはなかなか難しいこともあろうかと思いますので。","voiceIndex":376,"id":"exchange-155"},{"speaker":"三村委員","kind":"質問・要望","question":"１５３ページの非核平和都市宣言品川事業についてお伺いいたします。非核平和都市品川宣言２０周年記念事業として行われます平和のモニュメントは、どういったものにしようかと考えていらっしゃるのか、また、委託の方法や時期について教えていただきたいと思います。","respondent":"宮地総務課長","answer":"どういう形で発注するかということですけれども、製作しているところが幾つかありますので、そういったところに見積もりを提出していただきながら、ちょっと検討してまいりたいというふうに考えております。","voiceIndex":378,"id":"exchange-156"},{"speaker":"三村委員","kind":"提案","question":"記念事業としてタイムカプセルに次世代を担う青少年の作文や感想文を入れるという企画は、みんなで平和を考える企画として大変よいことだと思いますけれども、そこで提案をいたしたいんですけれども、モニュメントの平和をイメージさせるデザインというものをコンペ方式で募集してはと思いますけれども、お考えについてお聞きをしたいと思います。","respondent":"宮地総務課長","answer":"さまざまな方法があろうかと思いますので、その方法につきましては、いろいろな角度から検討し、決定をしていきたいというふうに思っております。","voiceIndex":380,"id":"exchange-157"},{"speaker":"須貝委員","kind":"質問","question":"１６９ページから１７０ページ、防火防災について、続きまして１５９ページ、青少年対策費についてお伺いいたします。防火についてなんですけど、今アメリカとかイギリスは住宅用火災警報機、アメリカなんかは約９４％のお宅に火災警報機が設置されている。イギリスは約８１％設置されている。こういうことを施策として防災課のほうで考えていますでしょうか、ちょっとご意見を。","respondent":"久保田防災課長","answer":"これまで実は、そういう配達の形をとっていたんですけども、置いておくということもこれからは可能ですので、そういう点での対応もしていきたいというふうには考えております。","voiceIndex":383,"id":"exchange-158"},{"speaker":"須貝委員","kind":"質問・要望","question":"現実的に死亡またはこれだけ品川区は今密集住宅街がほんとうに多いということなんで、街づくりの観点も含めまして、区のほうで早急にやはり実施していただきたいと思います。次に、青少年対策費についてお伺いいたします。じゃあ知らない人が、その場にいて、お店に来て販売する、さようならと。ですから、今地域活動課でやっている青少年対策という活動を、逆にその予算を地元地域に振り分けたらどうなのか。","respondent":"志村地域活動課長","answer":"ですので、私どもではこうした事業を各地区において、それぞれ特色ある事業を支援させていただいていますので、これにつきましても、引き続きまして行っていきたいと、かように考えてあります。","voiceIndex":385,"id":"exchange-159"},{"speaker":"須貝委員","kind":"質問・要望","question":"今いい話をお聞きしたんですけど、ほんとうにその地元で、地元の人がふだん知っている先輩、後輩、また、おじさん、おばさん、そういう触れ合いがなければ、いくら活動しても何にも残らないんですね、子どもにも。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":387,"id":"exchange-160"},{"speaker":"石田委員","kind":"質問・要望","question":"それから１５７ページ、庁舎等維持管理費であります。その関係でいかせていただきます。文書管理費というところなんですが、ちょっと大分あれなんですが、常任・特別委員会の報告事項のことについてちょっとお伺いをしたいと思います。ここら辺のところは総務で一括してそこら辺のところをやっていらっしゃると思うんですが、ここら辺のところを、もう一度再度確認をさせていただきたい、その流れを。","respondent":"宮地総務課長","answer":"例えば両委員会にまたがるものとか、いろんな意味で実務調整が必要です。その後、資料等につきましては、委員会開催の２日前には関係議員の方々に資料をお渡しできるように区議会事務局に各事業部から提出しております。","voiceIndex":389,"id":"exchange-161"},{"speaker":"石田委員","kind":"質問","question":"そこでお聞きをしたいのは、報告をする追加の部分でも何でも構わないんですが、総務部として、今委員会でこういうものを１年間、事業部でも結構です、事業部で考えて、これは大切な事業を今行っているよ、各委員会の中でこういうのを非常にずっと報告もしてきて、こういう重要なことがあったら、何かがあったら、それはすぐ報告しなさい、そういうことを助役からでもいいですが、どこからでも。","respondent":"宮地総務課長","answer":"それぞれ委員会の中でもいろいろな経過がございまして、常に毎年同じものでも報告していったほうがいいというところでは報告する案件もありますし、定例化しているものでしたら、報告しないでもいいという。","voiceIndex":391,"id":"exchange-162"},{"speaker":"石田委員","kind":"提案","question":"各そういうところがやっているでしょう。そういうところが議会と両輪ということであれば、そこら辺の把握はやっぱり総務部でしていただきたいなと私は思っております。そういう助役に上げる流れもあるのであれば、そこら辺のところは非常にやっていただきたいな。具体的なことをいいます。地元の人にそういう提案をした。１月２０日に文教委員会があります。そこら辺のお考えを聞かせていただきたい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":393,"id":"exchange-163"},{"speaker":"石田委員","kind":"質問・要望","question":"それが、ちょうど、それはいいです、聞いてわかればいいけど、公の委員会があるわけだから、私はちゃんと公の委員会の中で最終案を提示するならば、それは教育委員会に言っているわけじゃなくて、各事業部でいろいろあるんで、それは総務が取りまとめているんであれば、こういう長い間、２年も３年もやってきた重要なものについては、助役からでも構わないけれども、総務でもいいけれども。","respondent":"濱野助役","answer":"しかしながら、議会の皆様方が区の行政について議会の外から初めてお聞きになるというようなことは避けていかなければならないというふうに考えてありますので、そういう意味で、今後重要な案件について適切なタイミングをとらえてご報告申し上げる。","voiceIndex":396,"id":"exchange-164"},{"speaker":"石田委員","kind":"質問・要望","question":"ぜひよろしくお願いします。時間があれなんで、庁舎等の維持管理費にいかせていただきたいと思います。こういう形の中で、この庁舎管理について、どれぐらい今までかかってきていて、それでなおかつ、通常に電気代とかそういうことではなく、今後庁舎を維持管理するために幾らぐらい見込んでいるかということをちょっと教えていただきたい。","respondent":"西島経理課長","answer":"一般的に鉄筋の建物ですので、耐用年数は５０年から ６０年というふうに言ってありますけれども、その中でやはり１０年置きぐらいに直さなければいけない部分というのはどうしても出てまいります。","voiceIndex":398,"id":"exchange-165"},{"speaker":"石田委員","kind":"意見","question":"そうなってくると、今後そういうことをどういうふうにとらえて準備をしていくところは準備をしている、そうじゃなくて、基金は基金でボーンと入れるんだから大丈夫だぞ、こういうのも一つの考えでありますが、今後、その部分の基金をどういうふうに使っていこうか、またなおかつそういう部分のときの１０年間の基金を逆にそういうふうに考えていくのか、そこら辺をお考えをちょっとお聞かせ願いたい。","respondent":"市岡企画財政課長","answer":"この庁舎をどうするかという点については、多角的な検討が要ると思いますが、ちょっと基金のことだけ申し上げると、私どもの公共施設整備基金というのは、公共施設の整備に使うと条例にはっきり書いてありまして、この建物は１字違いで、大変恐縮ですが、公用財産。","voiceIndex":400,"id":"exchange-166"},{"speaker":"石田委員","kind":"質問","question":"それはぜひ３６年ということであれば、１０年計画でやったとしても４５年、実質問題、いろいろやっているところは４５年から５０年ぐらいで建て替えているところが多いのは現実だと思います。ですから、そういうふうに１０年かかるんであれば、そういうことも考えながらやっていく、そろそろそういう時期かなとも思っておりますので、ひとつ、区長、時間がないからいいです。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":402,"id":"exchange-167"},{"speaker":"土井委員","kind":"質問・要望","question":"私は１７９ページの住民基本台帳費、それに関連をして１８９ページの監査委員費で伺うこと。それから、１６１ページの、先ほどからいろいろ出ております生活安全にかかわる課題、この大きく２点についてお伺いをしたいと思います。その上で、本会議でもご質問したんですが、もう一度確認の意味で件数、どれだけ我が区ではこの間に使ったのかというのを聞かせていただきたいと思います。ここまではわかった。","respondent":"冨田戸籍住民課長、南監査委員事務局長、杉浦生活安全担当課長","answer":"当区の住基ネット関連の件数ですけれども、先日の一般質問の中でお答え申し上げましたのは、１月末現在の数字でございましたけれども。従来、監査委員の監査というのは財務関係が中心でございましたが、住基ネットの監査が必要だということで。２点あったと思います。一つは、サポート隊の活動と我が町パトロールを整理して説明を、こういうことです。","voiceIndex":404,"id":"exchange-168"},{"speaker":"土井委員","kind":"確認","question":"住民基本台帳の関係なんですけれども、今申し上げたように、機械をリースするのに ２,１００万円、これからもずっとかかりますよ、大体そういうことですよね。そして、カード作成等に３９０万円という中身ですよと。それで実際に恩恵に預かってするのが先ほどお伺いしたような件数、今のところそういう件数だと。生活のパトロールですが、確認をします。だから、その辺だけ伺います。","respondent":"冨田戸籍住民課長、杉浦生活安全担当課長","answer":"住基ネットの費用対効果の点ですけれども、この住基ネットが議論されたのが平成１１年のころですけれども、そのあたりでは、住民負担の軽減とそれから国、地方の効果、あわせて５００億円。生活安全サポート隊と我が町パトロールは一体じゃないかというお話ですが、これは一体ではありません。別の組織です。","voiceIndex":408,"id":"exchange-169"},{"speaker":"南委員","kind":"質問","question":"私も次世代育成支援対策推進法について伺います。何人かの委員がご質問されておりました。改めて今回国がこういう法律を制定して、行動計画策定を自治体に義務づけている、そこの思い、ねらいというのはどういうところにあるのか伺いたいと思います。","respondent":"榎本行財政改革担当課長","answer":"それで、基本理念としては、保護者が子育てについての第一義的責任を有するですけれども、それをさらに社会全体でどういうふうに支援していくかというものの見方でこういう行動計画を１０年間のスパンでやっていこうという形です。","voiceIndex":412,"id":"exchange-170"},{"speaker":"南委員","kind":"質問・要望","question":"少子化はもう一度伺いますけども、改善されてこなかったというふうに私は思うんですけれども、その点についてはどういうふうに品川区としては品川の現状を見ながら認識を持っていらっしゃるか、ちょっと伺います。","respondent":"榎本行財政改革担当課長","answer":"それで、今現在、本会議のほうでもありましたけれども、０歳から９歳ぐらいまでのお子さんについては人口が増えてきている。それ以上についてはちょっとその前の動向がありましたので、減っているというような形です。","voiceIndex":414,"id":"exchange-171"},{"speaker":"南委員","kind":"質問・要望","question":"それで、その行動計画の中で、やっぱり今申し上げたように、ほんとうに現状を変えなくてはいけないというふうに思うわけですけれども、改めてどこにどういうふうに重点的に行動計画の内容を盛り込んでいこうというふうに思っているのか、その点をちょっと伺いたいと思います。","respondent":"榎本行財政改革担当課長","answer":"大きく七つの項目がございまして、地域における子育ての支援、母性ならびに幼児、乳幼児の健康確保、それから教育環境の整備、生活環境の整備、職業生活と家庭生活の両立の推進、子ども等の安全の確保、要保護児童への対応など。","voiceIndex":416,"id":"exchange-172"},{"speaker":"南委員","kind":"質問・要望","question":"それからもう一つは、現状をやっぱりきちんと分析、現状分析中だというふうにおっしゃいましたけれども、現状分析というのは、どういう範囲でやられているのかというのをちょっと伺っていないので、改めてそこは教えていただきたいんですけれども、私は現状分析というのであれば、やっぱり今区民がどういうふうなサービスを求めていられるのか、そしてそれに対して品川区はどこまで到達しているのか。","respondent":"榎本行財政改革担当課長","answer":"ニーズ調査の関係につきましては、具体的に今後どういうふうにニーズを調査していくかというのがありますけれども、既に行われているこの１８０近い事業の中で、実際上、各事業を推進していく中では、いろんな要望等も聞いておりますので、ほんとうに必要があるところがあれば。","voiceIndex":418,"id":"exchange-173"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、改めてこういう行動計画をつくり、２１世紀のこの時期に国を挙げて次世代育成で子どもを安心して、喜びを持って育てられる、その育てることに誇りを持って育てていけるという、そういうほんとうにうれしくなるような、そういう行動計画をつくるに当たっては、やっぱりきちんとした現状分析、ニーズ調査というものをしっかりしていかないと。","respondent":"榎本行財政改革担当課長","answer":"２点にわたってのご質問で、まずニーズ調査の関係ですけれども、今年度は世論調査等も実施してまいりますので、その中でも十分そういうニーズを図っていかれるかなというふうに考えております。","voiceIndex":420,"id":"exchange-174"},{"speaker":"南委員","kind":"質問・要望","question":"公募枠もほんとうに２けたぐらいとっていただきたい、そういうふうに強く要望しておきたいと思います。したがって、今の品川区がやっている子育て支援サービス、それから区民の皆さんがほんとうに求めている支援サービス、こういうものがほんとうにぴったり合致するのかというところを、やっぱりよくつかむ必要があるというふうに思うんですね。","respondent":"中尾根企画部長","answer":"従来子育てということになりますと、どうしても施策的に保育中心の施策を打ってきたというのが現状です。国全体としても、なかなかこの少子化の社会現象を乗り越えることができないということですから、新しい時代に向かってのコンセプトは働きやすい環境をつくるということです。","voiceIndex":422,"id":"exchange-175"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、それが民間活力導入ということで、営利を目的とする企業の参入だとか、そういうことも含めてやっていくという、そういうことはやっぱり違うんじゃないかなというふうに思いますので、そこは十分検討していただいて、ほんとうにいい、そういう行動計画をつくっていただきたいということを強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":424,"id":"exchange-176"},{"speaker":"堺委員","kind":"質問・要望","question":"それから２点目が予算書の１６１ページ、先ほど来から出ております生活安全サポート活動、これに関連しまして、やはりプレス発表の資料によりますと、生活安全サポート隊による交番への立ち寄りも含めた云々と、こうなっておりますので、まずこの件については、交番、ちょっと私事前に申し上げていなかったので申しわけないんですが、今品川区内にある交番の数と、そのうち空き交番が幾つあるのか。","respondent":"宮地総務課長、杉浦生活安全担当課長","answer":"さまざま方法はあろうかと思いますが、今後これに取り組む中でいろいろ検討してまいりたいというふうに考えております。それにつきましては、これまで１０カ所の交番に立ち寄ってあります。これまで１５０回以上の立ち寄りを実施しております。","voiceIndex":426,"id":"exchange-177"},{"speaker":"堺委員","kind":"質問・要望","question":"要するにこの非核平和都市品川宣言、これは２０年前に出されましたけども、「核兵器廃絶と恒久平和確立の悲願を込めて、ここに非核平和都市を宣言し、全世界に訴える」、こういう一文もありますが、そういう関連からいきますと、せっかくの記念行事ですから、区内にあるそういう在日公館の方々にもそういう大事な記念のイベントに参加していただく、そういう意味からも、参加要請というんですか。","respondent":"宮地総務課長、杉浦生活安全担当課長","answer":"それから２６日には記念講演があります。２５日にはモニュメントの除幕式等、いろいろな場面で参加の場面はあろうかと思いますけれども、広く、国際友好協会等も通じながら呼びかけをしていきたいというふうに考えております。ただし、運用の面でなるべく区民の皆さんに姿を見せるということも大切なことでありますので、通常の連携を通じて申し入れをしていきたいなというふうに考えてあります。","voiceIndex":429,"id":"exchange-178"},{"speaker":"堺委員","kind":"質問・要望","question":"これについて、例えば３月２日、都議会の本会議で私どもの幹事長が代表質問の中で、この点についても、「東京都としても、約１,０００人規模の警察官等の増員、１００地区の防犯カメラの設置、防犯設備に対し、区市町村への補助など、総合的に取り組むことになっているけども、地域住民のきめ細かな治安、防犯ニーズに応えるために、区市町村とも連携して対応すべきであります」、こう質問をした際に。","respondent":"杉浦生活安全担当課長","answer":"そのように申し入れをしたいと思います。","voiceIndex":432,"id":"exchange-179"},{"speaker":"塚本委員","kind":"質問","question":"私のほうからは指定管理者制度の導入に関連してお伺いいたします。昼間の時間帯にも他会派から同様の質問がございましたけど、私はちょっと視点を変えてです。管理委託制度のもとにいろんな事業を委託しております。相手は公的団体でなければいけないということで制約があった。","respondent":"榎本行財政改革担当課長","answer":"それからあとはその中でランニングコストの縮減というものもあります。さらにもう一つ重要なのが、民間経営の発想やノウハウを取り入れることができるという部分が大きなメリットとして考えられているところです。","voiceIndex":435,"id":"exchange-180"},{"speaker":"塚本委員","kind":"質問","question":"ちょっと皮肉な言い方ですけれども、従前の方法じゃそういうものが欠けているという認識があるということですね。具体的にもう少しどういうことでコストが縮減されるのか、同一労働で賃金が違うのか、あるいは効率的な経営をしているのか、あるいは柔軟な発想とは一体何なんだ、それは役人にそういうものがなくていいのかという話になりますね。その３点についてお伺いいたします。","respondent":"榎本行財政改革担当課長","answer":"実際にその中でも創意工夫を図ってコスト縮減には努めておりますけれども、実際上そういう公共的団体等で働く職員の部分で区の職員が行っている場合もありましたし、もしくはそうでなく、固有でやっている場合もありますけれども、その中でのコストのところを考えたときには。","voiceIndex":437,"id":"exchange-181"},{"speaker":"塚本委員","kind":"質問","question":"官のほうもフレキシブルな考え方が必要ですよということで、ある意味じゃ現場をどんどん失っていくということがあるわけですね。それから、先ほどこの庁舎は公用の施設だという話がありました。公共施設ということは一般用語ですけれども、この中に公の施設という、管理委託ができるのは公の施設ということがうたってありますけれども、この三つの言葉の違いというのをちょっと教えていただければありがたい。","respondent":"市岡企画財政課長","answer":"ただし、ちょっと難しいのは、公の施設の中でも、個別法で、例えば道路法だとか、都市公園法で公共施設の中だけど、その法律の網がかぶっておりますので、例えば道路管理者をこの指定管理者に変えることはできないという個別法の規制がかぶっていると。","voiceIndex":439,"id":"exchange-182"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。公の施設というのは、条例で決めたものがそうだ、性質別で、これを条例で決めるか決めないかという境の認定、どういう考えのもとになっているのか、公の施設、改めて教えていただかないと、条例があるからそうだということじゃなくて、性質別といいますか、別の概念分けをしていただかないと、なぜこれが条例で決めなきゃいけないのかということがちょっとわかりにくいと思うんですけれど。","respondent":"市岡企画財政課長","answer":"難しく言うといろいろとあると思うんですが、簡単に言えば、その利用関係を公平かつ的確にやるため、例えば利用承認をするときに、ちゃんと公平なルールで決めなければいけないような、対住民との関係で公平性を担保するためには、条例で議会の議決を得て、管理運用のルール。","voiceIndex":441,"id":"exchange-183"},{"speaker":"塚本委員","kind":"質問","question":"現実に公園などは違った形で管理したほうが非常に能率的であるという側面があろうかと思うんですけれども、方向性のことについて見解があれば伺います。","respondent":"市岡企画財政課長","answer":"ただし、各施設いろいろありますけれども、例えば児童福祉施設や何かについても、これはいろいろな意味で結果がどうなるかはわかりませんが、検討していることは確かだというふうに聞いてあります。","voiceIndex":443,"id":"exchange-184"},{"speaker":"塚本委員","kind":"質問・要望","question":"やはり現場とのやりとりといいますか、自治体が実際にやってみて、不具合、具合等を中央とやりとりすることが大事だと思いますので、そのメッセージをしっかりと伝えていただきたいということを願っておきます。一々飛んで行って相談していたんじゃ余計、二重の手間になってコストがかかるわけですので、そういうことに関する考え方みたいなものは確立しているのかどうかということを教えていただきたい。","respondent":"榎本行財政改革担当課長","answer":"ただ、あくまでも条例の枠組で使用料等を決めておりますので、その中にどれぐらいフレキシブルな考え方が入れられるかという形になっていると思います。","voiceIndex":445,"id":"exchange-185"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぷりすくーるのようなさらのところからできたものならよろしゅうありますけれども、既設のものを扱って、おまえの管理責任だというようなことを言われてはかなわないということは、当然請負側にはあろうかと思いますけど、その辺の心配を一つと、それから指定管理者がその下にいろんな仕事をまた出すということがあろうかと思うんですけど、それに対する基本的な考え方。","respondent":"榎本行財政改革担当課長","answer":"既設の、既につくられた区立の施設についての指定管理者への委託のときの責任の問題ですけれども、あくまで施設の設置というのは区で行っておりますので、最終的な責任は区が負うという形になっておりますけれども、実際上は指定管理者の指定によって。","voiceIndex":447,"id":"exchange-186"},{"speaker":"塚本委員","kind":"質問","question":"現実にそれから改善命令、指示、どういう言葉を使うのかわかりませんけれども、いろんな苦情が私どものほうに寄せられたり、あるいは他から指摘されることがあろうかと思いますけれども、そういうチャンネルといいますか、発注がどういうことができるのか、あるいは部局がどうなっているのか、一貫してやるのか、あるいはそれぞれ今まで所管した課が現場に行ってやるのか、その辺のことを伺いたいと思います。","respondent":"榎本行財政改革担当課長","answer":"それとあと、指定管理者への管理監督の部分ですけれども、その施設の適正管理をしていく中で、部局についてはそれぞれの区の施設を持っているところが当たっていくという考えでおります。","voiceIndex":449,"id":"exchange-187"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=824#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":129330,"voices":451}},{"id":"h16-20040310-3","meetingId":"h16-c-budget","date":"2004年3月10日","dateIso":"2004-03-10","committee":"予算特別委員会","time":"午前１０時０５分～午後６時４１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を173件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"私は今日お伺いするのは、民生費のうち１９１ページの民生委員経費、１９９ページのかかりつけ医・歯科医定着促進事業についてお伺いをしたいと思います。民生委員が２９６人と書いてありますけれども、現制度では２８０人と承知しております。差し引き１６人でありますけれども、この１６人という数字の根拠といいますか、どういうところから１６人という増員がなされたのかご説明願いたいと思います。","respondent":"日下部障害者福祉課長","answer":"民生委員の増員の関係です。今回、２９６人ということで、今ご指摘がございましたけれども、実は民生委員につきましては３年に一遍、一斉改選ということで実施をしておりますけれども、その時期が今年の１２月にまいります。","voiceIndex":4,"id":"exchange-001"},{"speaker":"大沢委員","kind":"意見","question":"先ほど１２月ということですが、１２月の何日に改正があるのか、お答えをお願いしたいと思います。","respondent":"日下部障害者福祉課長","answer":"１２月１日付です。","voiceIndex":6,"id":"exchange-002"},{"speaker":"大沢委員","kind":"質問","question":"１２月１日に増員されるということですけれども、数といいますか、東京都と協議をしながら１６人ということを決められたということですが、品川区としては民生委員１人が担当する対象者の適当な数というのは、大体どのぐらいかご見解をお伺いしたいと思います。","respondent":"日下部障害者福祉課長","answer":"つまり、生活保護世帯の方あるいはひとり暮らしの高齢者の方であるとか、そういった一定の手を差し伸べる必要がある方がその世帯の中にどのぐらい含まれているのか、そういった点もありますので。","voiceIndex":8,"id":"exchange-003"},{"speaker":"大沢委員","kind":"質問","question":"５８０世帯ぐらいで、そのうちの何割かということで心得ますけれども、担当する側において民生委員が５８０世帯ということですけれども、自分の隣接の町会にまたがっているのが現状なんですけれども、そこの部分できちんと対処できるような半径何ｍといいますか、地区割の基準といいますか、何か基準みたいなものがあるんでしょうか。","respondent":"日下部障害者福祉課長","answer":"ただ、これは国、都の一つの考え方でもありますけれども、道路であるとかあるいは鉄道であるとか、いろいろな地形上の問題等もありますけれども、その地域の住民の皆さんにとってわかりやすい地域割といいますか、その辺が一つの考え方の基本になっているという面があります。","voiceIndex":10,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"今度は人の部分なんですけれども、どんなような基準で、例えば今、町会といいますか地域ごとにまたがっているわけですけれども、どういう対象者の方であればこの民生委員に任せよう、こんな種類の対象者の方であれば、この民生委員に任せようというような、そういう対象者の基準みたいなものはあるんでしょうか。","respondent":"日下部障害者福祉課長","answer":"民生委員の活動の基本というのは、地域住民の方にとって最も身近な福祉の窓口と、区と地域との一種のパイプ役を担っていくということでございまして、そういった意味では幅広く相談に対応するということが基本になってあります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問","question":"私、思うには、それではなおさら増員をされたということで、民生委員が対象とする方の人数が多いように見受けられますけれども、そういうことを鑑みて思うには、民生委員が１人でお持ちになる範囲といいますか、テリトリーが多くの町会にわたっているのではなくて、１町会を担当する民生委員の地区割みたいなものができてもいいような気がするんですが、どんなふうにお考えでしょうか。","respondent":"日下部障害者福祉課長","answer":"私ども民生委員ともいろいろご意見を伺ったんですけれども、今までのお付き合いとか信頼関係が急激に変わることについて、やはりいろんな心配もあるとか、いろいろそういう事情もありまして、一気に解消することがなかなか難しいという現状です。","voiceIndex":14,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問","question":"かかりつけ医・歯科医定着促進事業にいきます。最初に、事務事業概要によりますと、「区民が身近で気軽に適切な医療サービスを受けられるよう」と書いてあります。「区民」と書いてありますけれども、これは広く区民を指しているんでしょうか、それとも区民という文言に何か意味合いというのはあるんでしょうか、お伺いしたいと思います。","respondent":"田中健康課長","answer":"そういう方を含めて、紹介制度を一つ軸に置きまして、かかりつけのお医者さんにもっと身近に相談事ができるようにというのが、この制度の基本の考え方というふうに考えております。","voiceIndex":16,"id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"広く区民ということで、理解をします。ここにかかりつけ医と書いてありますけれども、医院といいますか、外科、内科とありますが、事務事業概要には四つ区分がありますけれども、この四つの区分で網羅なくかかりつけ医としての紹介窓口になっているんでしょうか。","respondent":"田中健康課長","answer":"一番簡単なところでは、通院のみを紹介している内容、それから訪問診療も含めて、通院と訪問で近くにそういう診療所があるかということ、それから特定疾患といいまして、難病ですとか、そういう方に対して対応できるところ、あるいは眼科、耳鼻科、皮膚科等々の専門という形です。","voiceIndex":18,"id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"１９９ページにかかりつけ医・歯科医定着促進と書いてあるんですが、歯科医は今まで入っていなかったんでしょうか。","respondent":"蓼沼高齢事業課長","answer":"平成１２年から年次計画でそれぞれポスター、ステッカー、リーフレット等、医師会のほうと協議しながら、効果的なＰＲを進めていこうということで、健康課と協力連携をしながら進めているというものです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"今度は受ける側からの質問なんですけれども、かかりつけ医調整委員会という委員会がありますけれども、この委員会では患者に対して自分たちが施した医術に関して満足度という、そんなような部分をＰＲとして考えて議論する委員会なのでしょうか、お伺いしたいと思います。","respondent":"田中健康課長","answer":"このシステム自体を調整する委員会でございまして、特に医師会、歯科医師会、それから区内の中核病院が含まれてあります。それから、福祉施設関係も含まれてあります。診療所で新たに病院の紹介ですとか、病院からの逆紹介ですとか、そういう内容を含んでいる調整の場です。","voiceIndex":22,"id":"exchange-010"},{"speaker":"大沢委員","kind":"質問・要望","question":"いずれにいたしましても、区民の声をフィードバックできるような、そしてさらにサービスに役立てるようなシステムづくりをお願いしたいと、制度にしていただきたいと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-011"},{"speaker":"嶋委員","kind":"質問・要望","question":"まずエレベーターの運用、コインランドリーの設置、介護予防の手引きについてお伺いをいたします。二つ目には、１９７ページの緊急通報システムについてお伺いします。三つ目に、２０１ページの障害児の地域での自立支援策についてお伺いいたします。それから、２１７ページ、児童センター運営費について、もしお時間があれば２１３ページ、保育園の園庭についてお伺いをいたします。","respondent":"早津高齢福祉課長、島袋品川区保健所衛生課長","answer":"要介護高齢者を対象としたサービスのほか、ご指摘のように４０代の方を対象にしたふれあい健康塾ですとか、そういった形でも実施しておりますので、こういった中で介護予防について一層取り組んでいきたいというふうに考えてあります。コインランドリーの設置につきましては、保健所に申請していただいて要件を満たせば許可できるです。八潮地区でも同じことです。","voiceIndex":26,"id":"exchange-012"},{"speaker":"嶋委員","kind":"質問・要望","question":"エスカレーターの運用は大変難しいということは、重々わかっておりますが、そういう意味ではやっぱり下りが大変厳しいということで、今後高齢化が進む、またそういう形の中でぜひ下りのエスカレーターの運用を始発とかいろいろあるかと思いますけれども、時間差でぜひお考えをいただきたいと考えています。","respondent":"日下部障害者福祉課長","answer":"コインランドリーの品川総合福祉センターへの設置の件ですけれども、この辺につきましては、そういうような地元の声もあるということで、品川総合福祉センターのほうに伝えまして、その辺の可能性についても検討を進めていくということにさせていただきたいと思います。","voiceIndex":29,"id":"exchange-013"},{"speaker":"嶋委員","kind":"質問・要望","question":"ありがとうございました。ぜひ、またよろしくお願いいたします。介護予防の手引きということも、ぜひお考えをいただきたいと考えていますので、よろしくお願いいたします。二つ目、１９７ページの緊急通報システムのことについてお伺いをいたします。今の現状のご説明をいただけたらと思います。","respondent":"早津高齢福祉課長","answer":"消防庁直結型のシステムと民間警備会社による連携システムという二つの種類がございまして、現状ということで申し上げますと、消防庁直結型のほうが平成１５年度１月時点ですが２３９人の利用、それから民間の直結型のほうが１２８人のご利用という状況です。","voiceIndex":31,"id":"exchange-014"},{"speaker":"嶋委員","kind":"質問","question":"そういう意味では、高齢者のみの世帯に火災報知機を設置していただけたら、こういうことがもう少し防げていけるのではないかと思いますが、火災発生時に消防庁に自動的に通報できるような火災報知機などの設置を考えておりますが、いかがでしょうか、お考えを聞かせていただきます。","respondent":"早津高齢福祉課長","answer":"火災報知機につきましても、対象者を同じくしての制度はあるんですが、あまり利用されていないという実態があります。今後の火災報知機についての考えについては、必要性等も含めまして、ちょっと検討させていただきたいというふうに思います。","voiceIndex":33,"id":"exchange-015"},{"speaker":"嶋委員","kind":"質問・要望","question":"せっかく消防庁に直結するシステムがありますので、そのシステムを利用して、火災によって亡くなるということがなくなるように、ぜひご配慮をいただきたいと、積極的に高齢者の安全を確保していただきたいと思いますので、どうぞよろしくお願いいたします。このことについて詳しくご説明をいただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-016"},{"speaker":"嶋委員","kind":"質問・要望","question":"今まで障害をもった子どもをお母さんたちが緊急時に預ける場所ということで、家庭あんしんセンターが１２歳まで、また１２歳以上１８歳までが昨年４月から品川総合福祉センターで見ていただけるということで、少しは障害を持った子どものお母さんたちの支援にはなってきているんですが、やはりいろんな障害によって、品川総合福祉センターで見ていただけない部分もたくさんあったので。","respondent":"日下部障害者福祉課長","answer":"それからもう一つは、ショートステイは通常７日間ですけれども、保護者の方が長期の入院をされたときに、７日ではとても対応仕切れないということで、今まで区では大島のほうにミドルステイ用ということで２床ほどベッドを持ってございました。","voiceIndex":37,"id":"exchange-017"},{"speaker":"嶋委員","kind":"確認","question":"そういう意味では充実されて、今までは八王子の先とか大島ということで、本当に親は預けたいけれども大島まで子どもを預けるのは、親自体が寂しい、心配だということで、なかなかそういうものが使えなかった。そういう意味では、今までは就労もいけなかったんです。今回の内容も就労もだめということなのか、確認をしたいと思います。","respondent":"日下部障害者福祉課長","answer":"就労ということになりますと、トワイライトステイの関係が出てくるかと思いますが、今申し上げましたように、共働きであるとか自営であるとか、この要望が強く出ておりますのは就労していらっしゃる方ですので、当然のことながら。","voiceIndex":39,"id":"exchange-018"},{"speaker":"嶋委員","kind":"質問・要望","question":"今回、図書館が全館８時までということになります。図書館と併用して児童センターがあると思いますが、児童センターの閉館時間が６時、７時のところもあるかと思いますが、それを図書館の閉館時間とともに児童センターの閉館時間も規則をつけて８時まで延ばしていただきたいという、中高生からの要望がありますが、いかがでしょうか。","respondent":"辻田児童課長","answer":"そういう中で、私どものほうも児童センターのあり方検討委員会というのを設置して、その中で検討してまいりました。","voiceIndex":41,"id":"exchange-019"},{"speaker":"嶋委員","kind":"質問・要望","question":"最後に、保育園の園庭のことです。春一番も吹いて、いよいよ春ということで、窓を開ける季節になりまして、園庭の砂塵で大変地域が困っているということで、家の中まで入り込んで、お掃除をしてもだめです。特に、日曜、祭日の保育園が休園のときにご配慮をお願いしたいという地域の要望がありますが、そういう点でお考えお聞かせいただきたいと思います。","respondent":"金子保育課長","answer":"保育園の園庭のお尋ねですけれども、確かに委員おっしゃるとおり、かなり強風の場合には砂塵等が舞って、近隣のお宅のほうにご迷惑がかかるということは、私どもも連絡をいただいて、対応については苦慮しています。","voiceIndex":43,"id":"exchange-020"},{"speaker":"嶋委員","kind":"質問・要望","question":"ぜひ、園庭の改良を。地元にお住まいの方たちが自分たちが散水をしてもいいという意見が出ておりますので、地域のボランティアを使ってもいいのなと考えています。そういうところもお考えをいただいて、ご配慮いただきたいと思います。ありがとうございました。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１９９ページの障害者福祉手当、難病手当のこと、あと１９７ページ、２０１ページの高齢者そして障害者の緊急通報システムと火災安全システムについてお伺いをします。よろしくお願いします。難病手当のところでは、若干特殊疾病の医療費の助成のほうにも連動してお伺いしますが、お許しをいただきたいと思います。何人の方が受けているのか教えください。","respondent":"日下部障害者福祉課長","answer":"この中に難病の医療費の助成を受けている方も含まれておりまして、現在のところ難病の方を対象にした手当といたしましては１,０５０人ほどです。","voiceIndex":47,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１,０５０人の方が受けていらっしゃるということなんですけれども、地域の方からぜひ難病手当を増やしてほしいという声をいただいていますので、聞いていただきたいと思います。手当の件も、結構いろんな交流会に出ると、品川区の１万円の額は決して多くないというか低いという状況の中で、ぜひ他区並みに引き上げていただきたいという声をいただいています。いかがでしょうか。","respondent":"日下部障害者福祉課長","answer":"ただ、私ども難病手当につきましては、あくまでも負担軽減の一助というような考え方で出させていただいているというものでございまして、そういった点では現状の月当たり１万円ということで給付をしていますが、これを増額するということは考えてございません。","voiceIndex":49,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問","question":"私のような福祉の谷間にいるような者はどうやって生きていけばよいのでしょうか」という、たくさんの病気の方が、ほとんどこういった目に見えた障害でないので社会的に理解されないというのと、やはり通院がずっと長引いているということでの経済的な負担をほとんどの方が訴えられていらっしゃるんです。これがとても大事であると思うんですけれども、再度お伺いします。いかがでしょうか。","respondent":"日下部障害者福祉課長","answer":"そういう状況を踏まえまして、手当の金額については、ただその金額だけで判断するというわけにはいかないというふうに考えておりますし、そういった点も含めまして、先ほどご答弁申し上げましたように、金額については現行どおりということで考えてあります。","voiceIndex":51,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"決して金額というか、全部横並びでいいと思いませんし、総合的にそれは判断するとは思うんですけれども、私はちょっと控えめに言ったんですが、品川区の難病手当はあまりにも低過ぎるのではないか。品川区より低いところがあるのでしょうか、金額的なところでの評価というのはどうでしょうか。","respondent":"日下部障害者福祉課長","answer":"ただ、ほかの区を見ましても、１万２,０００円であるとか、１万３,０００円であるとか、これはそんなに各区の手当の金額を見ましても大きく差があるというものではございません。","voiceIndex":53,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"支援というのは低いほうに揃えるんじゃなくて、やはり少しでも努力をして高いほうに引き上げていただきたいなと思います。もう一つ、保健所のところで特殊疾病の医療費の助成制度があると思うんですけれども、こことの関係というか、難病手当の仕組みを知らなくて受けていらっしゃらない方がいるので、この辺のお互いの連携プレーのところがどうなっているか教えてください。","respondent":"日下部障害者福祉課長","answer":"じゃ、手当のほうについては区役所のほうに行ってくださいということでは、これはやはりあまりにも縦割りということで、難病の方々に対して非常に不便な仕組みですので、これにつきましては平成元年から保健所で手当の申請についても受け付けをするということで。","voiceIndex":55,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ、連携を取って、漏れがないようにしていただきたいと思います。平成元年からですか、実際に去年のところで、難病手当のところが漏れている方がいらっしゃったんです。やっぱり、こういう姿勢が大事だと思いますが、いかがでしょうか。","respondent":"日下部障害者福祉課長","answer":"私ども、通常の窓口の対応でも、保健所のほうでもしっかりやっていただいているというふうに思いますけれども、間々そういった漏れが全くないとは言い切れない面がありますので、その辺はしっかりとさらに連携を取りまして。","voiceIndex":57,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"申請をしないと受けられないというところでは、ぜひ申請をしやすい、また漏れがない、優しい周知をよろしくお願い申し上げます。緊急通報システム、先ほども質問が出ていましたけれども、消防庁直結と民間のほうに委託している違いを教えていただきたいんですけれども。","respondent":"早津高齢福祉課長","answer":"消防庁直結型と申しますのは、ボタンを押したときに消防庁に連絡が行く一方、近隣の方で３名の協力員という方をお願いしています。","voiceIndex":59,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"消防庁直結のほうは近隣の方とのネットワークがとても重視されていて、いい制度だと思うんですけれども、これを利用したいという方から、消防庁直結のほうが受けにくくて、民間のほうを紹介されるようなお話を伺ったんですけれども、資格要件でこれが違う部分があるんでしょうか。","respondent":"早津高齢福祉課長","answer":"消防庁直結方式の場合は、協力員が３名必要というようなことで、そういう点がなかなか難しい方がいらっしゃるのではないか。そういうような方の場合ですと、協力員の要件もございませんので、民間のほうをお薦めしているという状況です。","voiceIndex":61,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"慢性疾患と急変するような状況の人、慢性疾患というのはたくさんいらっしゃるけれども、急変するかしないかというのは、なかなか判断が難しいんだと思うんです。この辺は、すごく基準があいまいであるなと思うんです。協力員３名の方がしっかり確保できて、やはり日常的に不安で、この制度を使いたいという方には、ぜひ申請を受理していただきたいんですけれども、いかがでしょうか。","respondent":"早津高齢福祉課長","answer":"具体的には、ケアマネージャーが訪問した上で相談をしていますので、個別的な内容につきましては、ケアマネージャーのほうと遠慮なくご相談いただければというふうに考えてあります。","voiceIndex":63,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ありがたいご答弁をいただきました。ケアマネージャーをとおしてということなので、個別的な状況をしっかりつかんでいただきたいと思います。安心のシステムなので、できるだけたくさんの方にご利用をいただいて、安心していただきたいと思います。だから、申請にあたってはハードルを高くしないで、ぜひ希望する多くの方が利用できる制度にしていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-031"},{"speaker":"高星委員","kind":"質問・要望","question":"だから、こういうこともありますものですから、その辺のところを今申し上げました生活安全サポート隊や我が町パトロールの仕事の中にリンクできるのかどうなのか、基本的な考え方をお聞かせいただきたい。２１５ページのほうは施設のほうなんだけれども、こちらのほうは３園というふうになっていて、２０９ページのほうは１園となっているので、この違いを教えていただきたいなというふうに思います。","respondent":"黒田生活福祉課長、金子保育課長","answer":"私どもは、そういうところでは区を挙げて取り組むということで、今回生活安全の担当ができましたので、区民の方が声を上げていただいて動いていただいて、行政も取り組む中で、継続的にやっていく中で。２０９ページの病後時保育１園といいますのは、私立保育園で１園お願いしていますので、これに対しまして東京都から補助が来ておりますけれども。","voiceIndex":67,"id":"exchange-032"},{"speaker":"高星委員","kind":"質問・要望","question":"この方は病気なんですね。昔からあるじゃないですか、宣伝でもやっていますね、お母さんが本当に子どもを愛すことができなかったら、何にも言わなくていい、抱きしめろという、これはまさに保育の原点というか、人間としての本能なんだろうというふうに。基本的には政治そのものが、やっぱり会社とかを説得して、そういうときに休みを取らせるような制度の問題だというふうに思うんですが、どうでしょうか。","respondent":"金子保育課長","answer":"品川区内の保育室の助成をしていた部分につきましては、全施設とも認証保育所への移行という考え方を持っていまして、予定によれば平成１６年度については全施設とも認証保育所のＢ型移行が完了するということで、私どももそういったレベルアップということに関しましては。","voiceIndex":70,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"かがやき園です。平成１６年５月の開所、もう間もなくだと思うんですが、すばらしい施設ができてくる。どう考えるべきかということ。それから、もう１点、ケアホーム西五反田も間もなく開所いたします。各個室というのは、最低基準よりも広いのか、あれが基準なのか、今後のことも考えた上で、その辺を教えていただきたいと思います。","respondent":"日下部障害者福祉課長、早津高齢福祉課長","answer":"国も平成１６年度からは知的障害者の入所施設の新設に対する補助金は出さないということで、そういった意味では、知的障害者の方の入所施設のあり方が大きな転換期を迎えているというふうに私ども認識をしています。その分、目の前にあるリビングが役に立っているという、こういう形に変更になってあります。","voiceIndex":73,"id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先ほどのかがやき園ですけれども、今後の運営の方法として、品川区はどういうふうに考えていくのかという点をお聞かせいただきたい。それと同時に、品川区の中に２０年以上ある社会福祉法人と八潮に品川総合福祉センターもありますので、その辺の考え方はどうなっていくのか、その２点をお願いいたしたいと思います。その辺のところを、もう一遍答えをお願いしたいと思います。","respondent":"日下部障害者福祉課長、早津高齢福祉課長","answer":"ですから、急激な転換というのはなかなか難しいのではないかと、このように考えられますけれども、ただ、かがやき園でのある種の実験的な取り組みということにもなろうかと思いますが、その辺の検証をしっかりとやって。ケアホームを今後建てるとした場合ですが、先ほどご答弁申し上げましたように、居室については６m2小さくなるというようなことも含めまして、ケアホーム西五反田と比べますとコンパクトな施設というのは十分可能です。","voiceIndex":76,"id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今後の方向性とか、どういう動きをされていくのか、その辺。それから、次の質問に入ります。支援費制度の部分なんですけれども、国庫補助金の問題の関係で不足が生じるんじゃないかという報道もされている部分もありますけれども、品川区の中の現状と、これによって今後の運営自体、支援費制度自体そのものが移行することはないんでしょうねという確認です。","respondent":"日下部障害者福祉課長","answer":"今後ですけれども、確かにスタートして１年でこれですから、先行きいろいろ心配なところがありますし、まだまだ不透明な点はありますけれども、ただ少なくとも、これは先日の本会議でも部長のほうから答弁させていただきましたように。","voiceIndex":79,"id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"意見","question":"当然、内容がかわるということだと思いますけれども。それと、今までの評価の中で、どんなクレームがついているのか、サービスを受けている方の問題が多いのか、サービスを提供する方の問題が出ているのか、その辺も含めてお答えをいただければと思います。","respondent":"高橋介護保険担当課長","answer":"私たちサービス向上委員会の中におきまして、いろいろな苦情についてはやはり介護保険制度が始まったというところでの説明とか、それについてのさまざまな仕組み等の話がうまく伝わらなかったような部分が見られますけれども、サービス向上委員会を通じて。","voiceIndex":81,"id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最後におっしゃった、安心してサービスを受けられる状況を、これからもご努力をよろしくお願いしたいと思います。９０％の方は免除になったけれども、１０％の方の思いの中で、賦課分所得の控除ぐらいできないのかなという話もときどき聞いております。最後にもう１点、これもお答えだけで結構です。今後の基金の運用について、十分検討していただきたいということで、その２点を簡単ですが。","respondent":"辻田児童課長、早津高齢福祉課長","answer":"確かに、高額所得者の方からは、そういうようなご意見をいただいております。ただ、私どものほうは粘り強く、この制度の福祉的な性格をご説明しながら納得していただいているという、そういうような状況です。基金につきましては、１号保険料によって積み立てたものです。十分に大事にして運用をしていきたいと、このように考えてあります。","voiceIndex":83,"id":"exchange-038"},{"speaker":"藤原委員","kind":"質問","question":"私は、初めに２１５ページの家庭あんしんセンター、２１７ページのぷりすくーる西五反田、２１３ページの保育園運営費についてお伺いします。家庭あんしんセンターについてお伺いしますが、一昨年の９月にオープンしまして、この施設は母子生活支援施設と子育て支援センター、ファミリーサポートセンター、障害者の施設からなっております。","respondent":"辻田児童課長","answer":"こういうような施設の利用増加に伴いまして、相談事業につきましても、一般的な相談につきまして約３００件を超える相談に対応している。","voiceIndex":88,"id":"exchange-039"},{"speaker":"藤原委員","kind":"意見","question":"これからの課題について２点ぐらい出たと思うんですけれども、その問題点を踏まえて、今後どのような施策を展開していくか、お考えがありましたらお知らせください。","respondent":"辻田児童課長","answer":"最初にお話しした利用促進ですけれども、これは見学会等や視察をさらに受け入れていく。特に、地域の民生委員、児童委員の方々、主任児童委員の方々、児童関係の方々にぜひそういう形で見ていただきたいということで進めてまいります。","voiceIndex":90,"id":"exchange-040"},{"speaker":"藤原委員","kind":"質問・要望","question":"ぷりすくーる西五反田についてお伺いしますが、今回１月２８日、３月３日の説明会において、大変多くの区民の方が説明を聞きに来てくださって、関心が高いことを示されていると思うんです。私が代表質問でもさせていただいたんですが、幼保一元化、一体化という意味において、１番目は二葉すこやか園、２番目はぷりすくーる西五反田と進んできたんですけれども、この次の３番目は考えているでしょうか。","respondent":"金子保育課長","answer":"委員ご指摘の国のモデル事業ですけれども、平成１７年度から全国で５０カ所というふうな報道はされています。まだ詳細な情報を得ておりませんけれども、早期に情報を収集して、対応については慎重に検討してまいりたいと考えております。","voiceIndex":92,"id":"exchange-041"},{"speaker":"藤原委員","kind":"質問","question":"待機児童についてお伺いしますが、２月２４日に第一次の結果が通知されたと思います。両方とも品川区民ということでは変わりないんですけれども、その辺、ずっと住んでいらっしゃる方が入れないというのはちょっと、えっと思う気持ちがあるんですが、その辺の対策について何かありますでしょうか。","respondent":"金子保育課長","answer":"現行の制度の中では以前から住んでいる方、つまり要件として居住何年というものを設定するというのはちょっと難しいところはありますが、今後、国のほうも入所要件については検討しているところでもありますので、この辺の動向も見ながら。","voiceIndex":94,"id":"exchange-042"},{"speaker":"藤原委員","kind":"質問","question":"１点伺います。保育園と私立幼稚園の窓口が一体化になるんですけれども、公立との窓口も一本化になりませんでしょうか。","respondent":"林（宏）委員長","answer":"行財政改革担当課長ですけれども、時間の関係でお答えできる時間がありませんから、後ほど個人的に聞いてください。次に、武内委員。","voiceIndex":96,"id":"exchange-043"},{"speaker":"武内委員","kind":"質問","question":"私のほうは１９３ページの品川区聴覚障害者協会、それと１９９ページの高齢者住宅対策事業の住宅あっせん、それから２０１ページの視覚障害者用触地図、４２１ページの「大江戸温泉物語」利用助成金、４点についてお伺いしたいと思います。初めに、１９３ページですけれども、品川区聴覚障害者協会に対しての助成を行っておりますけれども、内訳をお教えください。","respondent":"日下部障害者福祉課長","answer":"品川区聴覚障害者協会に対して補助を行っておりますけれども、これにつきましては全体の活動経費に対して年額トータルで３０万円を助成させていただいているということで、特段内訳等については、何に幾らというような形で定まっているものではございません。","voiceIndex":98,"id":"exchange-044"},{"speaker":"武内委員","kind":"質問","question":"主に活動費ということで、お伺いしました。こういった団体で耳マークのバッチ等を配布されているようですけれども、品川区において耳マークのバッチをつけて窓口に来られる方というのはいらっしゃいますでしょうか。それに対して対応等、どういうふうにされているかお教えください。","respondent":"日下部障害者福祉課長","answer":"実は、耳マークについては、聴覚障害者の全国的な団体が聴覚障害者であるということがわかるようにということで、確かに耳マークを活用するような仕組みがありますけれども、ただ私ども窓口で対応させていただいている限りにおきましては。","voiceIndex":100,"id":"exchange-045"},{"speaker":"武内委員","kind":"質問","question":"実際に私直接じゃないですけれども、個々の対応にあるのかもしれないですけれども、窓口に行かれてちょっと不自由されたようなこともお聞きしております。今後、そうした耳の不自由な方用に、例えば区役所の窓口でも耳マークを表示して、耳が不自由な方がスムーズにいろんなサービスを受けられるような対応を区として考えられるかどうか、方向性だけお伺いいたします。","respondent":"日下部障害者福祉課長","answer":"ただ、今、ご案内のような耳マークをつけていらっしゃる方、手話ができない方がいらっしゃる場合もあります。今、ご指摘の点も踏まえまして、より一層聴覚障害の方が窓口対応に困らないように配慮していきたいと、このように考えます。","voiceIndex":102,"id":"exchange-046"},{"speaker":"武内委員","kind":"意見","question":"ぜひ、取り組みのほう、よろしくお願いいたします。続きまして、１９９ページの高齢者住宅対策の住宅あっせんについてですけれども、この内容をどのような対応をされていらっしゃるかお教えください。","respondent":"蓼沼高齢事業課長","answer":"住宅あっせんについてのお尋ねですけれども、この予算につきましてはあっせんの成立したときの助成金、それから宅建品川支部に協力をお願いしておりますけれども、そのデータ登録整理等の委託料という中身です。","voiceIndex":104,"id":"exchange-047"},{"speaker":"武内委員","kind":"質問","question":"１４件の方があっせんを受けて入居されたというふうにお聞きしていますけれども、残りの残念ながらだめだった２３件の方の主な事情というか、どういった理由でだめだったのかというのがわかりましたら、主なところで結構ですけれどもお教えください。","respondent":"蓼沼高齢事業課長","answer":"主に希望される内容で物件が見つからないということで、家賃等の問題ですとか、あるいは地域的な問題、住宅の設備の問題等々といった状況で、成立が見ないというようなケースが主なものかと思います。","voiceIndex":108,"id":"exchange-048"},{"speaker":"武内委員","kind":"意見","question":"ところで、確か最近新聞に載りましたけれども、品川区が他区とまた東京都と協力して住宅あっせんを考えているような記事が載ったような気がしたんですけれども、その辺もし、おわかりでしたらお教えください。","respondent":"蓼沼高齢事業課長","answer":"あっせんの促進を図っていくということで、今取り組みを進めているところです。","voiceIndex":110,"id":"exchange-049"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、この予算の金額の中には、その取り組みのものは入っていないということでよろしいんでしょうか。","respondent":"蓼沼高齢事業課長","answer":"この協定に伴います予算面ですけれども、一部につきましては協力店の表示をするということでステッカーの作成を、これは年度内の予算で措置をいたしております。来年度につきましては、もろもろの登録に関するデータ関係の収集整理等の委託ということで、若干予算を組んです。","voiceIndex":112,"id":"exchange-050"},{"speaker":"武内委員","kind":"質問","question":"続きまして、２０１ページの視覚障害者用触地図についてお伺いしたいと思います。プレス発表も見まして、大体の内容は理解したんですけれども、もう一度大まかなところの概要をお教えください。","respondent":"日下部障害者福祉課長","answer":"ですから、触った感触で大体の方向であるとか、位置関係がわかってくるというものを、視覚障害者の団体の皆さん方のご意見等も伺いながらつくって活用していただくと、そういうことです。","voiceIndex":114,"id":"exchange-051"},{"speaker":"武内委員","kind":"意見","question":"プレス発表ですと、約４００人の身体障害者手帳１級から２級の視覚障害者の方を対象に、約１,０００部マップをつくられる予定になっておりますけれども、単純なことで申し訳ないんですが、４００人の対象者で１,０００部なので、その残りの６００部に関してはどのような使われ方をする予定でございましょうか。","respondent":"日下部障害者福祉課長","answer":"例えば、５カ所であれば１カ所につい２００部程度をつくって、それを必要な方から順にご活用いただくということで、いずれにしろ平成１６年度につきましては、一応このぐらいの大きな枠組みの中で、ご意見をいただきながら取りかかってみたいと、このようなことです。","voiceIndex":116,"id":"exchange-052"},{"speaker":"武内委員","kind":"意見","question":"まだ始まっていないのであれですけれども、今後ガイドマップに組み込んだ施設が移転等で変わることも考えられると思うんですけれども、そうした場合に、また新たにつくり直すとかいろいろ問題点が出てくるかなと思うんですけれども、今後そういったものを含めて課題がありましたらお教えください。","respondent":"日下部障害者福祉課長","answer":"実際にどんな形で進めていくのかということで、先へ進めてみないとなかなか具体的な課題等についてもはっきりしてまいりませんので、まずはこちらにありますようにワークショップの開催を基本にして、その中で今後の課題等についてはきちんと検証していきたいと。","voiceIndex":120,"id":"exchange-053"},{"speaker":"武内委員","kind":"意見","question":"非常にいい取り組みだと思いますので、ぜひよろしくお願いいたします。最後になりますけれども、４２１ページの「大江戸温泉物語」の国民健康保険利用者に対して、サービスということで予算が計上されておりますけれども、これもプレス発表で見させていただきましたけれども、また大体の主な目的と概要をご説明をお願いいたします。","respondent":"太田保険年金課長","answer":"国民健康保険ですけれども、今、保険事業ということで、被保険者の方がレクリエーションを楽しみながら健康づくりに役立てていただこうということで、１泊の施設で温泉施設等を中心としたところを利用した場合に。","voiceIndex":122,"id":"exchange-054"},{"speaker":"武内委員","kind":"質問","question":"これも２００万円の予算で、プレス発表ですと国民健康保険加入者１２万人の５％、６,０００人を見込んでいるということで、単純に計算しますと１人当たり３３３円ぐらいの利用なんですけれども、割り引きを見ると大人は９００円とか、ちょっと金額的に合わないような気がするんですけれども、その辺はどのようなお考えがあるのか教えてください。","respondent":"太田保険年金課長","answer":"実際には利用券を全世帯、被保険者の方が利用できる形での交付を考えてありますので、１２万人という被保険者のマーケットを考えてありますので、そうしますと２００万円ですから約１６円ぐらいの単価、その方が全員利用するとは限りませんけれども。","voiceIndex":124,"id":"exchange-055"},{"speaker":"三村委員","kind":"質問・要望","question":"私のほうから２１３ページの保育園運営費、２０９ページの認証保育園について、 ２１５ページのファミリーサポート、生活支援型一時保育について、２１７ページの児童センターについてお聞きしていきたいと思います。そして、認証保育園についても同じく平均的な保育料はどの程度なのか、最高幾らぐらい払っているのか、もしわかれば教えていただきたいと思います。","respondent":"金子保育課長","answer":"認証保育所の保育料ですが、これは東京都の要綱で上限を定めていまして、さまざまな施設がありますが、大体基本的なところは５万円から７万円程度、年齢によっても違いますけれども、そのようなところで分布しているというふうに認識しています。","voiceIndex":128,"id":"exchange-056"},{"speaker":"三村委員","kind":"質問","question":"どうしてこのような質問をしたかといいますと、私たちの生活者ネットワークで子育てにかかるコスト調査というのをやったんですけれども、保育にかかる費用は最低０円、最高２７万円というとても大きな開きがあるということと、対象者の５％の家庭で月８万円以上保育料を払っているという実態があります。そういった現状に対して、品川区としてはどのように認識をされているのかお聞きしたいと思います。","respondent":"金子保育課長","answer":"認可保育所の件に関しましては、私ども何回もご説明申し上げてはおりますが、あくまでも現在の応能負担の体系そのものは崩しておらず、それに対してすべての階層に９％を掛けているという方式にしておりますので。","voiceIndex":130,"id":"exchange-057"},{"speaker":"三村委員","kind":"質問","question":"先ほどの土曜日の高額な利用者負担ということもありまして、ぜひ私立幼稚園の利用者に実施しているような補助制度みたいなものを、高額な負担をされている方たちへの助成制度と考えていただければと、子育て支援として考えていただければと思うんですけれども、お考えをお聞きしたいと思います。","respondent":"金子保育課長","answer":"認可保育所と認証保育所の役割分担ということで、認証保育所については現在のところ新たな補助をしていくということは考えておりませんで、認可保育所の応能負担という部分について、現在のところは維持していこうというふうに考えているところです。","voiceIndex":132,"id":"exchange-058"},{"speaker":"三村委員","kind":"意見","question":"細切れの預かり保育と１日のスケジュールに沿った、具体的に言えば保育園のお昼寝の時間といいますか、休憩の時間がありまして、園児が全員寝ているような時間がありますけれども、そういった時間帯のみの受け入れとか、そういったことが出てくるかと思うんです。そういったところの調整等は、どういうふうにお考えなのかお聞かせ願いたいと思います。","respondent":"金子保育課長","answer":"例えば、０歳児ですと、実際には自由な時間に寝て、自由な時間に起きてという傾向もありますので、その辺の波に乗って保育をしていくというふうになりますし、対極の年長の子どもをお預けになる場合には。","voiceIndex":136,"id":"exchange-059"},{"speaker":"三村委員","kind":"質問","question":"ぜひ、今、保育園に通っている子どもたちへの負担が少ないような形での実施をお願いいたします。子どもの家庭あんしんセンターで行われているファミリーサポートの仕組みについてお伺いいたします。ファミリーサポートの研修について、今まで何人の方が受講されましたでしょうか。現在の提供会員と利用会員の数を教えていただけますでしょうか。","respondent":"辻田児童課長","answer":"ファミリーサポートは、現在まで９回の養成講座を実施しております。その中で、受講生が延べ２９４人ということです。そして、現在の登録者数につきましては、提供会員のほうが１９６人、依頼会員が５０８人ということです。","voiceIndex":138,"id":"exchange-060"},{"speaker":"三村委員","kind":"質問","question":"受講者の中で提供会員になっていない方はどの程度いらっしゃるのでしょうか、またその理由についてどのように分析されているのでしょうか、お答えをお願いいたします。","respondent":"辻田児童課長","answer":"これは養成講座を聞いていく中で、自分ではなかなかできないというようなこともありますでしょうし、それから家庭状況の中で不十分であるというようなこともあると思います。","voiceIndex":140,"id":"exchange-061"},{"speaker":"三村委員","kind":"質問","question":"ファミリーサポート事業は利用エリアが近隣に限られてしまう傾向がありますので、ぜひ地域的な偏りをなくして、病院跡地につきましても高齢者のみの利用ではなくて、一時保育の実施、子育て中の親子が集まれるような、異世代交流の場となるような施設、多様な区民の意見を反映させるような形の施設の検討をお願いしたいと思いますけれども、お考えをお願いいたします。","respondent":"辻田児童課長","answer":"そういう意味では、私どもほうも児童センターの親子サロンであるとか、家庭あんしんセンター等を使って、提供会員の方々の活動を少しずつ実施していただくような形を今後考えてまいりたいと思います。","voiceIndex":142,"id":"exchange-062"},{"speaker":"三村委員","kind":"質問","question":"引き続きまして、児童センターについてお伺いをしていきたいんですけれども、今回事務事業評価におきまして、児童センターの役割はＣ評価がついているんですけれども、子どもたちの放課後の居場所としてきた児童センターの役割を今後どのように考えられていくのか、今後の方向性についてお伺いしていきたいと思います。","respondent":"辻田児童課長","answer":"そういう中で、児童センターの役割、次世代育成支援というものを考えた、すべての家庭の子育てを支援していくためにはどうしたらいいかということで、今後児童センターが大きく変わらなければならないということで。","voiceIndex":144,"id":"exchange-063"},{"speaker":"三村委員","kind":"意見","question":"全体としては、減らしていくということではないということで安心するんですけれども、今までの児童センターとしては小学生対象の事業がとても多かったかと思います。小学生対象の事業について、今後どのようにされていくのか、お考えのほうをお願いいたします。","respondent":"辻田児童課長","answer":"そういうような意味で、すまいるスクールと連携した形で、それを支えるような形、例えばそこになじまないような子どもがあれば、個別、具体的な形での対応、そういうようなことも考えていかなければならないかなという具合に考えています。","voiceIndex":146,"id":"exchange-064"},{"speaker":"三村委員","kind":"意見","question":"内容についてもお答えいただければと思ったんですけれども、ちょっと時間がないので、先ほどから出ています児童センターのあり方検討委員会の中の一文なんですけれども、中高生になってから突然来館し活発に活動することは考えがたいことから、小学校から児童センターに足を……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":150,"id":"exchange-065"},{"speaker":"菊地委員","kind":"質問・要望","question":"路上生活者の問題ですけれども、午前中の審議の中で、この調査の目的が路上生活者の動向をつかんで、それを自立支援につなげていくと。それから、緊急一時保護センターには、大田寮ができたのが平成１３年頃でしょうか、何人ぐらいの方が実際に品川区内にいた路上生活者の皆さんが入所されているのか、平成１３年、１４年、１５年は途中ですけれども、この辺がわかりましたら教えていただければと思います。","respondent":"黒田生活福祉課長","answer":"本当に自立のために何をしたいかという、ご本人の意向に沿いながら、こちらができることにこたえていくというのが今の路上生活者の対応です。大田寮ですが、平成１５年度は２２名の利用がございました。","voiceIndex":152,"id":"exchange-066"},{"speaker":"菊地委員","kind":"質問","question":"大田寮の入所者が２２名だということで、以前の実態から比べると、随分大きくこの問題というのは前進しているんだなというふうに思います。ですから、失職をしてアパート代が払えなくなる、こういうところになるまで皆さん一生懸命仕事を探されるんでしょうけれども、こういう皆さんが実際に品川の窓口に来たときに、どんな対応をされるのかというのを具体的な事例でお聞きしたいんですけれども。","respondent":"黒田生活福祉課長","answer":"ＩＴ関連で、どうしても家賃滞納をして出ざるを得ないとなると、やはり路上生活という対応ではないとは思います。ただ、出されてしまった場合は、まずは路上生活者の自立支援システムに乗っていただく。","voiceIndex":154,"id":"exchange-067"},{"speaker":"菊地委員","kind":"質問","question":"もちろん課長のおっしゃるとおり、どう自立していくか、当然のことだと思います。今、お話ししたのは路上生活になる前の話ですから、路上生活者を出さない、食いとめていく、こういう視点に立つことが、まず必要なんじゃないかというふうに思うんです。今の課長のご答弁等で考えると、どうして品川区の見解と他の地方自治体の実際が違うのか、これがよくわからないんですけれども、この辺をお答えをください。","respondent":"黒田生活福祉課長","answer":"他の自治体と違うかどうかというのは、私もよくわかりませんが、やはり生活保護というのは基本がありますので、その基本にのっとってこちらは対応しています。","voiceIndex":156,"id":"exchange-068"},{"speaker":"菊地委員","kind":"質問","question":"ですから、そういう人たちをどのように助けていくのかというのは、実際に路上生活者になる前にどうするか、そこをしっかり視点に地方自治体が据えない限りは、行政が据えない限りは、実際に自立支援センターに送ればいいんだという視点では、絶対にこれはなくならない問題であるというふうに思います。品川区ではこういうことも行わないんでしょうかね、この辺もちょっとお聞かせください。","respondent":"黒田生活福祉課長","answer":"働けないんだったら、働けないという証明を出していただくしかないです。離職者支援の貸し付けですが、これは社会福祉協議会でやってありますので、当然相談窓口ではご紹介しています。","voiceIndex":158,"id":"exchange-069"},{"speaker":"菊地委員","kind":"質問・要望","question":"これは餓死と凍死が死亡原因ということですけれども、少なくとも品川区として区民を路上生活者にはしない、こういう姿勢がまず何よりも求められるものだと思います。それがなければ、いくら調査を進めたって、同じ状況が続いていくんだということです。不況で本当に苦しいとき、若者でさえ仕事がない時代ですので、ぜひとも必要な支援を思い切って広げていただきたいなというふうにお願いをして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-070"},{"speaker":"須藤委員","kind":"質問・要望","question":"同じ委員会になっちゃうのか、介護は介護、障害者は障害者というような形で、別個に構築されるというような思いがあるんですけれども、その辺のところと、それから二つつくって、障害者のほうが７６３万円ですか、障害者のほうの構築するというのがかなり数字的には上がって、両方書いてあるのに数字的にちょっと少ないのと。それから、２１１ページの児童手当給付金の仕組みを簡単に教えてください。","respondent":"高橋介護保険担当課長、日下部障害者福祉課長、辻田児童課長、金子保育課長、山岡保健高齢事業部副参事、早津高齢福祉課長","answer":"もう１点につきまして、午前中にもご質問がありましたけれども、本格的実施ですが、その部分につきましては。そういった意味では、今後は特に自立と社会参加の促進、この辺が一番重要なところだというふうに考えております。ご案内のとおり、法制度としては認可保育園、幼児教育施設と二つの施設になってありますが、私どもとしましては。２年前は４１人、その前は４７人、今年も４１人を予定していますので、３０人が続くという事態ではございません。それがまず１点。","voiceIndex":162,"id":"exchange-071"},{"speaker":"須藤委員","kind":"提案","question":"長期基本計画でこうなっているよというのはわかるけれども、説明してくるときに、今、事業部制を敷いていろいろやってきて提案してくる。それから、２００１年の心身障害者の国際生活機能、いわゆる新しい障害を分類して、２００１年にＷＨＯが国際生活機能分類というのをされていますけれども、そのあたりをご存じだったら教えてください。","respondent":"日下部障害者福祉課長、田中健康課長","answer":"私、ちょっと手元に詳しい中身をわかるようなものは持っておりませんけれども、確かにＷＨＯで障害についての具体的な定義が規定されておりまして、それがベースになって障害者の施策について。私どものほうで、今そういう意味でのいわゆるケースカンファレンスを通じまして、より充実できるように努めているところです。","voiceIndex":171,"id":"exchange-072"},{"speaker":"本間委員","kind":"質問","question":"これについてお伺いします。それから最後に１９５ページは高齢者生きがいづくり事業、いきいきカラオケ広場等についてお尋ねしたいと思います。そして、品川介護福祉専門学校は、最近は人数が少ない形での卒業生になっているようですけれども、平成７年以降今日までの卒業生の総数をお尋ねします。","respondent":"早津高齢福祉課長、山岡保健高齢事業部副参事","answer":"この奨学金については、基本は返還していただくわけですが、人材確保というような観点から、区内の社会福祉法人等に就職した場合については、３年間の勤務の実績があった段階で返還免除というような運用をしています。先ほどから申しますように、１期からざっと言いますと、４０人、４０人、４３人、４０人、４７人、４１人、昨年が３０人と、これは退学の方あるいは休学の方が出た関係で少なくなっております。今年は４１人の予定をしています。","voiceIndex":175,"id":"exchange-073"},{"speaker":"本間委員","kind":"質問","question":"大変、画期的な学校ができて、レベルの高い介護養成人が着々と増えてきているわけですけれども、区内に就職を３年間見届けたら免除になるというふうなことです。その件で、そのことに満たない形の返還をされていないような人がいるのかどうかというのと、それから３年以降の品川区における定着の度合い。ざっとでいいです。","respondent":"早津高齢福祉課長、山岡保健高齢事業部副参事","answer":"３年に至らずに退職するなり別のところに就職した人間も中には散見されます。散見程度ということで、そういう人もいるです。３年で免除になったからやめるというのは、私どものほうにはほとんど耳に届いておりません。ただ、ほかの理由で、いろんな家庭の事情等でやめるというケースはあるかもしれませんけれども、３年経ってからということはほとんど聞いていません。","voiceIndex":178,"id":"exchange-074"},{"speaker":"本間委員","kind":"質問・要望","question":"どうか、引き続きマンパワーの拡大と質的向上のために頑張っていただきたいというふうに思います。シルバー人材センター支援事業の件ですが、合わせまして新就業システム推進事業の２点についてお尋ねします。新就業システムにつきましては、５５歳以上から６４歳までという中身ですけれども、着実に成果が上がっているという説明がございましたが、その着実に成果が上がっている中身についてお伝えください。","respondent":"蓼沼高齢事業課長","answer":"これにつきましては平成１４年４月から一部開設をいたしまして、９月に完全オープンしたということで、従来の生きがいとしての就業にプラスいたしまして、現役とは異なる多様な高齢期の働き方を実現するということで実施してまいりました。","voiceIndex":183,"id":"exchange-075"},{"speaker":"本間委員","kind":"意見","question":"時間がありませんので、次に移りたいと思います。最後に、高齢者生きがいづくり事業の中で、いきいきカラオケ広場等とありますが、この中に麻雀広場等も含むのではないかと思いますが、たばこを吸わない、お酒を飲まない、お金をかけない等々の三原則でやっておりますが、この件について時間がありませんのでメリットだけ一言。","respondent":"蓼沼高齢事業課長","answer":"ご指摘のとおりです。健康増進、生きがいづくり、仲間づくりということで、今、事業を進めているところです。","voiceIndex":187,"id":"exchange-076"},{"speaker":"若林委員","kind":"意見","question":"２０１ページの社会参加への支援等々、１９１ページの痴呆性高齢者グループホーム整備費助成事業、２０５ページの知的障害者入所更正施設、さらに２１５ページの家庭あんしんセンター運営費、２１７ページの児童センター運営費、できれば２０９ページの乳幼児・小学生医療費助成事業までいきたいと思います。中身をお示しください。","respondent":"日下部障害者福祉課長","answer":"一つは消防庁のほうと直結した自動通報システム、それからもう一つは民間の事業者に委託した形での通報システムということで、いずれかの選択という形で事業を実施しています。","voiceIndex":190,"id":"exchange-077"},{"speaker":"若林委員","kind":"質問","question":"それぞれ単価とか出しにくいと思います。単価という言い方があたっているのかどうかわかりませんが、１人当たりどのぐらいお金がかかるのか、今あえて聞きませんけれども。これが１通何円という非常に安価なツールでございまして、携帯電話の助成の考え方とかあればお答え願えますでしょうか。","respondent":"日下部障害者福祉課長","answer":"私どもはそれを基本にして、聴覚障害者の方にも災害時の安全性を高めていただくということで、区のほうとしてもいろいろなご案内をしています。それが基本でございまして、現在のところ具体的な助成等の措置については考えてございません。","voiceIndex":192,"id":"exchange-078"},{"speaker":"若林委員","kind":"質問","question":"外がどんなにうるさくても音が拾えるということですので、この辺もまた参考にしていただいて、さらに聴覚障害を持った方へのご配慮をお願いしたいと思います。続きまして、痴呆性高齢者グループホーム、合わせて知的障害者入所更正施設、この２点を並行してご質問します。どのような厚生労働省に対して納得をしていただいたのか、どういう言い方をして厚生労働省を「うん」と言わせたのか、この辺の考え方を。","respondent":"早津高齢福祉課長、日下部障害者福祉課長","answer":"こういった痴呆の特性に着目した施設というものがグループホームでありまして、痴呆性高齢者の増加を背景に、また全体としてグループホームが区内には乏しいという中で。それが平成１３年から１５年に至る中で、今年度竣工するわけです。国のほうとしましては、新たな施設建設についての補助を打ち切ることを打ち出したのはごく最近でございまして、平成１６年度からは廃止をすると。","voiceIndex":194,"id":"exchange-079"},{"speaker":"若林委員","kind":"意見","question":"グループホームのこと、よくわかりました。それから、かがやき園のほう、午前中も話がありました。そうしますと、今回かがやぎ園に３０人入所されるわけですけれども、地域にまた帰っていただくには、例えば１０年なのか、２０年なのか、いやそれでは長い、最低１年ぐらいで、その障害の重さによっても違うと思いますが、この辺の組み立て方をお教え願います。","respondent":"早津高齢福祉課長、日下部障害者福祉課長","answer":"私の先ほどの説明が二つの施設の違いをはっきりとさせるために、あえて強調的に行いました関係で、そのようになったのかと思いますが、痴呆と身体といっても、やはり重複している方が大変多うありますし、また痴呆の介護についても。そういうことで、在宅生活全体についての総合的なマネージメントといいますか、そういうものが必要ですので、今、私どもの障害者福祉課と受託先の福栄会でいろいろ検討チームをつくって検討しています。","voiceIndex":197,"id":"exchange-080"},{"speaker":"若林委員","kind":"質問・要望","question":"私も見に行って、本当につくった人の思いが込められるといいますか、トイレ一つにしても、その人が大工さんというんでしょうか、独自に創造して、これを痴呆の高齢者の方に使っていただきたいという、トイレ一つにしてもすごく思いのこもるものをつくっておられました。ぜひとも、そういう一つ一つ心のこもった、グループホーム建設に向けて、民間と力を合わせてぜひつくっていただきたい。","respondent":"早津高齢福祉課長","answer":"介護報酬の１割負担も含めて、大体そのぐらいの費用ではないかというふうに言われているところです。","voiceIndex":200,"id":"exchange-081"},{"speaker":"若林委員","kind":"質問・要望","question":"わかりました。十七、八万円というお答え、大井六丁目は確か１５万円台とか言っていましたけれども。そこを何とかもう少し低くという、これからそういうご要望も多々来ると思いますので、また最大限のご努力をお願いしたいなと思います。続きまして、家庭あんしんセンター、児童センター絡みで、今平塚二丁目に家庭あんしんセンターが一昨年の９月からスタートいたしました。","respondent":"辻田児童課長","answer":"この中では、言語、理学、作業療法等を実施しているということで、きちっと引き継いで実施してきているという状況です。","voiceIndex":202,"id":"exchange-082"},{"speaker":"若林委員","kind":"質問","question":"療育相談のほうはわかりました。保護者の方から聞きますと、大井倉田の子育て相談センターのほうでは療育相談ではなくて、療育そのものを毎週やっていたという経過があったと思います。今回、家庭あんしんセンターの中には、大井倉田の子育て相談センターの機能を移すというお話の中で、なかなかそういうサービスが受けられないんだという、そういう保護者の方の声がありました。この辺はいかがでしょうか。","respondent":"辻田児童課長","answer":"決して前のところで受けられた方が、こちらのほうに来て相談回数が減ったとかというようなことは、私どものほうは聞いていないんですけれども、きちっとその辺はやられているという具合に把握しております。","voiceIndex":204,"id":"exchange-083"},{"speaker":"若林委員","kind":"意見","question":"具体的に大井倉田の子育て相談センターのときはどのような頻度でやっていのか、現在の家庭あんしんセンターではどういう頻度でやっておられるのかお教え願います。","respondent":"辻田児童課長","answer":"平成１３年度の実績等がここにありませんので、平成１４年度でいきますと、合わせて子育て支援センターが９月から始めております。それまでは大井倉田の子育て相談センターのほうでやっておりますけれども、約１,７００件ぐらいの数がございました。","voiceIndex":206,"id":"exchange-084"},{"speaker":"若林委員","kind":"確認","question":"今の１,２９１件は相談ですよね。療育そのものではないと思います。それを一つご確認を願います。大井倉田の子育て相談センターが廃止をされて平塚に移った。平塚に移ったら、サービスがなくなったとは言いませんけれども、非常に受けにくくなった。この辺、もう１回ご説明を願いますでしょうか。","respondent":"辻田児童課長","answer":"ただ、大井倉田から平塚に移ったということで、場所的な変更があって、いろんな形で今まで近かった方が遠くなったとかというようなことはありますので、その辺につきましては、その数に多少反映されているのではないかなという具合に考えております。","voiceIndex":208,"id":"exchange-085"},{"speaker":"西本委員","kind":"質問・要望","question":"私のほうからは大きくは３項目、２１７ページの児童センター運営費、それから２０９ページの認証保育所関係、それから３点目には２１３ページから２１５ページにかけました保育園運営費について質問をします。特に、区の持ち物の場合もありますし、借りているというところがありますので、その辺の大きな方向性としては、どういう形になるのか教えていただきたいと思います。","respondent":"辻田児童課長","answer":"ただ、これは条例上、きちっと手続をしませんと、次の手立て等もなかなか進めませんので、まだこの中に残っていらっしゃる方がいらっしゃいますので、個別の形で対応する中で、スムーズに他の学童保育クラブ、児童センター等に移っていただく中で。","voiceIndex":211,"id":"exchange-086"},{"speaker":"西本委員","kind":"質問・要望","question":"先ほどもちょっといろいろ答弁がありましたけれども、もっと広い意味で、児童センターがこれからどういう方向で、位置づけとして発展していくのだろうかというところをお答えいただきたいと思います。","respondent":"辻田児童課長","answer":"児童センターの新たな方向性ですけれども、これは平成１４年１０月から児童センターのあり方検討委員会で検討してまいりました。","voiceIndex":213,"id":"exchange-087"},{"speaker":"西本委員","kind":"質問・要望","question":"今後、児童センターをいろいろ拡大していくと思うんですが、具体的なものがなかなか見えずらい部分があって、例えば今までも子育てサロンとかいろいろやっていますので、そこはこの１年間、２年間、移行期に関して、具体的に児童センターが地域の中で重要なポストにあるんだということをぜひ見せていただきたいなというふうに考えておりますが、その辺はいかがでしょうか。","respondent":"辻田児童課長","answer":"児童センターがすべてまとめるということではなく、まとめていく方向で何とかならないかなです。そのためには、今ある１３ブロックの地域センターや何かとの連携を今後強くしていくというようなことも含めて、具体的な取り組みを今検討しています。","voiceIndex":215,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問","question":"ぜひ、具体的な行動、提起をお願いしたいと思います。次に、認証保育所なんですが、無認可保育所が認証保育所になるということで、補助金の出し方が過去と違っている部分があると思います。その違いによって、実際に運営する側の影響、もしくはメリットはいかがなものか、その辺を教えてください。","respondent":"金子保育課長","answer":"つまり、認可外の保育施設が４月から定員どおり埋まっているかというと、必ずしもそういうわけではないので、充足率も従来の数から算出していきますと、若干認証保育所に移行したほうが数字的には有利であるというふうな、私どもの試算結果でございました。","voiceIndex":217,"id":"exchange-089"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、認証保育所はある程度高額になっていますので、そこと合わせるために上げるんじゃないかという考え方もありまして、多分今年の保育料の値上げは、品川区で行われているのと全く別だと思いますし、東京都の考え方と区の考え方は全然違うところがあると思うんですけれども、認可に入れなかった人に対する助成というのは、何か考えることはありませんでしょうか。","respondent":"金子保育課長","answer":"そういう意味では、私ども聞いている範囲では、必ずしも認可保育園に申し込まなくて、認証保育所でやっている保育のメニュー、例えば私どもよく聞くんですけれども、１歳児の頃から英語をやるとか、そういったそれぞれの認証保育所の特色あるメニューをご希望されて。","voiceIndex":219,"id":"exchange-090"},{"speaker":"西本委員","kind":"意見","question":"考え方がわかりました。認可保育園に入りたいという形への希望を、なるべく取っていただけるような施策の展開をお願いしたいところです。最後に保育園運営費についてなんですが、いろいろ見ますと保険の業務委託とか、育児休業などの人材派遣職員の活用であるとかということが挙げられているんですが、これはどういう考えのもとで、実態はどういうふうになっているのかお答え願いたいと思います。","respondent":"金子保育課長","answer":"２点のお尋ねですけれども、まず育児休業等人材派遣職員に関しましては、私どもの平成９年だったと思いますが、保育園の保育士の定数を削減しております。そこの段階で、過員がある程度発生しておりまして、それ以降産休・育休等々については、過員を充ててきた経過があります。","voiceIndex":221,"id":"exchange-091"},{"speaker":"西本委員","kind":"意見","question":"影響のないように、民間活力をともに考えて保育園運営をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":223,"id":"exchange-092"},{"speaker":"石田委員","kind":"質問・要望","question":"延長夜間保育のほうからいかせていただきたいと思いますが、特にこれは限ってやりたいんですが、８時半から１０時の部分が平成１６年度９園ということになると考えていますが、今後これを拡大していくのか、それと今後の考え方を教えていただきたい。施設的に、現実的には今やっているところは何人ぐらいまでは受け入れられるとお考えになっていらっしゃるか、その辺のところを教えていただきたいと思います。","respondent":"金子保育課長","answer":"延長夜間保育のお尋ねです。委員ご指摘のとおり、平成１６年度は９園目の１０時までの園を開設する予定にしております。そもそも１０時までの園に関しましては、平成１１年に３園でスタートして、平成１４年に３園を拡大した経過があります。","voiceIndex":226,"id":"exchange-093"},{"speaker":"石田委員","kind":"質問・要望","question":"先に進んだ話までいただいたような気がしますが、そうなってくると現実問題、今何人ぐらい８時半から１０時を使っているかというところの平均値を教えていただきたいのと、一つの園でどれぐらいまで受け入れられる体制があるのか教えていただきたい。","respondent":"金子保育課長","answer":"これはあくまでも平日のデータです。私どもは、ともすれば他区に見られるとおり、延長夜間の定員をあえて設定しないで、必要な方の区民のニーズにはこたえるという形で実施しているものですので、人数に応じて職員を配置していくというふうに考えているところです。","voiceIndex":228,"id":"exchange-094"},{"speaker":"石田委員","kind":"質問","question":"ただ、今お伺いすると４.１人の平均だということであれば、よく品川区の中で、今多分この中でどこかの保育園には必ず自転車で１０分行けばどこかしら行くぐらいの距離感があると思います。７時半でも構いません。８人ぐらいのところだったら、それでまとめてどうしてもニーズのある方はそこへ行ってくださいと、そういう政策的な判断があってもいいと思うんですが、その考え方についてお聞かせください。","respondent":"金子保育課長","answer":"委員のご指摘、ごもっともなところがあるとは思いますが、そういった私どものスタートの精神も含めて考えて、今後検討する余地があれば検討していきたいというふうには考えております。","voiceIndex":230,"id":"exchange-095"},{"speaker":"石田委員","kind":"質問・要望","question":"その方たちのニーズをしっかりとらえれば、この方はどうしても１０時だとかわかるわけですよね。そうすると、８人なら、その人は朝からずっとそこの保育園にいてくれていいんです。その方たちに、認証保育のほうがこういうこともあっていいですよと断れば、待機者の人がもっと多く保育園に入っていけるということもあるわけで、その辺の点はもう一度ご答弁をいただきたい。","respondent":"金子保育課長","answer":"あらゆる点から考えて、現在は確かに１０時園を９園まで拡大してきたという経過がありますが、今後はこういったメニューを再編成していく。","voiceIndex":232,"id":"exchange-096"},{"speaker":"石田委員","kind":"意見","question":"年間トータルを考えると、年間で８,０２２万円かかるんだろうと考えています。そういう形の中で４人です。病気のときぐらいは子どもを親が見たほうがいいと考えていますが、どうしてもそういう事情があるということであれば、そこでこういう制度があっても構わないと考えていますが、先ほどの保育園で全体で９.４％の負担というのがありましたが、受益者の考えで１日２,０００円だということであります。","respondent":"金子保育課長","answer":"ただ、病後時の場合は特に在園児について費用を取っていないんですね。この辺は今後検討する余地があるのかなというふうには、私は考えておりますが、全体的な費用としての二千何がしという費用ですね。","voiceIndex":234,"id":"exchange-097"},{"speaker":"川西委員","kind":"質問・要望","question":"痴呆性高齢者のケア事業ですが、先ほどもずっと何回もお答えにあるように、一つはグループホーム、一つは在宅の中では、デイサービスに通っていろいろケアをしているというようなことなんですけれども、ここで一つ取り上げていただきたいのは、５０代からもっと前の方もたまにいらっしゃいますけれども、アルツハイマー系の病気の人に対して、かなり在宅で家族も含めて頑張っているけれども。","respondent":"早津高齢福祉課長","answer":"区内のデイサービスセンターの中では、痴呆性の専門ということで小山の家、月見橋の家がありますが、なお痴呆のケアの手法については来年度本格的に検討して、現在もまだ緒についたばかりというような傾向がありますので。","voiceIndex":237,"id":"exchange-098"},{"speaker":"川西委員","kind":"質問","question":"かつてありました福祉委員長会というところで、地方に視察に参りました。１５万円ぐらいから１８万円ぐらいの年金で暮らせるのはグループホームの費用に全部払っちゃうわけにはいかないわけで、そういう場合にやはり東品川、八潮にあるようなわかくさ荘みたいなものも、やはり全然考えないというわけにはいかないと思いますが、平成１６年度予算の中で方向の検討ぐらいはされていくんでしょうか、伺います。","respondent":"蓼沼高齢事業課長","answer":"高齢者住宅についてのお尋ねですけれども、これまで計画的に高齢者住宅を整備してまいりまして、２２０戸のストックを抱えてございまして、区としては一定程度の水準にあるというふうに考えてあります。","voiceIndex":239,"id":"exchange-099"},{"speaker":"川西委員","kind":"質問・要望","question":"ぜひ、都南病院のところに併設して、高齢者シルバー住宅を考えていただきたいというふうにお願いをいたします。年金で暮らしている方は、何％ぐらいの人がそういうものを求めているかというのを、ぜひ調査をしていただきたいというふうに思います。次に、非常勤徴収員のことですけれども、この徴収員の方々を予算化しまして、どのぐらいの収納率を見込んでいらっしゃるのか伺います。","respondent":"太田保険年金課長","answer":"介護保険の部分ですけれども、予算に見合った上限ということでは、滞納繰越分で換算いたしますと約２名で７％ということで換算をしています。","voiceIndex":241,"id":"exchange-100"},{"speaker":"川西委員","kind":"質問・要望","question":"ぜひ、介護保険の理解を求めて、徴収に努力していただきたいと、これはお願いで結構です。次に、先ほども出ました件ですが、人材派遣と産休代替職員雇上が出ておりますが、振り分けはどういうふうにしていらっしゃるのか。産休等の代替職員の単価より人材派遣は少々高めだというふうに認識しておりますが、それでも人材派遣がよいのかどうか、この辺について伺います。","respondent":"金子保育課長","answer":"当然のことながら保育士の資格と経験が２年以上ということで問うておりますので、その辺が違ってくるがために単価も違ってくるというふうなことでご理解いただきたいと思います。","voiceIndex":243,"id":"exchange-101"},{"speaker":"川西委員","kind":"質問・要望","question":"そのノウハウで保育園の運営が円滑に行くことは反対はいたしませんが、その辺の原価計算もしながら、あるいはアルバイトとしての要望が区民の保育士有資格者の中にないのかどうかの分析もしながら、こういう制度の活用をお願いしたいと思います。それから、次に移ります。この休館日の開設を考えていただけるかどうか、この辺について伺います。","respondent":"辻田児童課長","answer":"児童センターあり方検討委員会の中でも、その点につきましては検討しておりまして、今後考えてまいりたいというふうに考えております。","voiceIndex":245,"id":"exchange-102"},{"speaker":"沢田委員","kind":"質問・要望","question":"２１３ページの保育園運営費に関連して、子育て支援の問題と保育料値上げ問題を中心に聞かせていただきたいと思います。初めに、区長は施政方針の中で、予算編成の三つの柱のトップに、次代を担う子どもと子育て世代を強力に支援するというのを掲げました。予算のトップにこれを据えた理由は何なんでしょうか、説明願いたいと思います。","respondent":"榎本行財政改革担当課長","answer":"子育て支援をトップに据えたですけれども、去年の次世代育成支援対策推進法ができた段階で、国を挙げての子育て支援をどういうふうに進めていくかということを早急にやらないと、この深刻なる少子化には太刀打ちできないという状況にあります。","voiceIndex":248,"id":"exchange-103"},{"speaker":"沢田委員","kind":"質問","question":"もう一つだけ聞きたいんですが、これは我が党も評価をし、本当にありがたいことだと思うんですけれども、小学生の医療費無料制ですね、全国に先駆けて品川区はやりました。立派なことだというふうに思います。これは何が目的でやったんでしょうか。","respondent":"辻田児童課長","answer":"これはやはり品川区の中で子育ての楽しさを実感していただける、そういう意味で経済的支援というような、サービスの中でこれを実感していただくということで、私どものほうは６年生という部分まで引き延ばして区の独自性を出したものです。","voiceIndex":250,"id":"exchange-104"},{"speaker":"沢田委員","kind":"質問","question":"そうしますと、先ほど受益者負担ということがしきりと言われました。保育料の値上げについては受益者負担が出てくるけれども、医療費無料化のところになると、子育ての楽しさが実感できるものに。ここの場では、受益者負担の原則はどうなっているんでしょうか。","respondent":"辻田児童課長","answer":"その中の一貫として、やはり高額所得者についてはそれなりの負担をしていただく。少なくとも福祉を今後継続していくためには、常に適正な負担ということをきちっと踏まえてやらなければ、今後長く継続できないという具合に考えております。","voiceIndex":252,"id":"exchange-105"},{"speaker":"沢田委員","kind":"質問","question":"全然、答えになっていないですよね。確かに所得制限はあっても、９割の子どもと家族に対しては医療費無料制になると。この問題はどうなんのかというのに対して、答えになっていない。ですから、私は受益者負担というなら、受益を受けるのはその家族、親と子どもだけじゃなくて、社会全体が受益を受けるんだという、この立場がなければ、先ほどの医療費の無料制という根拠が出てこない。","respondent":"金子保育課長","answer":"保育料を決めるにあたっての国あるいは都道府県、区との関係ですけれども、保育料あるいは国負担、都負担については、制度がただいま変更の過程にあるというのは委員も承知していらっしゃるとは思いますが、保育料に関しましては児童福祉法で直接的な規定がありまして。","voiceIndex":254,"id":"exchange-106"},{"speaker":"沢田委員","kind":"意見","question":"厚生委員会で配付された資料で言いますと、平成１４年度は保育運営経費全体で８７億１,３００万円、そして保育料として取るべき２０％は１７億４,０００万円、そして国と都が負担をするのは国が８億５,９００万円と都が４億２,９００万円、区が同じく４億２,９００万円、国の決めた最低基準の中で半分は保育料として取りなさい。その辺の考え方をお尋ねしたいと思います。","respondent":"金子保育課長","answer":"今、お尋ねの国の保育の運営経費の算定の仕方、これは厳然としてあるわけでありまして、品川区として独自に判断して、委員ご指摘のとおり５２億５,６００万円余というのを運営費として支出しているものです。","voiceIndex":256,"id":"exchange-107"},{"speaker":"沢田委員","kind":"意見","question":"ところが、今は国の基準の２０％を保育料として徴収する。これの９.６％しか取っていない。保育者ばかりに向いて、国には全然ない。ところが、国はどうかといいますと、１９８４年までは全体にかかった運営費、措置費の８０％は国が負担していたんです。今、５０％です。その次になって、１９８５年になって７０％になり、１９８６年になって５０％になる。","respondent":"金子保育課長","answer":"それは、私どもの特別区長会のほうで実施しているものです。","voiceIndex":258,"id":"exchange-108"},{"speaker":"沢田委員","kind":"質問","question":"当時、超過負担の問題を議会挙げて、この問題を論議したときから比べると、恐ろしく後退をしていると私は言わざるを得ません。５６条の２項は、それらしいことは書いてあるんだけれども、５６条の第３項、家計の影響を考慮すべきことが書いてあるんだけれども、その辺をもう少し説明してもらえないでしょうか。","respondent":"金子保育課長","answer":"委員ご指摘のとおり、児童福祉法の第５６条３項は、先ほどちょっとはしょって読みましたけれども、もう少し読みますと「保育費用を支弁した市町村の長は、本人またはその扶養義務者から当該保育費用を。","voiceIndex":260,"id":"exchange-109"},{"speaker":"沢田委員","kind":"質問","question":"マンションだとかは大体子育てを１人、２人やれば、２ＤＫ、３ＤＫ借りれば１３万円、１５万円というお金がかかっちゃう。その辺のところをどれだけ考慮されたのかということと、これはたびたび代表質問でも私言いましたけれども、少子化に対する区民調査の中で実施してほしい施策、子育てしながら、それはどれぐらいになっていますか。","respondent":"金子保育課長","answer":"少子化に関する区民調査についてのお尋ねです。子どもを産み育てる上での悩みや問題の中では、第１子選択の問題ではないですが、家庭の経済あるいは子どもの教育費、住居の問題等々のところが、非常に大きな悩みや問題として出されているところだというふうに考えます。","voiceIndex":262,"id":"exchange-110"},{"speaker":"沢田委員","kind":"質問","question":"読売新聞が去年５月２５日に行った子育てに関する世論調査の設問です。そこに今度は保育料をこんなに上げようとするんですから、私は全体の流れ、家計の調査をするといったけれども何を調査したのか、大変これは首を傾げるところです。これはやるんだなと思って、本会議の代表質問で言ったら、何ら否定的な話はなかった。","respondent":"金子保育課長","answer":"これも厚生委員会でも何度も申し上げたとおりですが、私ども今回の保育料の改定に関しては、国の徴収金基準額の４７％から６０％に上げるのは政策目標だというふうに掲げておりますが、私ども平成１６年第１回定例会にご提案申し上げているのは。","voiceIndex":264,"id":"exchange-111"},{"speaker":"沢田委員","kind":"質問","question":"時間がないので、私の質問に答えてほしいんですよ。政策目標だということは、意思決定していないということですか。","respondent":"小沼福祉事業部長","answer":"極端なことを言いますと、１万円払って８万５,０００円のものが出てくると、こういうこともご賢察の上、私どものことをご理解いただければと思います。","voiceIndex":266,"id":"exchange-112"},{"speaker":"沢田委員","kind":"意見","question":"私は本会議でも言ったんですけれども、共働きの女性が働けば所得税や住民税や社会保障の負担をするということが、Ｄ１０階層で６０万円、それも含めて約７０万円近い年間の負担になりますし、奥さんが、女性が会社で働けば、働いたことが法人税となって、それがまた全体に還元される。働くことは、非常に大きな意味を持っているということを言いたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":268,"id":"exchange-113"},{"speaker":"木下委員","kind":"質問","question":"私のほうは１９１ページの民生費、社会福祉費の民生委員経費の部分と、４８０ページの保険給付費の部分について、お聞きしたいこととお願いがあります。第１に、民生委員経費のことについてお聞きしたいと思うんです。そこで、民生委員の現状についてお聞きしたいと思うんですけれども、大体平均年齢はおいくつなんでしょうか。年齢制限といいますか、おいくつまでなっていらっしゃるのか。","respondent":"日下部障害者福祉課長","answer":"例えば、新任の民生委員ですと、具体的な条件としましては６５歳未満、ただ再任ということになりますと７３歳未満ということで、若干緩やかになってまいります。それから、児童福祉の専門で担当いたします主任児童委員につきましては、新任、再任ともに５５歳未満という状況です。","voiceIndex":270,"id":"exchange-114"},{"speaker":"木下委員","kind":"質問","question":"かなり高齢の方がやっていらっしゃるということで、それに加えて民生委員といいますと高齢者相談員ですとか、児童委員ですとか、民生委員の仕事プラスほかの仕事も横並びでやっていかなきゃならない。高齢者相談員ですけれども、これは高齢者の方を大体何人ぐらいを担当されていらっしゃるんでしょうか。","respondent":"早津高齢福祉課長","answer":"対象としては、主にひとり暮らしの高齢者並びに高齢者世帯が該当ということになります。世帯数で申しますと、９,６００世帯ぐらいというのが対象件数になろうかと思います。","voiceIndex":272,"id":"exchange-115"},{"speaker":"木下委員","kind":"質問・要望","question":"これは実質決まった数字なんでしょうか、まだ決まっていないんでしたら、もっと定員の増員を求めるべきではないのか。ですからこそ「やめたい」という民生委員の声が私ども議員のところに届いてくるというのが現状ですので、先ほどお聞きしたような、これは今年の１２月１日に改定される定員の数というのは、もう決まっちゃったことで変えられないのか。","respondent":"日下部障害者福祉課長","answer":"例えば、「これからも積極的に取り組んでいきたい」という回答をいただいた方が約半数、それから「職務が重く負担であるが、やりがいはある」という方が約３割いらっしゃったということで。","voiceIndex":276,"id":"exchange-116"},{"speaker":"木下委員","kind":"質問・要望","question":"事情はわかりました。ただ、民生委員法第４条で、市町村長の意見を聞いてこれを定めるとなっているわけですから、実情というのを、都の部署でちょっとわからない部分があるんじゃないかなと思いますので、要望として都に対して強く働きかけをお願いしたいと思います。続きまして、介護のほうに移らします。これはもう負担がどんどん上がっていってしまう、目に見えていますよね。","respondent":"早津高齢福祉課長","answer":"品川区の最大の特徴は、ケアプランを作成するのが在宅介護支援センターという、サービス事業者とは独立した組織ということで、構造的にいいますと、品川区のこのシステムというのは不正受給が非常に発生しにくいシステムだというようなことになります。","voiceIndex":280,"id":"exchange-117"},{"speaker":"木下委員","kind":"質問","question":"品川区としては不正がないというふうにお聞きしましたので、これからもそういうのをきちっと監視していただきたく、お願いしまして終わらします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":282,"id":"exchange-118"},{"speaker":"田中委員","kind":"質問・要望","question":"この背景としては住宅施策、中堅ファミリー層対策が進んでいるとか、またまちづくり事業の一つの成果として、品川区内に特に中堅ファミリー層の方々が移住してきているといった背景もあろうかと思いますが、０歳から９歳児が増えたことで少子化対策の観点からすると、この部分だけでよしとされてはいないと思いますが、昨日そのようなニュアンスの議論がありましたので。","respondent":"榎本行財政改革担当課長","answer":"そういった意味で、今回の乳幼児医療費につきましても１２歳まで広げるという部分、それから教育改革の部分で、さらにその年代層の部分についてもいろんな対策を打つことによって品川区からの転出を防いで、長く品川区に子育て世代がいられるような形にもっていくという考えです。","voiceIndex":284,"id":"exchange-119"},{"speaker":"田中委員","kind":"質問・要望","question":"一つは教育資金であり、住宅資金であり、老後の資金だと。そういう観点からも、さまざまな施策を進めるべきではないかというふうに考えておりまして、単なる保険料が高いだ、安いだ、手当があるなしという観点だけではなくて、総合的な視点から施策を遂行すべきだと思っているんですが、その辺はどのような意識を持たれてさまざまな施策を遂行されているのか、お聞かせをいただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"それで、かなり次世代育成行動計画というのは、地方自治体にも課せられていますけれども、企業、それから雇い主である自治体、それぞれの立場でのいろんな課題を解決していかなければならないという形になっておりますので、その中で何が一番少子化のために役立つのか。","voiceIndex":286,"id":"exchange-120"},{"speaker":"田中委員","kind":"質問・要望","question":"まさに平成１６年度は計画をするですが、ぜひ次世代育成支援体制を十分確立いただきまして、万全な対応を取っていただきたいと思います。午前中も我が党の鈴木真澄委員からの質問がありました乳幼児医療費助成、これは９０％の所得制限を行っている。小さければ小さいほど受診率が高いわけですが、徐々に成長していくにあたって病院にかかる率は低下しているという中で、なぜ今回小学校６年生まで広げたのか。","respondent":"辻田児童課長","answer":"小学校６年生まで考えた背景ですけれども、今般児童手当が小学校３年生まで年齢引き上げをされました。従来から見ますと、児童手当の年齢と乳幼児医療の年齢が大体一致しているということです。","voiceIndex":288,"id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほどの期待として教育費を浮かすんだと、またそれを子育てを楽しんでもらう、実感してもらうほうに回してもらいたいということなんですが、この医療費が下がる分、区の皆さんの予測として、じゃそれぞれのご家庭でどういったものに支出をしようと予想されているのか、また浮いた分をどういったものに回してもらいたいと期待をされているのか、その辺の考え方をお聞かせいただきたいと思います。","respondent":"辻田児童課長","answer":"今後、来年の１月から実施するわけですけれども、その状況をつぶさに私どもは見ていきたいという具合に考えております。それから、教育費ですけれども、別に教育費ということに限って言ったわけではございません。","voiceIndex":290,"id":"exchange-122"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ、その最後の部分の、この事業を行った中で、要は浮いた分を何に使うかは、間接的に言えば補助金から生まれたお金だと思いますので、その使われ方の動向、また人口がどういう形で増減があるのか、定着がどうあるのか、ぜひその辺を十分今後の動向を調査していただいて、今回の補助金のあり方の検証を引き続きしていただきたい。","respondent":"高橋区長","answer":"そのように、教育費につきましても、塾に通わなくてもすまいるスクールでそれが補えないだろうかと、そういうような観点から、教育費の削減が少しでもあるようにというふうなことで、すまいるスクールを各学校全部でやるような予定にしているわけです。","voiceIndex":292,"id":"exchange-123"},{"speaker":"山路委員","kind":"質問・要望","question":"もう１点は、今年の１月１５日に臨海斎場がオープンしまして、それに伴った授産メニュー開発検討事業ということでずっと進めてこられまして、非常に障害者の方に夢を持っていただいた事業ではないかと思ってきたんですが、その葬祭用品というんですか、骨壺、ほかにもいろいろ製品があると思うんですが、その辺についての現在の状況を聞かせていただきたいと思います。","respondent":"中川原福祉事業部副参事、日下部障害者福祉課長","answer":"そこで、今福祉ショップテルベの見直しが始まりまして、売れるものをつくる。そして、自分たちで売って生活費を稼ぐという、作業訓練の域を出まして、そういった取り組みを開始しようということで今頑張っております。２点目の葬祭用品の現状です。おかげさまでいろいろ関係各方面のご理解、それからご支援をいただきまして、昨年の１２月から福祉工場の製陶工場が竣工し、本格稼働いたしました。","voiceIndex":295,"id":"exchange-124"},{"speaker":"山路委員","kind":"質問・要望","question":"まちの商店街の障害者の会長からちょっと相談を受けたんですね。うちの商店街というのは非常に障害者の方が多く買い物に来る。私も会長として、このまちにない障害者の店をやってみたい。授産施設の品物を売ることも、ここは可能であると。このまちにない品物をこれから研究していきたいという、こういう相談があったんですけれども、何かいいアドバイスがあったら教えていただきたいと思います。","respondent":"中川原福祉事業部副参事","answer":"それを私どもの専門の職員がコーディネートしまして、それを何とか区民の自主的な活動として組み合わせるということで、双発的な活動の仕事をさせていただきたいということで考えてありますので、どうぞそういうお話をお寄せいただきたいと考えています。","voiceIndex":298,"id":"exchange-125"},{"speaker":"山路委員","kind":"質問・要望","question":"産業振興課も係わるかなと思ったんですが、強いて障害福祉者課長が障害者の立場でということでしたので、ここで相談をさせていただきました。骨壺、葬祭製品のほうは、軌道に乗ってきましたら、さらに最初の計画でありました、非常に厳しい道かと思うんですが、ＩＴのソフト開発の道まで何とか頑張っていただきたいと思いますが、その後の検討はどうでしょうか。","respondent":"日下部障害者福祉課長","answer":"ということで、今しばらくはこちらのほうに一生懸命頑張らせていただいて、その辺で一定の目処が立った段階でＩＴの開発等についても検討を進めていきたいと、このように考えております。","voiceIndex":300,"id":"exchange-126"},{"speaker":"山路委員","kind":"質問","question":"ありがとうございました。どうぞよろしくお願いいたします。続きまして、成年後見センターの相談者の方が徐々に増えてきたように感じるんですね。これから、重要な問題にもなっていくかなと考えているわけなんですが、何件ぐらい相談があって、成立したといいますか、そういうのは幾つぐらいあるか聞かせていただきますでしょうか。","respondent":"中川原福祉事業部副参事","answer":"相談件数ですが、現在、月平均１６５件ほどの電話、来所相談があります。そのうち、いろいろ高齢福祉課に相談しまして後見に結びついたのが、今申立て決定したのが１４件で、申立て済みが９件です。","voiceIndex":302,"id":"exchange-127"},{"speaker":"山路委員","kind":"質問","question":"高齢者リハビリテーションシステム推進事業、これから最も重要になってくるんじゃないかと思っているわけですが、昨日は私どもの国会議員で健康センターを視察させていただきまして、部長にご案内もしていただいたと思うんですが、平成１６年のプレス発表にも載っておりますが、地域ごとに細かくやる会場というのが、これから課題になってくるんじゃないかと思いますが。","respondent":"早津高齢福祉課長","answer":"筋力向上トレーニングにつきましては、荏原南学童保育クラブ跡地を利用するというのが１カ所決定しておりまして、あと２カ所につきましては新年度に入ってから、適地等について検討を進めていきたいというふうに考えてあります。","voiceIndex":304,"id":"exchange-128"},{"speaker":"山路委員","kind":"質問・要望","question":"今、決まっているのは承知しているわけですが、きめ細かにもっともっと会場を増やして、地域の中でできるような体制を要望しておきます。先に行きます。","respondent":"日下部障害者福祉課長","answer":"そういったことで、非常にこの辺は日進月歩ですけれども、私どもとしましてもこういった機器の開発の状況等をしっかり踏まえながら、障害者の方に対しての、特にコミュニケーションの関係というのは非常に重要な要素でもありますので、どういう形で活用できるのかと。","voiceIndex":306,"id":"exchange-129"},{"speaker":"山路委員","kind":"質問","question":"これは日常生活用具に入っているのかどうか、教えていただけますでしょうか。","respondent":"日下部障害者福祉課長","answer":"残念ながら、まだ機器の開発ができて間もないということもございまして、日常生活用具の指定対象にはなってございません。","voiceIndex":308,"id":"exchange-130"},{"speaker":"山路委員","kind":"質問・要望","question":"今後、よろしくお願いいたします。続いて、視覚障害者問題の弱視、斜視という、昨年は色覚障害者の方に対する色覚バリアフリーということで、私も非常に医療と福祉の谷間にある制度で一般質問でお願いしたわけなんですが、今、弱視、斜視、これが非常に注目を浴びているわけですが、まず認識を聞かせていただきたいと思います。","respondent":"日下部障害者福祉課長","answer":"これに該当している場合につきましては、当然手帳交付の対象になってまいりますけれども、ただ一般的に弱視の方あるいはこれと関連する斜視の方につきましては、その程度にもよりますが、その基準を満たさない場合には、当然のことながら手帳の交付対象にはなっていないと。","voiceIndex":310,"id":"exchange-131"},{"speaker":"山路委員","kind":"質問","question":"厚生労働省の国の基準には補助制度があるんですね。地方自治体にはないということで、何件かの地方自治体もやっているわけなんですけれども。医者のほうでも乱視、近視とよく間違う。これが今非常に注目を浴びているわけですけれども、これに対する支援、これも今後考えてもいいんじゃないかと思いますけれども、どのようにお考えでしょうか。","respondent":"日下部障害者福祉課長","answer":"先ほど申し上げましたように、具体的に身体障害者の指定の基準に合致をしていれば、それに合った形での、例えば補装具であるとか、日常生活用品の提供がされますけれども、これに該当しない場合には、基本的にそういった対象になっていないというのが現状ですが、今回弱視。","voiceIndex":312,"id":"exchange-132"},{"speaker":"須貝委員","kind":"質問・要望","question":"こんなところから、今日特養ホームを利用している方から、生涯このホームで暮らしたいという要望の人がかなり出ているというお話を聞いております。要は、ご自分の生涯をこのホームで過ごしたい。その辺、こういう事業の考え方としてどうなんだろうかということを、考え方をお知らせ願いたいのと、また働きかけられるのかという、その実情のところをご答弁をお願いいたします。","respondent":"早津高齢福祉課長","answer":"区内の特養ホーム、基本的には終の棲家にということで、最後まで頑張るというような形での運営に努めているところですが、すべての方についてそれができるかといいますと、現在の特養ホームの配置基準ですとか、あるいは介護体制、それからご本人の急変した医療の必要性。","voiceIndex":315,"id":"exchange-133"},{"speaker":"須貝委員","kind":"質問","question":"済みません。ちょっと聞き漏らしたかと思うんですけれども、現在、特養ホームで看取りといいますと、最後はご病気になられると思うんです。痴呆もあるかと思いますけれども、肉体的に。最後まで看取るという特養ホームというのは、何箇所ぐらいあるんですか。","respondent":"早津高齢福祉課長","answer":"これは各法人が運営しておりまして、その運営法人の中でのケアに対する考え方というものがかなり出てきているのもあろうかと思います。","voiceIndex":317,"id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"その方がねたきりかどうかもわからない。このような情報不足というんですか、その辺を非常に私は危惧するところなんですね。そして３人の協力者が必要だと。二つお伺いしたいと思います。今後、大まかな情報ですね。緊急通報システムの条件枠を広げるか、またはこのシステムの手続等を、行政のほうでもっと積極的に取り入れられるように動いていただけないか、この２点についてお伺いしたいと思います。","respondent":"新美保健高齢事業部長","answer":"ただいまのご質問ですが、向こう三軒両隣の方々は、やはり当然通常のおつき合いで情報をお持ちなケースというふうに私ども考えておりまして、地域におけるケアはふれあいサポート活動のように、一定の組織とルールの中でどれだけ地域がひとり暮らしや要介護の方を助けられるか。","voiceIndex":319,"id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"先ほどの特養ホームですか、これもやはり今後２４時間医療が係われるような仕組みを国のほうに要請していただいて、品川区もつくっていただければありがたいなと、それが第１点。第３点、乳幼児・小学生医療費助成事業なんですけれども、先ほどから何人かの委員からお話しがありますけれども、所得制限ですか。今回の仕組みに対しては、私はすごいいい仕組みだなと思って感謝しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":321,"id":"exchange-136"},{"speaker":"本多委員","kind":"質問・要望","question":"２１３ページの保育園運営費について、保育料の改定につきましてご質問いたします。受益者負担、当然の方向だと考えています。保育に要した費用については、その費用の全部または一部を徴収することとなっています。」となっておりますけれども、この「全部または一部」の範囲につきまして、例えば政令指定都市など例を挙げて教えていただきたいと思います。","respondent":"金子保育課長","answer":"その意味で、私どもは特別区全体とほぼ同じような保育料ですので、やはり特別区あるいはそのあたりで非常に低い保育料を設定してきたという経過があると考えています。私どもはそういう経過を踏まえた上で、今回９％の引き上げという改定案をご提案を申し上げているわけです。","voiceIndex":323,"id":"exchange-137"},{"speaker":"本多委員","kind":"質問・要望","question":"品川区の今回の改定の階層区分につきまして、現行の階層区分の２６そのものの考え方と、Ａ、Ｂは変わりませんけれども、２６のそれぞれのアップ率に対してご説明いただきたいと思います。第２子以降の基準についても教えていただきたいと思います。","respondent":"金子保育課長","answer":"３点ほどのお尋ねかと思います。階層区分についての考え方ですけれども、いわゆるＡＢ階層といいますけれども、生活保護世帯をＡ階層としております。その次がＢ階層で、前年度区民税の非課税世帯というふうにしております。","voiceIndex":325,"id":"exchange-138"},{"speaker":"本多委員","kind":"質問・要望","question":"この区分そのものは変わらないということで、アップ率なんですけれども、平均で ９.２％ということなんですけれども、国基準に対してはやはり階層区分によってはばらつきがあるというところで、受益者負担ということでは、方向性はいいと思うんですけれども、受益者全体の公平性というところではどうなのかなと思うんですけれども、改めてその点について教えていただきたいと思います。","respondent":"金子保育課長","answer":"先ほども答弁で申し上げましたとおり、児童福祉法で規定しています保育料の考え方でも、家計に与える影響を考慮してというふうにあります。","voiceIndex":327,"id":"exchange-139"},{"speaker":"本多委員","kind":"質問","question":"次に納付が困難な場合というところで、状況に応じて保育料の減額という制度が今までありました。災害に遭った方ですとか、５項目ぐらいあると思うんですけれども、その制度はそのままということでよろしいでしょうか。","respondent":"金子保育課長","answer":"委員ご指摘のとおり、納付が困難な場合、主なもので５項目、ほかにも若干ありますが、この制度については変わりなくそのまま維持する考えです。","voiceIndex":329,"id":"exchange-140"},{"speaker":"本多委員","kind":"質問・要望","question":"１０分の１０で来る委託のものとか、そういったものは省きまして、区の財源で用いるという事業については、この部分は本当に高いなと考えていますし、また本当に質の高い保育サービスの受益者という立場で、子育て支援策を受けるということで、金額だけではなくて制度をしっかりとお伝えすれば、どなたにでも明らかにわかりやすく納得をしていただけるものだと思うんですけれども、その辺につきまして。","respondent":"金子保育課長","answer":"委員ご指摘のとおり、その辺のところも十分周知の一つとしていくとともに、例えば先ほど部長が申し上げましたとおり、０歳児では月当たり５３万５,０００円かかっているにも係わらず、今回の改定で最高の保育料で６万２,８００円。","voiceIndex":331,"id":"exchange-141"},{"speaker":"本多委員","kind":"質問・要望","question":"参考までにちょっとご意見をいただきたいんですが、昭和４０年に三ツ木保育園が開園しましてから、それ以来保育園が増設されまして、昭和４０年代からそういうニーズが高まってきたというところで、やはり料金改定というものですから、いろんな見方をしなければいけないと思いまして、直接比較にはならないと思うんですが、世の中の物価の変遷につきまして、区役所から発行した資料をちょっと見ているんです。","respondent":"小沼福祉事業部長","answer":"ちなみに、これは自慢になることではございませんけれども、前回の改定は昭和５９年ですが、確かそのときには１３年間、結果的に据え置いてしまったような状況というようなこともありますので、私たちもそういう点も踏まえて。","voiceIndex":333,"id":"exchange-142"},{"speaker":"本多委員","kind":"質問・要望","question":"保育のニーズの多様化、就学前児童教育、福祉のさらなる充実を図りつつ、園整備の適正配置などを視野に入れまして、園の運営は受益者負担の方向ということなんですけれども、経営主体の多様化につきまして、今後の方針などはどのような方向なのか教えていただきたいと思います。","respondent":"金子保育課長","answer":"そういう意味では、個別のケースに応じて、さまざま検討していきたいというふうに考えてあります。","voiceIndex":335,"id":"exchange-143"},{"speaker":"本多委員","kind":"質問・要望","question":"どうぞ本当に充実した保育をよろしくお願いしたいと思います。１９５ページの高齢者クラブにつきまして教えていただきたいと思います。超高齢化時代を迎えまして、高齢者が増えております。しかし、ある高齢者クラブのお話を伺いました。というのは、やはり世話焼きさんと言うんですか、会長ですとか、世話焼きさんが相当いろいろとご苦労されていると思うんです。","respondent":"蓼沼高齢事業課長","answer":"そういった中では、例えば町会との関係を円滑に連携が保たれているところとそうでないところでは、クラブの活動の活発化状況も違っているというような状況がありますので、一つには町会との連携を深めていくというようなことを一つの解決には至らないかもしれませんけれども。","voiceIndex":337,"id":"exchange-144"},{"speaker":"山村委員","kind":"質問","question":"先ほどの質問の中でお金がかかるので、子どもを産む産まないという話があったと思うんですが、先輩たちの世代の話ではなくて、私の世代のことを思いますと、お金を自分のために使いたい若者が多いものですから、子どもにお金を使いたくないという意味で、お金がかかると言っている若者もいるということをまず頭の中に入れていだければと思います。私は違うんですが。","respondent":"金子保育課長","answer":"そういった事業の性格、またその事業の全体経費、そのほかその事業に対する特定財源の割合、こういった全体的に総合的に判断して、受益者の負担をどの程度設定するのが適切かと、個々的に判断するのが一番肝要なところではないかというふうに考えてあります。","voiceIndex":340,"id":"exchange-145"},{"speaker":"山村委員","kind":"質問","question":"本当に子どもを育てるための福祉なのか、仕事をするための福祉なのかというところの観点をとらえて、今後も頑張っていただければと考えています。次に１９８ページの心身障害者福祉費のことについてご質問したいと思います。障害児童と普通児童との交流は、現在どのようなふうになっているのか教えていただけますでしょうか。","respondent":"日下部障害者福祉課長","answer":"障害を持った児童と健常児童との交流ですけれども、一般的に申し上げますと、例えば保育園においても障害児保育ということで進められておりますし、例えば学校に上がれば学校において障害児の皆さん方も普通学級に入っていらっしゃるケースもある。","voiceIndex":342,"id":"exchange-146"},{"speaker":"山村委員","kind":"質問","question":"今後はもっと増やしていただければと思うんですが、最近は２０人に１人ぐらいが学習障害、ＬＤですか。４０人に１人がＡＤＨＤ、多動性障害と言われる児童がいるというふうに新聞に載っておりましたが、そういう児童を受け入れるために、一般の学校の教室とかで工夫されていることがあるんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":344,"id":"exchange-147"},{"speaker":"山村委員","kind":"質問","question":"かかりつけ医ということなんですが、薬剤師とか薬局、薬のことに関しては、これとどういうふうに絡んでいく予定があるのか、考えられているのか教えていただければと思います。","respondent":"田中健康課長","answer":"いわゆるかかりつけ薬局といいますか、そういうお話というのは先日の一般質問でもいただいておりますけれども、品川区においてまだかかりつけの薬局という部分までは、そういう意味での考え方としてしっかりしたものがないのが状況です。","voiceIndex":349,"id":"exchange-148"},{"speaker":"山村委員","kind":"質問","question":"確かに、診断は医師ですが、その後の治療で大部分は薬に頼る部分がありますので、逆に言えばかかりつけの医師というのも重要だと思うんですけれども、そういう考え方で言えば、かかりつけの薬局ですとか、そういう考えもあるんじゃないかと思うんですが、どうでしょうか。","respondent":"田中健康課長","answer":"例えば介護のいろんな相談をつなぐための身近な相談窓口という意味合いでの機能というのは、これから十分私どもは取り組むべきフィールドとしては考えられるというふうに思ってあります。","voiceIndex":351,"id":"exchange-149"},{"speaker":"山村委員","kind":"質問・要望","question":"どうしてもお医者さんを選ぶ方が多いと思うので、そうするとお医者さんによって薬が変わると、また困るということもあるんじゃないかと考えています。とりあえず、これは要望ということで、よろしくお願いいたします。次は、１９５ページのしながわ出会いの湯事業について、どのようなことをやられているのか教えていただければと思います。","respondent":"蓼沼高齢事業課長","answer":"これにつきましては区内の公衆浴場を活用して、６５歳以上の高齢者の方が毎週木曜日にお楽しみプログラムと言っておりますけれども、カラオケですとか健康体操を楽しんだ後に無料で入浴をしていただくという事業です。","voiceIndex":353,"id":"exchange-150"},{"speaker":"山村委員","kind":"質問","question":"そうしますとこの事業に対する補助だと思うんですが、今後もこのほかに銭湯を地域のふれあいの場というか健康面において、どのように活用していくかお考えがあったら教えていただければと思います。","respondent":"蓼沼高齢事業課長","answer":"今後どうやっていくかということにつきましては、例年何回か浴場組合の方との懇談会等を設けましていろいろ検討していますけれども、それにつきましては今後の課題というふうに考えてあります。","voiceIndex":355,"id":"exchange-151"},{"speaker":"山村委員","kind":"意見","question":"千代田区では銭湯が四つぐらいしかなくなってしまって、わざわざ区がつくったそうです。そういうこともありますので、今後銭湯をあまり潰さないように、鋭意活用していただいて補助をしていただければと思うんですが、今後どのように活用していくか、よろしいでしょか。","respondent":"田中健康課長","answer":"公衆浴場のお尋ねでございまして、高齢事業課のほうでいろいろ事業を行っておりますが、基礎的な意味で公衆浴場の経営の安定および振興ということで、健康課のほうからですけれども、設備等の整備補助金というものと、それから設備の資金の。","voiceIndex":357,"id":"exchange-152"},{"speaker":"山村委員","kind":"質問","question":"これからもどうか銭湯がなくならならないように、鋭意努力していただければと思っています。次は、２０２ページの社会福祉施設費のことでお聞かせいただければと思います。夫等に先立たれて年金生活で苦しい方が集まって、一つの部屋を借りて共同生活をするということなんですが、そういう場合だと区営住宅に入れないでのでしょうか、無理なんだとは思うんですが、その辺を教えていただければと思います。","respondent":"市岡企画財政課長","answer":"公営住宅法等の規定では世帯が単位になっておりまして、そういう任意のグループというのは対象になっておりませんので、現状ではそういう対象にはなりません。","voiceIndex":359,"id":"exchange-153"},{"speaker":"山村委員","kind":"質問","question":"グループリビングということは、住宅を確保するのが一番難しいそうなんですよ。そういう意味で、区が区営住宅などを活用してグループリビングにある程度補助を出すという考え方も、これからは一つのあり方としてあるんじゃないかと思うんですが、どのように思いますでしょうか。","respondent":"蓼沼高齢事業課長","answer":"高齢者の住宅施策はストックの活用ですとかやってありますけれども、今後そういうような選択肢が可能なのかどうか、総合的な高齢者住宅施策の中で、一つの課題として検討していきたいというふうに思います。","voiceIndex":361,"id":"exchange-154"},{"speaker":"宮崎委員","kind":"質問","question":"私は３８５ページ、４３３ページ、４５３ページ、国保、老健、介護について伺いたいと思います。初めなんですけれども、こういうケースがありました。豊町のアパートにひとり暮らししている女性なんですけれども、介護認定を受けてヘルパーの派遣、歩きが非常に困難で車いすも借りている。ところが、何にもできないと言われたんです。こういうケースは、何か対応というのはできないものなんでしょうか。","respondent":"早津高齢福祉課長","answer":"ただいまの具体的な似たようなケースが私のところにもかつてあったような気がいたしますけれども、極めて個別的なケースですし、その例では生活保護のケースワーカーとの連携の中で相談しつつ、対応しているというようなものがありました。","voiceIndex":365,"id":"exchange-155"},{"speaker":"宮崎委員","kind":"質問・要望","question":"この方は実際にどういうふうになったのか、結果ですね。どういうふうになったのかお聞かせいただきたいと思います。かつてそういう相談があったようだというふうなお話で、その後生活保護を受けていたので、それで回ったというお話だったんですけれども、その結果というのは、回したら知らないということなんでしょうか。","respondent":"早津高齢福祉課長","answer":"個別のケースですので、似たようなケースかもしれないし、正しいか正しくないかということはわかりかねるところでございまして、詳細なお答えというのはしかねるものです。","voiceIndex":367,"id":"exchange-156"},{"speaker":"宮崎委員","kind":"質問","question":"私は、今お話ししたように、せっかく介護保険を使ってヘルパーと車いすの貸与を受けているわけですね。ところが、これが使えないんですよ。本人は例えば火事になったらどうなんだと心配しているんだけれども、ところがケアマネージャーは「大家さんに言ってくれ」の一点張りだったということなんですよね。手すりをつけたんですね。ですから、私は結果どうなったのかということを聞いているんです。","respondent":"早津高齢福祉課長","answer":"再三になりますけれども、個別のケースのことで、またいろいろ当事者の情報というのもあろうかと思います。委員からのご発言を受けて、こうであるというようなことは誤解を招きかねないと思いますし、この場での発言は控えさせていただきたいと思います。","voiceIndex":369,"id":"exchange-157"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、この点を再度伺いたい。ちょっと質問を変えます。私は老健施設だとか、区のほうはグループホームですとか、ショートステイとか、そういうお話がありましたけれども、この考え方なんですけれども、どういう負担を求めていくことなのかも含めて、どういうふうに考えているのかも含めてお伺いしたいというふうに思います。併せて、どの程度の施設を考えておられるのかお伺いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":371,"id":"exchange-158"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ですから、非常にこれについては怒っています。跡地の利用については、最初に聞いたように、いつどういうふうに決めるのかというところを併せてもう１回お伺いしたい。例えば、今待っている方々が、具体的にショートステイとかデイホームとか、利用がどのぐらい増える、そういう目標を持ってつくろうとしているのかどうなのか、目標かあればぜひその点もお聞かせいただければと思います。","respondent":"高橋区長","answer":"ああ、なるほどなという思いをいたしました。品川区も今そういう方向に入りつつあるわけでございまして、そういう方向をこれからも在宅介護をより伸ばせていくように、またそれをより補完をさせていかれるような施策に重点を置いていきたいと考えています。","voiceIndex":374,"id":"exchange-159"},{"speaker":"宮崎委員","kind":"質問・要望","question":"それと、区内で民間のいわゆる有料老人ホーム等をつくられてきているやに聞きますけれども、この動きはどうなのか。そして、あと特別養護老人ホームについては、部長もかなり２３区ではトップクラスだというふうにおっしゃっていますけれども、私どもの計算では２３区で計画も含めて大体１８番目というふうに思っておりますけれども、何番目というところの認識はありますか、お伺いしたいと思います。","respondent":"高橋区長、早津高齢福祉課長","answer":"都南病院の問題について、具体的な計画はですけれども、今、あの土地が買えるか買えないかわからないわけですから、買える見通しが立ちましたら、具体的な計画を立てていきたいと思っています。ケアマネージャーの権限としては、ノーです。","voiceIndex":376,"id":"exchange-160"},{"speaker":"宮崎委員","kind":"質問・要望","question":"一番の出口のところ、外へ出るところが出られないんですから、だから私はこだわって聞いております。今回の値上げは非常に大きな値上げの計画なんですけれども、資料によりますと年収３００万円で４人世帯のところは、今回１５万１,０００円の保険料になる。例えば、１０年前はどうだったのかと、同じモデル世帯で三つの収入区分のところの保険料を教えていただきたいというふうに思います。","respondent":"太田保険年金課長","answer":"ただ、国民健康保険に加入されている方は区民の中の３分の１強の数字ですので、国民健康保険に加入されている方だけが厳しい状況であるということではないというふうに認識をしています。","voiceIndex":379,"id":"exchange-161"},{"speaker":"宮崎委員","kind":"質問","question":"非常に痛いという声があちこちから聞かれております。昨年も伺いましたけれども、滞納が非常に多くなっている中で、特に病気だとか、倒産だとか、そういう経済的な理由による滞納が非常に増えてきているというふうに思います。ここで１点聞きたいんですけれども、今短期証はどういうふうに発行されてきているのか、四、五年にわたっての数がわかったら教えていただければというふうに思います。","respondent":"太田保険年金課長","answer":"去年の１０月で２年証の更新時期を迎えましたので、新たに短期証の該当される方等が出ましたので、４月で６,８００件ほど、昨年の１０月で５,７００件です。","voiceIndex":381,"id":"exchange-162"},{"speaker":"宮崎委員","kind":"質問","question":"本当に短期証も発行がぐっと増えているというふうに感じます。国庫補助も８４年には確か４５％だったものが、現在は３８.５％というふうになっております。東京都も今回減っておりますが、最後に伺いたいのは、国とか東京都に対しての区の対応といいますか、ぜひ増やせというふうに言ってほしいんですけれども、その辺の考え方を最後に聞いておきたいと思います。","respondent":"太田保険年金課長","answer":"国庫負担の問題については、従来から私ども区長会から国に対して５０％の補助をしてほしいということでの要請はしています。なお、東京都につきましては、東京都が独自に施策を展開している部分のペナルティの項目補助ですので、一般的な補助ではございません。","voiceIndex":383,"id":"exchange-163"},{"speaker":"堺委員","kind":"質問・要望","question":"２点目は、２１７ページにあります児童福祉施設耐震診断、７,０５１万２,０００円計上されておりますが、先般私どもも区長に避難場所にも指定されている小・中学校をはじめ、福祉施設や医療施設などの耐震性向上のための改修事業等を促進することということを含めまして、先般要望してきたところですが、この事業の目的あるいは事業内容につきまして、簡単に教えていただければと思います。","respondent":"蓼沼高齢事業課長、辻田児童課長","answer":"新就業システム推進事業の経費です。主なものといたしましては、まず人件費で、１人当たり３６０万円の４人分です。それと事業費が３６０万円が主な内容です。内容的には、建物の耐震改修の促進法に関する法律に合わせた形での診断ということで、私どものこの金額では実施施設３４、保育園と児童センター、保育園の単独施設、保育園、児童センター、その他の複合施設９カ所すべてで３４カ所です。","voiceIndex":386,"id":"exchange-164"},{"speaker":"堺委員","kind":"質問","question":"耐震診断につきましては、わかりました。これは事業内容あるいは事業目的に沿った形で実施されるわけですが、実施時期は大体いつ頃を想定しているんでしょうか。","respondent":"蓼沼高齢事業課長、辻田児童課長","answer":"職員の方たちの経歴等ですけれども、中にはシルバー人材センターの会員の方であったり、あるいは区内の企業所のＯＢの方であったりという方たちです。実施ですけれども、大体６月から始まりまして、何とか８月末までに終わらせたいという具合に考えているところです。","voiceIndex":389,"id":"exchange-165"},{"speaker":"堺委員","kind":"質問・要望","question":"サポしながわのほうですが、着実な成果が上がっていると、どなたかの委員のご質問の中でお答えがございました。そうしますと、今からそれに耐え得るというんですか、体制を十分整えておかなきゃいけないかなと、こんな気がするんですが、将来についての対策といいましょうか、その辺はどのようにお考えになっているのか教えていただきたいと思います。","respondent":"蓼沼高齢事業課長、辻田児童課長","answer":"いずれにいたしましても、雇用者の雇用安定法の改正も予定されているですので、シルバー人材センターと含めて、今後需要にどういうふうに的確にこたえていくかは、十分に検討してまいりたいというふうに考えてあります。３４施設を２カ月でできるかですけれども、診断にあたる会社を複数にすれば、そういうことで可能かなという具合に考えて、何しろ現に使っている施設なので、なるべく短期間にあげていきたいという具合に考えております。","voiceIndex":392,"id":"exchange-166"},{"speaker":"堺委員","kind":"質問・要望","question":"サポしながわのほうでも、シルバー人材センターと連携を取って、的確に対応できるようにしていくですから、ぜひそういう方向で取り組んでいただきたいと、このようにお願いをしておきたいと思います。１カ所大体２５０万円かかる。短期間でできるですので、やはり小さい子どもがお使いになる児童福祉施設ですから、何かあってからでは遅いわけでありますから、そういう面では早急にお願いしたい。","respondent":"市岡企画財政課長","answer":"耐震補強の工事については、近年非常に技術が進んでおりまして、いろいろな新しい技術で簡易なもの、短期間でできるもの、いろいろな手法がありますので、その辺も十分研究して対応していきたいというふうに考えてあります。","voiceIndex":395,"id":"exchange-167"},{"speaker":"堺委員","kind":"質問・要望","question":"最後に、今お話しがございましたので安心をしたんですが、結果が確かに出ないとわかりませんが、緊急性のあるものについては、補正予算を組んででも速やかに対処していただきたい、このことを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":397,"id":"exchange-168"},{"speaker":"伊藤委員","kind":"確認","question":"私は２１３ページの保育園に関連して質問をします。二つ、まず先に確認の質問でありますが、品川区が展開しております子育て事業というものは、品川区民全体を当然対象とするわけであって、決して保育園に入っている子どものみとか、そのほかの子どものみに施策が集中してはいけないと思いますが、いかがでしょうかというのが一つ。","respondent":"金子保育課長","answer":"２点のご質問です。子育て支援策ですが、委員ご指摘のとおり保育園に限らず、在宅の子育ての家庭も視野に入れて、全体的に考えていくもの、実施していくべきものというふうに考えてあります。それから、国・都の補助のあり方は、やはり時代に応じて変わってくるものだと思います。","voiceIndex":399,"id":"exchange-169"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今回の保育料の改定が９％の改定でも１億１,０００万円ですから、改定があったとしてもこの延長夜間保育にかかる人件費とコストを支えることはできないことは明確なんですが、そのことの確認を一つ。平成１６年度のみで結構ですから教えていただきたいんですが、いかがでしょうか。","respondent":"金子保育課長","answer":"すべての経費をトータルして計算する。つまり細かな消耗品、備品、光熱水費を計算するというのは、非常に難しいものでありますが、延長夜間保育についてのみは職員の増配置をしていますので、その分だけは計算できるかと思います。","voiceIndex":401,"id":"exchange-170"},{"speaker":"伊藤委員","kind":"確認","question":"定員弾力化、ほかも含めれば、おそらくは、予算ベースは ５,４１７万円ですけれども、これの数倍から数十倍まではいかないでしょうけれども、コストがかかっていることは事実、そのことを確認させていただきました。それから、品川区が高い保育事業を維持するために、独自に投入している運営費加算額は幾らかということを、数字ですからすぐ出てくると思うんですがお教えください。お願いいたします。","respondent":"金子保育課長","answer":"国徴収金基準額に基づいて区がその保育料の負担部分を肩代わりしている、これを金額にしますと９億２,２００万円ほどになります。さらに、運営費の加算部分として区が負担している部分は５１億５,８００万円というふうな数字になってあります。","voiceIndex":403,"id":"exchange-171"},{"speaker":"伊藤委員","kind":"質問・要望","question":"今、数字が大分出てまいりました。やっぱり、これはこの情報化の時代ですから、これから利用する保護者の皆さんに端的に教えていただきたい。９.４％の負担をいただいていることは事実ですけれども、そのかわり残りの九十何％ですか、それが全部税金なんだよと、それはきちんとご説明していただきたいんです。","respondent":"金子保育課長","answer":"先ほども本多委員のところでご答弁申し上げましたが、４月以降、私どもは保育料の改定について周知をしていきたいと考えておりますが、委員からさまざまご意見をいただいているとおり、今の保育料というものがどういう仕組みになっているのかということと。","voiceIndex":405,"id":"exchange-172"},{"speaker":"伊藤委員","kind":"質問・要望","question":"品川区もおそらくそういう背景の中で品川区は高い保育所を展開しているから、結果として負担を求めていくんだという姿勢で、この方向を打ち出してきたと思いますが、区長にぜひ一言いただきたいのが、横並びの行政展開から今度は競争の時代に入ってくる中で、品川区の自己決定、自己責任の中で今後の保育行政、それからこれからの行政をどう担っていくかということをご答弁をお願いします。","respondent":"高橋区長","answer":"そういうものを勘案しながら、品川区が独自で政策を実施できるもの、２３区が統一でなくて実施できるものにつきましては、品川区なりの行政をこれからも続けてまいりたいと考えています。","voiceIndex":407,"id":"exchange-173"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=826#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":127591,"voices":409}}]);
